// JSZip is only used by the Admin bulk-HTML import screen — lazy-load on demand.
let _JSZipMod = null
const loadJSZip = async () => {
  if (_JSZipMod) return _JSZipMod
  let lastErr
  for (let i = 0; i < 3; i++) {
    try {
      const mod = await import('jszip')
      _JSZipMod = mod.default || mod
      return _JSZipMod
    } catch (e) {
      lastErr = e
      await new Promise(r => setTimeout(r, 400 * (i + 1)))
    }
  }
  throw lastErr
}
// Odia @font-face CSS with base64-embedded Noto Sans Oriya (400 + 700).
// Loaded lazily because the bundle is ~445KB — we only need it when
// rasterising a worksheet PDF through html2canvas/html2pdf.  Embedding the
// fonts directly in the captured HTML prevents Google Fonts network races
// (which caused Odia glyphs to render as tofu / blank pages on flaky links).
let _odiaFontsMod = null
const loadOdiaFontFaceCSS = async () => {
  if (_odiaFontsMod) return _odiaFontsMod
  try {
    const mod = await import('@/lib/odia-fonts')
    _odiaFontsMod = mod.ODIA_FONT_FACE_CSS || ''
    return _odiaFontsMod
  } catch (e) {
    console.warn('[odia-fonts] failed to load embedded fonts:', e?.message)
    _odiaFontsMod = ''
    return ''
  }
}
// Client-side PDF blob-size guard.  html2canvas can silently emit a mostly
// empty page (~ few hundred bytes of jsPDF chrome) when the capture
// container had zero height or the DOM was still loading.  Anything under
// ~1 KB is almost certainly a blank page, so surface an error instead of
// downloading a broken file.
const MIN_PDF_BYTES = 1000
const savePdfBlobOrError = (blob, filename) => {
  if (!blob || blob.size < MIN_PDF_BYTES) {
    toast.error('PDF appears blank — please retry. If this keeps happening, use the ⋯ menu → Print instead.')
    return false
  }
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  document.body.appendChild(a)
  a.click()
  setTimeout(() => { try { document.body.removeChild(a) } catch (_) {} ; URL.revokeObjectURL(url) }, 1500)
  return true
}
// ---------------------------------------------------------------------------
// PERF: Code-split heavy components + admin panels behind next/dynamic.
// These modules pull in Recharts, PDF renderers, WhatsApp campaign tooling,
// etc. and were adding ~500KB+ to the initial JS bundle for every visitor —
// even though most visitors never open the admin console or the Ajira paywall.
// dynamic() lazy-loads them on first render, so the initial page is smaller
// and TTI (time-to-interactive) improves noticeably on 3G/4G mobile.
//
// Chunk-loading self-heal: the loader wraps each import() with a small
// retry loop.  If the browser has a stale HTML page after a deploy (its
// bundled chunk hash is gone from the server), the second attempt still
// won't succeed — but the global chunk-error handler in /app/layout.js
// then triggers a one-time page reload to fetch the fresh HTML.
// ---------------------------------------------------------------------------
const _retryImport = (loader, retries = 2, delayMs = 400) => async () => {
  let lastErr
  for (let i = 0; i <= retries; i++) {
    try { return await loader() }
    catch (e) {
      lastErr = e
      if (i === retries) break
      await new Promise(r => setTimeout(r, delayMs * (i + 1)))
    }
  }
  throw lastErr
}
const _dyn = (loader, name) => dynamic(_retryImport(loader), {
  ssr: false,
  loading: () => (
    <div className="flex items-center justify-center py-10 text-xs text-muted-foreground">
      <span className="animate-pulse">Loading {name}…</span>
    </div>
  ),
})
