// ---------- Annual Lesson Plan data (Class 1-8 · month-wise chapters) ----------
import ANNUAL_PLAN_DATA from '@/lib/annual-lesson-plan.json'
// ---------- Foundational LO Codes (Balvatika/C1/C2) ----------
// Bundled so lesson-plan renderers can display the Competency Goal (DG) column
// without extra API calls.  Loaded lazily via require() to keep initial parse light.
import FOUNDATIONAL_LO_CODES from '@/lib/lo-codes-foundational.json'
// Build lookup maps once (module scope): by full id (BV3-PD-1.1.1) and by
// raw "code" per classCode (BV3 + "PD 1.1.1"). Value = { competency, description }.
const FOUND_BY_ID = new Map()
const FOUND_BY_CLASS_RAW = new Map()
for (const c of FOUNDATIONAL_LO_CODES) {
  FOUND_BY_ID.set(c.id, { competency: c.competency, description: c.description, domain: c.domainName })
  FOUND_BY_CLASS_RAW.set(`${c.classCode}|${c.code}`, { competency: c.competency, description: c.description, domain: c.domainName })
}
// Runtime cache — populated lazily via GET /api/lo-codes so we can resolve
// LEGACY codes (e.g. "M 214", "OD 101") that predate the foundational NCF-FS
// import.  Any renderer that shows DG/LO details should call `hydrateLoCodes()`
// on mount to make sure this map is populated before rendering.
const RUNTIME_LO_MAP = new Map()  // key: `${classCode||''}|${code}` → { competency, description, domain, code }
let _loCodesHydrated = false
async function hydrateLoCodes() {
  if (_loCodesHydrated) return
  _loCodesHydrated = true
  try {
    // Pull the entire LO code library once (typically <1k rows).  Safe / cached
    // by the browser HTTP cache anyway.
    const r = await api('/lo-codes?limit=5000')
    for (const row of (r?.items || r?.codes || r?.loCodes || [])) {
      const rawCode = String(row.code || row.id || '').trim()
      if (!rawCode) continue
      const compact = rawCode.replace(/\s+/g, ' ').trim()
      const cc = row.classCode || (row.class === 0 ? 'BV3' : row.class === 1 ? 'C1' : row.class === 2 ? 'C2' : '')
      const rec = { competency: row.competency || '', description: row.description || row.text || '', domain: row.domain || row.subject || '', code: compact }
      RUNTIME_LO_MAP.set(`${cc}|${compact}`, rec)
      RUNTIME_LO_MAP.set(`|${compact}`, rec) // fallback lookup w/o class
      // Also store by DB `id` (e.g. "BV3-PD-1.1.1", "M-101")
      if (row.id) RUNTIME_LO_MAP.set(`ID|${row.id}`, rec)
    }
  } catch { /* silent — falls back to bundled foundational data */ }
}

/**
 * Resolve the Competency Goal (ଦକ୍ଷତା ଲକ୍ଷ୍ୟ / DG) + LO details for a lesson period.
 * Returns { cgCode, cgText, loCode, loText } — every field falls back to '' on miss.
 *
 * Lookup order:
 *   1. Bundled foundational (FOUND_BY_ID / FOUND_BY_CLASS_RAW)
 *   2. Runtime API cache (RUNTIME_LO_MAP) — needed for legacy codes like "M 214"
 */
const getLoDetails = (loCodeId, className) => {
  if (!loCodeId) return { cgCode: '', cgText: '', loCode: '', loText: '' }
  const raw = String(loCodeId).trim()
  let hit = FOUND_BY_ID.get(raw)
  const s = String(className || '').toLowerCase()
  let cc = null
  if (/balvatika|sishuvatika|ଶିଶୁ|ବାଲ୍ୟ/i.test(s)) cc = 'BV3'
  else if (/class\s*[- ]?1\b|ପ୍ରଥମ/i.test(s)) cc = 'C1'
  else if (/class\s*[- ]?2\b|ଦ୍ୱିତୀୟ|ଦ୍ଵିତୀୟ/i.test(s)) cc = 'C2'
  if (!hit && cc) {
    const rawSpaced = raw.replace(/-/g, ' ').trim()
    hit = FOUND_BY_CLASS_RAW.get(`${cc}|${rawSpaced}`) || FOUND_BY_CLASS_RAW.get(`${cc}|${raw}`)
  }
  // Runtime cache — legacy codes like "M 214", "OD 101"
  if (!hit) {
    hit = RUNTIME_LO_MAP.get(`ID|${raw}`)
        || RUNTIME_LO_MAP.get(`${cc || ''}|${raw}`)
        || RUNTIME_LO_MAP.get(`|${raw}`)
        // Try normalized spacing variants
        || RUNTIME_LO_MAP.get(`${cc || ''}|${raw.replace(/-/g, ' ')}`)
        || RUNTIME_LO_MAP.get(`|${raw.replace(/-/g, ' ')}`)
        || RUNTIME_LO_MAP.get(`${cc || ''}|${raw.replace(/\s+/g, '-')}`)
        || RUNTIME_LO_MAP.get(`|${raw.replace(/\s+/g, '-')}`)
  }
  if (!hit) return { cgCode: '', subCode: '', cgText: '', loCode: raw, loText: '' }
  const rawCode = hit.code || raw.replace(/^(BV3|C1|C2)-/,'').replace(/-/g, ' ').trim()
  // "PD 1.1.1" → mainCode "PD-1", subCode "PD-1.1"
  //   • cgCode  = domain + first numeric segment ("PD-1")   → shown in DG column
  //   • subCode = domain + first two numeric segments ("PD-1.1") → shown alongside LO
  const parts = rawCode.match(/^([A-Z]{1,4})\s*([0-9]+)(?:\.([0-9]+))?/)
  const cgCode  = parts ? `${parts[1]}-${parts[2]}` : ''
  const subCode = parts && parts[3] ? `${parts[1]}-${parts[2]}.${parts[3]}` : ''
  return {
    cgCode,
    subCode,
    cgText: hit.competency || '',
    loCode: rawCode,
    loText: hit.description || '',
  }
}
const getCompetencyGoal = (loCode, className) => {
  const d = getLoDetails(loCode, className)
  return d.cgText || d.loText || ''
}

// --- Hindi-subject curriculum translation (CG / Competency / LO values) ------
// The SCERT-Odisha framework text is stored in Odia. For HINDI-subject lesson
// plans we translate just the CG/Competency/LO *values* into Hindi (codes stay
// unchanged) via the server /lo-codes/translate endpoint (Gemini + DB cache).
const _countScript = (s, re) => (String(s || '').match(re) || []).length
// A string is "Hindi" when it has Devanagari and is NOT dominated by Odia.
const _looksHindi = (s) => {
  const dev = _countScript(s, /[\u0900-\u097F]/g)
  const od = _countScript(s, /[\u0B00-\u0B7F]/g)
  return dev > 0 && dev > od
}
// Decide if a lesson belongs to a Hindi subject (name signal first, then content).
const isHindiLesson = (lesson, book, chapter) => {
  const label = `${book?.name || ''} ${lesson?.subject || ''} ${chapter?.name || ''}`
  if (/hind/i.test(label) || /हिंदी|हिन्दी|ହିନ୍ଦୀ/.test(label)) return true
  if (/odia|ଓଡ|english|ଇଂରାଜ/i.test(label)) return false
  let sample = `${lesson?.title || ''} ${(lesson?.learningOutcomes || []).join(' ')}`
  try {
    if (Array.isArray(lesson?.fiveE?.stages)) sample += ' ' + lesson.fiveE.stages.map(s => `${s?.teacher || ''} ${s?.student || ''}`).join(' ')
    else if (lesson?.panchapadi) sample += ' ' + Object.values(lesson.panchapadi).map(dv => `${dv?.teacherActivityText || dv?.teacherActivity || ''} ${dv?.studentActivityText || dv?.studentActivity || ''}`).join(' ')
  } catch {}
  return _looksHindi(sample)
}

/**
 * Return ALL LO code entries for a lesson period.
 * Combines:
 *   • Legacy/original codes (e.g. "M 214", "OD 101") that were assigned to the lesson
 *   • New foundational sub-Dakhyata codes (BV3-*, C1-*, C2-*) auto-aligned by monthly plan
 * Order: legacy first (top), foundational after (bottom) — matches user requirement:
 * "LO Code column re previous Existing Jaha prati lesson period re thila,
 *  seita bi rahiba with sub-Dakhyata LO Codes."
 */
const getAllLoEntries = (p) => {
  if (!p) return []
  const codes = Array.isArray(p.loCodes) && p.loCodes.length
    ? p.loCodes
    : (p.loCode ? [p.loCode] : [])
  const seen = new Set()
  const entries = []
  for (const raw of codes) {
    const key = String(raw || '').trim()
    if (!key) continue
    const uk = key.toUpperCase()
    if (seen.has(uk)) continue
    seen.add(uk)
    const d = getLoDetails(key, p.className)
    const isFoundational = !!d.subCode || /^(BV3|C1|C2)-/i.test(key)
    entries.push({
      raw: key,
      displayCode: d.loCode || key,
      subCode: d.subCode || '',
      isFoundational,
      text: d.loText || '',
    })
  }
  // Legacy first, foundational after — preserves teacher's familiar codes on top
  const legacy = entries.filter(e => !e.isFoundational)
  const foundy = entries.filter(e => e.isFoundational)
  return [...legacy, ...foundy]
}

// JSX renderer for the LO column (stacked list — codes only, DG is separate)
const renderLoStackJsx = (p, opts = {}) => {
  const { fontSize = '9pt' } = opts
  const entries = getAllLoEntries(p)
  if (!entries.length) return <span>—</span>
  return (
    <>
      {entries.map((e, i) => (
        <div key={i} style={{ fontFamily: 'monospace', color: e.isFoundational ? '#0f766e' : '#1a365d', fontWeight: 700, fontSize, marginBottom: 1 }}>
          {e.displayCode}
        </div>
      ))}
    </>
  )
}

// HTML-string renderer for the LO column (Word DOC exports)
const renderLoStackHtml = (p, opts = {}) => {
  const { fontSize = '9pt' } = opts
  const entries = getAllLoEntries(p)
  if (!entries.length) return '—'
  return entries.map(e => `<div style="font-family:monospace;color:${e.isFoundational ? '#0f766e' : '#1a365d'};font-weight:700;font-size:${fontSize};margin-bottom:1px">${e.displayCode}</div>`).join('')
}

// DG (ଦକ୍ଷତା ଲକ୍ଷ୍ୟ) stack: unique sub-Dakhyata codes derived ONLY from foundational
// entries (BV3-*, C1-*, C2-*).  Legacy codes never contribute to the DG column.
// Example: entries = [OD 101, PD 1.1.1, PD 1.1.2] → DG stack = ['PD-1.1']
const getDgStack = (p) => {
  const entries = getAllLoEntries(p)
  const seen = new Set()
  const dgCodes = []
  for (const e of entries) {
    if (e.isFoundational && e.subCode && !seen.has(e.subCode)) {
      seen.add(e.subCode)
      dgCodes.push(e.subCode)
    }
  }
  return dgCodes
}

const renderDgStackJsx = (p, opts = {}) => {
  const { fontSize = '9pt' } = opts
  const dgCodes = getDgStack(p)
  if (!dgCodes.length) return <span>—</span>
  return (
    <>
      {dgCodes.map((c, i) => (
        <div key={i} style={{ fontFamily: 'monospace', color: '#7c3aed', fontWeight: 700, fontSize }}>{c}</div>
      ))}
    </>
  )
}

const renderDgStackHtml = (p, opts = {}) => {
  const { fontSize = '9pt' } = opts
  const dgCodes = getDgStack(p)
  if (!dgCodes.length) return '—'
  return dgCodes.map(c => `<div style="font-family:monospace;color:#7c3aed;font-weight:700;font-size:${fontSize}">${c}</div>`).join('')
}

// Auto class-range subtitle for the home Unit Tests banner (reflects published classes).
const UnitTestRangeSubtitle = () => {
  const [range, setRange] = useState('')
  useEffect(() => {
    let alive = true
    fetch('/api/store/unit-tests/classes')
      .then(r => r.json())
      .then(d => {
        const nums = (d?.classes || []).map(c => parseInt(c.class, 10)).filter(n => !isNaN(n))
        if (alive && nums.length) {
          const od = n => String(n).replace(/[0-9]/g, x => '୦୧୨୩୪୫୬୭୮୯'[+x])
          setRange(`ଶ୍ରେଣୀ ${od(Math.min(...nums))}–${od(Math.max(...nums))}`)
        }
      }).catch(() => {})
    return () => { alive = false }
  }, [])
  return <div className="mt-1" style={{ color: '#3b2f05', fontSize: 13 }}>{(range || 'ଶ୍ରେଣୀ')} · ସବୁ ବିଷୟ · ପ୍ରତି ଅଧ୍ୟାୟ ୫ଟି ପରୀକ୍ଷା</div>
}

// ---------- API ----------
const api = async (path, opts = {}) => {
  const token = typeof window !== 'undefined' ? localStorage.getItem('em_token') : null
  const timeoutMs = opts.timeoutMs || 45000
  const maxRetries = opts.noRetry ? 0 : 1                    // one auto-retry on network error
  const method = opts.method || 'GET'

  // Perform ONE attempt (a single fetch with an abort-timeout).  Returns the
  // parsed JSON body on 2xx.  Throws a NETWORK error on transient failures
  // (dns/tls/timeout) so the outer retry loop can react.  4xx/5xx from the
  // server are treated as final and never retried.
  const attempt = async () => {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(new Error('timeout')), timeoutMs)
    let res
    try {
      res = await fetch(`/api${path}`, {
        method,
        headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(opts.headers || {}) },
        body: opts.body ? JSON.stringify(opts.body) : undefined,
        signal: controller.signal,
        cache: 'no-store',
      })
    } catch (fetchErr) {
      // "Failed to fetch" / AbortError land here — classify as network
      const isAbort = fetchErr?.name === 'AbortError'
      const err = new Error(isAbort
        ? 'The server took too long to respond. Please check your connection and try again.'
        : 'Network error — could not reach the server. Please check your internet and try again.')
      err.isNetwork = true
      err.original = fetchErr
      throw err
    } finally { clearTimeout(timer) }

    const data = await res.json().catch(() => ({}))
    if (!res.ok) {
      // Single-device login: backend says this token belongs to a session that was
      // replaced by a newer device login. Clear the token and broadcast so the app
      // can route to the login screen with a clear message.
      if (res.status === 401 && data?.code === 'SESSION_REPLACED' && typeof window !== 'undefined') {
        try {
          localStorage.removeItem('em_token')
          localStorage.setItem('em_session_kicked', '1')
          window.dispatchEvent(new CustomEvent('em:session-replaced', { detail: { message: data.error } }))
        } catch { /* non-blocking */ }
      }
      // 💎 AI Credit exhaustion — global handoff to purchase modal.
      // Any endpoint returning HTTP 402 with code=INSUFFICIENT_AI_CREDITS dispatches
      // a shared event that the App-level listener converts into an open Buy Credits
      // modal. We still THROW so the caller's try/catch can preserve form state.
      if (res.status === 402 && data?.code === 'INSUFFICIENT_AI_CREDITS' && typeof window !== 'undefined') {
        try {
          window.dispatchEvent(new CustomEvent('ai-credits:insufficient', {
            detail: {
              availableCredits: data.availableCredits ?? data.balance ?? 0,
              requiredCredits: data.requiredCredits ?? data.required ?? 0,
              zone: data.zone || null,
              type: data.type || null,
            },
          }))
        } catch { /* non-blocking */ }
      }
      // Soft-handle subscription/auth preview responses (locked lesson content)
      if (data && data.preview) return data
      const err = new Error(data.error || `Server returned ${res.status}. Please try again.`)
      err.status = res.status
      err.data = data
      throw err
    }
    return data
  }

  // Retry loop — only retries when the previous attempt failed with a NETWORK
  // error.  Server-side 4xx / 5xx / 401 errors are surfaced immediately so the
  // user isn't told to retry when their credentials are actually wrong.
  let lastErr
  for (let i = 0; i <= maxRetries; i++) {
    try { return await attempt() }
    catch (e) {
      lastErr = e
      if (!e?.isNetwork) throw e         // don't retry auth / validation failures
      if (i < maxRetries) {
        await new Promise(r => setTimeout(r, 800 * (i + 1)))   // small back-off before retry
        continue
      }
      throw e
    }
  }
  throw lastErr
}

// -----------------------------------------------------------------------------
//  📊 Offer analytics tracking (fire-and-forget, session-throttled)
//  Called by the banner (view), popup (view) and plan-card CTA (click).
//  Uses a per-tab session key + localStorage-based dedupe so we don't
//  double-count within a short window.
// -----------------------------------------------------------------------------
const _emSessionKey = (() => {
  if (typeof window === 'undefined') return 'ssr'
  try {
    let k = sessionStorage.getItem('em_offer_session')
    if (!k) { k = 'em_' + Math.random().toString(36).slice(2, 12) + Date.now().toString(36); sessionStorage.setItem('em_offer_session', k) }
    return k
  } catch { return 'anon_' + Date.now() }
})()

const trackOfferEvent = (offerId, event, planId = null) => {
  if (!offerId || !event) return
  if (typeof window === 'undefined') return
  try {
    // Client-side dedupe — cap to 1 view per offer per 30 min per browser
    if (event === 'view') {
      const key = `em_offer_view_${offerId}`
      const last = Number(localStorage.getItem(key) || 0)
      if (last && Date.now() - last < 30 * 60 * 1000) return
      localStorage.setItem(key, String(Date.now()))
    }
    const token = localStorage.getItem('em_token')
    fetch('/api/offers/track', {
      method: 'POST', keepalive: true,
      headers: { 'Content-Type': 'application/json', 'x-em-session': _emSessionKey, ...(token ? { Authorization: `Bearer ${token}` } : {}) },
      body: JSON.stringify({ offerId, event, planId }),
    }).catch(() => {})
  } catch { /* non-blocking */ }
}

// ---------- PDF helpers (html2canvas + jsPDF, true fit-to-page) ----------
// Renders one or more DOM elements as separate A4 pages where each element is
// captured, then scaled-to-fit the entire page (preserving aspect ratio).
// • No horizontal/vertical overflow — content always fits in one PDF page per element.
// • Multi-element callers get multi-page PDFs (one element = one page).
// • Works on mobile because we capture the element at its natural CSS size.
const downloadElementsAsPdf = async (elements, { filename = 'document.pdf', orientation = 'landscape', margin = 4 } = {}) => {
  if (typeof window === 'undefined') return
  const items = Array.isArray(elements) ? elements : [elements]
  if (!items.length) return
  const html2canvasMod = await import('html2canvas')
  const html2canvas = html2canvasMod.default || html2canvasMod
  const jsPDFMod = await import('jspdf')
  const jsPDF = jsPDFMod.jsPDF || jsPDFMod.default
  const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation, compress: true, putOnlyUsedFonts: true })
  const pageW = pdf.internal.pageSize.getWidth()
  const pageH = pdf.internal.pageSize.getHeight()
  const usableW = pageW - margin * 2
  const usableH = pageH - margin * 2
  for (let i = 0; i < items.length; i++) {
    const el = items[i]
    if (!el) continue
    // Save & temporarily remove margin/shadow that would pollute the capture
    const prev = { margin: el.style.margin, boxShadow: el.style.boxShadow, pageBreakAfter: el.style.pageBreakAfter }
    el.style.margin = '0'
    el.style.boxShadow = 'none'
    el.style.pageBreakAfter = 'auto'
    const canvas = await html2canvas(el, {
      scale: 2,
      useCORS: true,
      backgroundColor: '#ffffff',
      logging: false,
      letterRendering: true,
      windowWidth: el.scrollWidth,
    })
    // Restore inline styles
    el.style.margin = prev.margin
    el.style.boxShadow = prev.boxShadow
    el.style.pageBreakAfter = prev.pageBreakAfter

    // Compute fit-to-page (preserve aspect ratio)
    const imgRatio = canvas.width / canvas.height
    const pageRatio = usableW / usableH
    let finalW, finalH
    if (imgRatio > pageRatio) {
      // Image wider than page — fit by width
      finalW = usableW
      finalH = usableW / imgRatio
    } else {
      // Image taller than page — fit by height
      finalH = usableH
      finalW = usableH * imgRatio
    }
    const x = (pageW - finalW) / 2
    const y = (pageH - finalH) / 2
    if (i > 0) pdf.addPage()
    const imgData = canvas.toDataURL('image/jpeg', 0.95)
    pdf.addImage(imgData, 'JPEG', x, y, finalW, finalH, undefined, 'FAST')
  }
  pdf.save(filename)
}

// ---------- Export Settings hook (admin-controlled visibility of Print/PDF/Word + watermark) ----------
// Cached at module level so multiple components share one fetch per page-load.
let __exportSettingsCache = null
let __exportSettingsPromise = null
const fetchExportSettings = () => {
  if (__exportSettingsCache) return Promise.resolve(__exportSettingsCache)
  if (__exportSettingsPromise) return __exportSettingsPromise
  // Fetch legacy generic settings AND the new lesson-plan-specific security
  // config in parallel.  Merged with AND-semantics — if either says OFF, the
  // button hides.  Lesson-plan security config also carries `allowPrint`,
  // `pdfPassword`, `oneTimeDownload`, etc. which the download flow uses.
  __exportSettingsPromise = Promise.all([
    fetch('/api/settings/public').then(r => r.json()).catch(() => ({})),
    fetch('/api/document-security/lesson-plan/config').then(r => r.json()).catch(() => ({})),
  ])
    .then(([legacy, lpsec]) => {
      const cfg = lpsec?.config || {}
      __exportSettingsCache = {
        // Legacy fields — kept UNCHANGED for non-lesson-plan document types.
        // The merge below applies ONLY to lesson-plan PDF + Word buttons.
        showPrint: legacy?.showPrint !== false,
        showPdf: legacy?.showPdf !== false && cfg.allowPdf !== false,
        showWord: legacy?.showWord !== false && cfg.allowWord !== false,
        showWatermark: legacy?.showWatermark !== false,
        // 🏫 Multigrade Lesson Plan — dedicated PDF-download visibility.
        // Admin toggle only affects the Multigrade "Download PDF" button.
        multigradePdf: legacy?.multigradePdf !== false,
        // New lesson-plan security fields — used by lesson-plan download UX only
        lpAllowPdf:    cfg.allowPdf !== false,
        lpAllowWord:   cfg.allowWord !== false,
        lpAllowPrint:  cfg.allowPrint !== false,
        lpBrandWatermark: cfg.brandWatermark !== false,
        lpUserWatermark:  cfg.userWatermark !== false,
        lpPdfPassword: cfg.pdfPassword !== false,
        lpWordProtect: cfg.wordProtect !== false,
        lpOneTimeDownload: !!cfg.oneTimeDownload,
        lpExpiry: cfg.expiry || 'off',
      }
      return __exportSettingsCache
    })
    .catch(() => {
      // Network failure → assume everything ON (safe default for end-users)
      __exportSettingsCache = {
        showPrint: true, showPdf: true, showWord: true, showWatermark: true,
        multigradePdf: true,
        lpAllowPdf: true, lpAllowWord: true, lpAllowPrint: true,
        lpBrandWatermark: true, lpUserWatermark: true,
        lpPdfPassword: true, lpWordProtect: true,
        lpOneTimeDownload: false, lpExpiry: 'off',
      }
      return __exportSettingsCache
    })
  return __exportSettingsPromise
}
const invalidateExportSettings = () => { __exportSettingsCache = null; __exportSettingsPromise = null }
const useExportSettings = () => {
  const [s, setS] = useState(__exportSettingsCache || {
    showPrint: true, showPdf: true, showWord: true, showWatermark: true,
    multigradePdf: true,
    lpAllowPdf: true, lpAllowWord: true, lpAllowPrint: true,
    lpBrandWatermark: true, lpUserWatermark: true,
    lpPdfPassword: true, lpWordProtect: true,
    lpOneTimeDownload: false, lpExpiry: 'off',
  })
  useEffect(() => { fetchExportSettings().then(setS) }, [])
  return s
}

// ---------- Diagonal "lessonguruodisha.com" watermark for generated outputs ----------
// Returns the same SVG markup used by <PrintBrandWatermark/> as a raw HTML string.
// Used when we build off-screen DOM (lesson PDF) or Word HTML where JSX isn't an option.
const _buildWatermarkSvgInner = () => {
  // Grid of rotated text elements covering the whole printable area.
  // viewBox 1600×1000 ≈ A4 landscape aspect; preserveAspectRatio=none stretches to fill.
  const items = []
  const txt = 'Lesson Guru Odisha • lessonguruodisha.com'
  const rotate = -22
  const stepX = 360
  const stepY = 110
  for (let r = -1; r <= 11; r++) {
    for (let c = -1; c <= 6; c++) {
      const x = c * stepX + (r % 2 ? -150 : 0)
      const y = r * stepY + 40
      items.push(`<text x="${x}" y="${y}" transform="rotate(${rotate} ${x} ${y})" font-size="22" font-weight="700" font-family="Inter,'Noto Sans',system-ui,sans-serif" fill="#1e3a8a" fill-opacity="0.13">${txt}</text>`)
    }
  }
  return `<svg width="100%" height="100%" viewBox="0 0 1600 1000" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">${items.join('')}</svg>`
}
const brandWatermarkSvgHtml = () => (
  `<div class="print-brand-watermark-host" style="position:absolute;inset:0;pointer-events:none;z-index:0;overflow:hidden" aria-hidden="true">${_buildWatermarkSvgInner()}</div>`
)

// Renders as a fixed SVG overlay inside the printable container. Absolutely positioned so
// it doesn't disturb the table layout, and html2canvas captures it natively (works in
// screen preview + PDF + print).
const PrintBrandWatermark = () => (
  <div className="print-brand-watermark" aria-hidden="true"
    dangerouslySetInnerHTML={{ __html: _buildWatermarkSvgInner() }} />
)



// ---------- Watermark ----------
const Watermark = ({ user }) => {
  const [now, setNow] = useState(new Date())
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 30000)
    return () => clearInterval(t)
  }, [])
  if (!user) return null
  const text = `${user.name} • ${user.mobile} • ${now.toLocaleDateString('en-IN')} ${now.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}`
  return (
    <div data-watermark="true" className="pointer-events-none fixed inset-0 z-[60] overflow-hidden select-none">
      <div className="absolute inset-0 -rotate-[30deg] scale-150 flex flex-col gap-10 opacity-[0.12] dark:opacity-[0.16]">
        {Array.from({ length: 16 }).map((_, i) => (
          <div key={i} className="whitespace-nowrap flex gap-10 text-[13px] font-bold text-primary">
            {Array.from({ length: 6 }).map((__, j) => (
              <span key={j}>🔒 {text} • Lesson Guru Odisha Premium • Personal Educational Use Only</span>
            ))}
          </div>
        ))}
      </div>
    </div>
  )
}

// ---------- Top Bar ----------
const TopBar = ({ title, onBack, right }) => (
  <div className="sticky top-0 z-40 glass border-b border-border" style={{ paddingTop: 'env(safe-area-inset-top)' }}>
    <div className="flex items-center gap-2 h-14 px-3">
      {onBack ? (
        <Button size="icon" variant="ghost" onClick={onBack} className="rounded-full"><ArrowLeft className="w-5 h-5" /></Button>
      ) : (
        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center text-white shadow-lg"><GraduationCap className="w-5 h-5" /></div>
      )}
      <div className="flex-1 truncate font-bold text-base">{title}</div>
      {right}
    </div>
  </div>
)

// ---------- Bottom Nav ----------
const BottomNav = ({ view, go }) => {
  const items = [
    { id: 'home', label: 'Home', icon: Home },
    { id: 'classes', label: 'Lessons', icon: BookOpen },
    { id: 'search', label: 'Search', icon: Search },
    { id: 'plans', label: inNativeApp() ? 'My Plan' : 'Premium', icon: Crown },
    { id: 'profile', label: 'Profile', icon: UserIcon },
  ]
  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 glass border-t border-border">
      <div className="grid grid-cols-5 max-w-md mx-auto" style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}>
        {items.map((it) => {
          const active = view === it.id || (it.id === 'classes' && ['books', 'chapters', 'lessons', 'lesson-view'].includes(view)) || (it.id === 'profile' && ['admin', 'change-password', 'dashboard'].includes(view))
          const Icon = it.icon
          return (
            <button key={it.id} onClick={() => go(it.id)} className={`flex flex-col items-center justify-center py-2.5 gap-0.5 transition-all ${active ? 'text-primary' : 'text-muted-foreground'}`}>
              <div className={`p-1.5 rounded-2xl transition-all ${active ? 'bg-primary/10 scale-110' : ''}`}>
                <Icon className="w-5 h-5" strokeWidth={active ? 2.5 : 2} />
              </div>
              <span className={`text-[10px] font-medium ${active ? 'font-bold' : ''}`}>{it.label}</span>
            </button>
          )
        })}
      </div>
    </div>
  )
}

// =============================================================================
//  ⚡ InstantLessonSearch — fast "Lesson Finder" for teachers.
//  Cascading Class → Subject → Topic → Period dropdowns backed ENTIRELY by the
//  existing lesson-period endpoints (/classes, /books, /chapters?scope=lessons,
//  /lessons) — so it inherits the same visibility rules. "View Full Lesson"
//  opens the existing <LessonView/> (which enforces subscription/auth + has
//  Print & Download). Purely additive; no new data or permission system.
// =============================================================================
const InstantLessonSearch = ({ go, setContext }) => {
  const [classes, setClasses] = useState([])
  const [books, setBooks] = useState([])
  const [chapters, setChapters] = useState([])
  const [lessons, setLessons] = useState([])
  const [selClass, setSelClass] = useState('')
  const [selBook, setSelBook] = useState('')
  const [selChapter, setSelChapter] = useState('')
  const [selPeriod, setSelPeriod] = useState('') // lesson id (unique)
  const [busy, setBusy] = useState({ classes: true, books: false, chapters: false, lessons: false })
  const [result, setResult] = useState(null)
  const [opening, setOpening] = useState(false)
  const [recents, setRecents] = useState([])

  const RECENTS_KEY = 'lg_recent_lessons_v1'
  useEffect(() => {
    try {
      const raw = localStorage.getItem(RECENTS_KEY)
      const arr = raw ? JSON.parse(raw) : []
      if (Array.isArray(arr)) setRecents(arr)
    } catch {}
  }, [])

  const recordRecent = (r) => {
    if (!r?.lesson?.id) return
    const entry = {
      lesson: r.lesson,
      cls: r.cls,
      book: r.book,
      chapter: r.chapter,
      ts: Date.now(),
    }
    setRecents(prev => {
      const next = [entry, ...prev.filter(e => e?.lesson?.id !== r.lesson.id)].slice(0, 8)
      try { localStorage.setItem(RECENTS_KEY, JSON.stringify(next)) } catch {}
      return next
    })
  }

  const clearRecents = () => {
    setRecents([])
    try { localStorage.removeItem(RECENTS_KEY) } catch {}
  }

  const openRecent = (e) => {
    if (!e?.lesson) return
    setContext({ class: e.cls, book: e.book, chapter: e.chapter, lesson: e.lesson })
    go('lesson-view')
  }

  useEffect(() => {
    api('/classes')
      .then(r => setClasses(r.classes || []))
      .catch(e => toast.error(e.message || 'Failed to load classes'))
      .finally(() => setBusy(s => ({ ...s, classes: false })))
  }, [])

  const onClass = async (id) => {
    setSelClass(id); setSelBook(''); setSelChapter(''); setSelPeriod('')
    setBooks([]); setChapters([]); setLessons([]); setResult(null)
    if (!id) return
    setBusy(s => ({ ...s, books: true }))
    try { const r = await api(`/books?classId=${id}`); setBooks(r.books || []) }
    catch (e) { toast.error(e.message) } finally { setBusy(s => ({ ...s, books: false })) }
  }
  const onBook = async (id) => {
    setSelBook(id); setSelChapter(''); setSelPeriod(''); setChapters([]); setLessons([]); setResult(null)
    if (!id) return
    setBusy(s => ({ ...s, chapters: true }))
    try { const r = await api(`/chapters?classId=${selClass}&bookId=${id}&scope=lessons`); setChapters(r.chapters || []) }
    catch (e) { toast.error(e.message) } finally { setBusy(s => ({ ...s, chapters: false })) }
  }
  const onChapter = async (id) => {
    setSelChapter(id); setSelPeriod(''); setLessons([]); setResult(null)
    if (!id) return
    setBusy(s => ({ ...s, lessons: true }))
    try { const r = await api(`/lessons?chapterId=${id}`); setLessons(r.lessons || []) }
    catch (e) { toast.error(e.message) } finally { setBusy(s => ({ ...s, lessons: false })) }
  }

  const getLesson = () => {
    if (!selClass) return toast.error('📚 Please select a Class')
    if (!selBook) return toast.error('📖 Please select a Subject')
    if (!selChapter) return toast.error('📝 Please select a Topic / Chapter')
    if (!selPeriod) return toast.error('⏱️ Please select a Period')
    const lesson = lessons.find(l => l.id === selPeriod) // match by unique id, not title
    if (!lesson) { setResult({ notFound: true }); return }
    setResult({
      cls: classes.find(c => c.id === selClass),
      book: books.find(b => b.id === selBook),
      chapter: chapters.find(c => c.id === selChapter),
      lesson,
    })
  }

  const viewFull = () => {
    if (!result?.lesson) return
    setOpening(true)
    try {
      recordRecent(result)
      setContext({ class: result.cls, book: result.book, chapter: result.chapter, lesson: result.lesson })
      go('lesson-view') // reuses existing auth + print + download
    } finally { setOpening(false) }
  }

  const cName = (c) => c?.name || c?.title || ''
  const Field = ({ icon, label, value, onChange, disabled, loading, placeholder, options }) => (
    <div>
      <label className="text-xs font-bold text-muted-foreground flex items-center gap-1 mb-1">{icon} {label}</label>
      <div className="relative">
        <select
          value={value}
          disabled={disabled || loading}
          onChange={(e) => onChange(e.target.value)}
          className="w-full h-12 rounded-2xl border-2 border-border bg-background px-4 pr-10 text-base font-semibold appearance-none disabled:opacity-50 focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/30"
        >
          <option value="">{loading ? 'Loading…' : placeholder}</option>
          {options}
        </select>
        <ChevronRight className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 rotate-90 pointer-events-none text-muted-foreground" />
      </div>
    </div>
  )

  return (
    <div className="pb-28">
      <div className="bg-gradient-to-br from-violet-600 via-indigo-600 to-blue-600 text-white px-5 pt-7 pb-9 rounded-b-[2rem] relative overflow-hidden">
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-yellow-300/20 rounded-full blur-3xl" />
        <div className="flex items-center gap-2 relative">
          <div className="text-4xl drop-shadow">⚡</div>
          <div>
            <p className="font-extrabold text-xl leading-tight">Instant Lesson Search</p>
            <p className="text-[12px] opacity-90">Find &amp; open any lesson period · Balvatika – Class 10</p>
          </div>
        </div>
      </div>

      <div className="px-4 -mt-5 relative">
        <Card className="p-4 rounded-3xl border-2 shadow-xl space-y-3">
          <Field icon="📚" label="Class" value={selClass} onChange={onClass} loading={busy.classes}
            placeholder="Select Class"
            options={classes.map(c => <option key={c.id} value={c.id}>{cName(c)}</option>)} />

          <Field icon="📖" label="Subject" value={selBook} onChange={onBook} disabled={!selClass} loading={busy.books}
            placeholder={!selClass ? 'Select a Class first' : (books.length ? 'Select Subject' : 'No subjects available')}
            options={books.map(b => <option key={b.id} value={b.id}>{cName(b)}</option>)} />

          <Field icon="📝" label="Topic / Chapter" value={selChapter} onChange={onChapter} disabled={!selBook} loading={busy.chapters}
            placeholder={!selBook ? 'Select a Subject first' : (chapters.length ? 'Select Topic / Chapter' : 'No topics available')}
            options={chapters.map(c => <option key={c.id} value={c.id}>{cName(c)}</option>)} />

          <Field icon="⏱️" label="Period" value={selPeriod} onChange={setSelPeriod} disabled={!selChapter} loading={busy.lessons}
            placeholder={!selChapter ? 'Select a Topic first' : (lessons.length ? 'Select Period' : 'No periods available')}
            options={lessons.map(l => <option key={l.id} value={l.id}>{`Period ${l.period ?? '?'}${l.title ? ' · ' + l.title : ''}`}</option>)} />

          <Button onClick={getLesson} className="w-full py-3.5 h-auto rounded-2xl text-base font-extrabold bg-gradient-to-r from-violet-600 to-blue-600 text-white shadow-lg">
            <Search className="w-5 h-5 mr-2" /> GET LESSON
          </Button>
        </Card>

        {result && (
          <div className="mt-4">
            {result.notFound ? (
              <Card className="p-6 rounded-2xl border-2 border-dashed text-center">
                <div className="text-4xl mb-2">📚</div>
                <p className="font-bold">No lesson is currently available for this selection.</p>
                <p className="text-xs text-muted-foreground mt-1">Try a different Period, Topic or Subject.</p>
              </Card>
            ) : (
              <Card className="rounded-2xl border-2 overflow-hidden">
                <div className="bg-emerald-500 text-white px-4 py-2 flex items-center gap-2 font-extrabold text-sm">
                  <span className="text-lg">✓</span> LESSON FOUND
                </div>
                <div className="p-4 space-y-2">
                  <div className="flex flex-wrap gap-1.5">
                    <Badge className="bg-blue-100 text-blue-800 border-0">📚 {cName(result.cls)}</Badge>
                    <Badge className="bg-indigo-100 text-indigo-800 border-0">📖 {cName(result.book)}</Badge>
                    <Badge className="bg-purple-100 text-purple-800 border-0">📝 {cName(result.chapter)}</Badge>
                    <Badge className="bg-amber-100 text-amber-800 border-0">⏱️ Period {result.lesson.period}</Badge>
                  </div>
                  {result.lesson.title && <p className="font-bold text-base pt-1">{result.lesson.title}</p>}
                  {result.lesson.topic && <p className="text-sm text-muted-foreground line-clamp-2">{result.lesson.topic}</p>}
                  <Button onClick={viewFull} disabled={opening} className="w-full h-12 mt-2 rounded-2xl font-extrabold bg-gradient-to-r from-emerald-600 to-teal-600 text-white">
                    {opening ? <Loader2 className="w-5 h-5 mr-2 animate-spin" /> : <span className="mr-2">📖</span>} View Full Lesson
                  </Button>
                  <p className="text-[11px] text-center text-muted-foreground">Opens the full lesson · Print &amp; Download available inside</p>
                </div>
              </Card>
            )}
          </div>
        )}

        {recents.length > 0 && (
          <div className="mt-6">
            <div className="flex items-center justify-between mb-2 px-1">
              <p className="text-xs font-extrabold text-muted-foreground flex items-center gap-1">🕘 Recently Opened</p>
              <button onClick={clearRecents} className="text-[11px] font-bold text-muted-foreground hover:text-destructive">Clear</button>
            </div>
            <div className="space-y-2">
              {recents.map((e) => (
                <Card
                  key={e.lesson.id}
                  onClick={() => openRecent(e)}
                  className="p-3 rounded-2xl border-2 cursor-pointer flex items-center gap-3 active:scale-[0.99] transition-transform"
                >
                  <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-violet-600 to-blue-600 text-white flex items-center justify-center font-extrabold text-xs shrink-0">
                    P{e.lesson.period ?? '?'}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-bold text-sm truncate">{e.lesson.title || `Period ${e.lesson.period ?? ''}`}</p>
                    <p className="text-[11px] text-muted-foreground truncate">{cName(e.cls)} · {cName(e.book)} · {cName(e.chapter)}</p>
                  </div>
                  <ChevronRight className="w-5 h-5 text-muted-foreground shrink-0" />
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  )
}


// =============================================================================
//  <Typewriter/> — reveals text letter-by-letter for a "streaming AI" feel
// =============================================================================
const Typewriter = ({ text = '', speed = 12, className = '' }) => {
  const [shown, setShown] = useState('')
  useEffect(() => {
    setShown('')
    if (!text) return
    let i = 0
    const iv = setInterval(() => {
      i += Math.max(1, Math.round(text.length / 200))
      if (i >= text.length) { setShown(text); clearInterval(iv) }
      else setShown(text.substring(0, i))
    }, speed)
    return () => clearInterval(iv)
  }, [text, speed])
  return <span className={className}>{shown}<span className="inline-block w-1 bg-current animate-pulse opacity-70 ml-0.5" style={{ height: '0.9em', verticalAlign: 'middle' }} /></span>
}

// =============================================================================
//  <LiveGenerationFeed/> — animated status feed replacing plain spinners.
// =============================================================================
const WorksheetLibraryView = ({ go, user }) => {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [current, setCurrent] = useState(null)
  const [q, setQ] = useState('')
  const load = async () => {
    setLoading(true)
    try { const r = await api('/worksheets/mine'); setItems(r.items || []) } catch (e) { toast.error(e.message) }
    setLoading(false)
  }
  useEffect(() => { if (user) load() /* eslint-disable-next-line */ }, [user])
  useEffect(() => {
    if (!items.some(w => w.status === 'generating')) return
    const t = setInterval(load, 5000); return () => clearInterval(t)
    /* eslint-disable-next-line */
  }, [items])
  const openOne = async (id) => {
    try { const r = await api(`/worksheets/${id}`); if (r.worksheet?.status === 'ready') setCurrent(r.worksheet); else toast(r.worksheet?.errorMessage || 'Not ready yet') }
    catch (e) { toast.error(e.message) }
  }
  const filtered = items.filter(w => !q || (w.title || '').toLowerCase().includes(q.toLowerCase()) || (w.chapterName || '').toLowerCase().includes(q.toLowerCase()) || (w.className || '').toLowerCase().includes(q.toLowerCase()))
  const genCount = items.filter(w => w.status === 'generating').length
  return (
    <div className="max-w-2xl mx-auto px-4 py-4">
      <div className="flex items-center gap-2 mb-3">
        <Button size="sm" variant="outline" onClick={() => go('dashboard')} className="rounded-full h-8">← Back</Button>
        <h1 className="font-black text-lg flex-1">📖 My Worksheets</h1>
        <Button size="sm" variant="outline" onClick={load} className="rounded-full h-8">↻</Button>
      </div>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Search by title, chapter, class…" className="w-full h-10 rounded-xl border-2 px-3 text-sm mb-3" style={{ fontSize: 16 }} />
      {genCount > 0 && <p className="text-[11px] text-blue-700 dark:text-blue-300 mb-2">⏳ {genCount} still generating — this list updates automatically.</p>}
      {loading ? (
        <div className="py-10 text-center text-muted-foreground"><Loader2 className="w-6 h-6 animate-spin mx-auto" /></div>
      ) : filtered.length === 0 ? (
        <Card className="p-6 text-center rounded-2xl border-2 border-dashed"><p className="text-sm text-muted-foreground">No worksheets yet. Generate one from any lesson&apos;s Custom Worksheet tool.</p></Card>
      ) : (
        <div className="space-y-2">
          {filtered.map(w => (
            <Card key={w.id} className="p-3 rounded-2xl border-2 flex items-center gap-2">
              <div className="min-w-0 flex-1">
                <p className="font-bold text-[13px] truncate">{w.title || `${(w.type || '').toUpperCase()} · ${(w.format || '').toUpperCase()}`}</p>
                <p className="text-[10px] text-muted-foreground truncate">{[w.className, w.bookName, w.chapterName].filter(Boolean).join(' · ')}</p>
                <div className="flex gap-1.5 mt-1 flex-wrap text-[9px]">
                  <Badge variant="secondary">{(w.type || '').toUpperCase()}</Badge>
                  <Badge variant="outline">{(w.format || '').toUpperCase()}</Badge>
                  {w.count ? <Badge variant="outline">{w.count} Q</Badge> : null}
                  {w.generatedAt && <Badge variant="outline">{new Date(w.generatedAt).toLocaleDateString('en-IN')}</Badge>}
                </div>
                {w.status === 'failed' && w.errorMessage && <p className="text-[10px] text-red-600 mt-1">{w.errorMessage}</p>}
              </div>
              <div className="flex flex-col items-end gap-1 shrink-0">
                {w.status === 'generating' && <Badge className="bg-blue-500 text-white animate-pulse text-[9px]">⏳ Generating</Badge>}
                {w.status === 'failed' && <Badge className="bg-red-500 text-white text-[9px]">❌ Failed</Badge>}
                {(w.status === 'ready' || !w.status) && <Button size="sm" onClick={() => openOne(w.id)} className="h-7 text-[10px] rounded-full">Open</Button>}
                {(w.status === 'ready' || !w.status) && <a href={`/api/lessons/${w.lessonId}/worksheets/${w.id}/pdf?variant=worksheet`} target="_blank" rel="noreferrer" className="text-[10px] text-blue-600 font-bold underline">PDF</a>}
              </div>
            </Card>
          ))}
        </div>
      )}
      {current && (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-3" onClick={() => setCurrent(null)}>
          <Card className="max-w-lg w-full max-h-[85vh] overflow-y-auto p-4 rounded-2xl" onClick={e => e.stopPropagation()}>
            <div className="flex items-start justify-between gap-2 mb-2">
              <p className="font-black text-sm">{current.title}</p>
              <button onClick={() => setCurrent(null)} className="text-xl leading-none">✕</button>
            </div>
            {current.instructions && <p className="text-[11px] italic text-muted-foreground mb-2">{current.instructions}</p>}
            <div className="space-y-2">
              {(current.questions || (current.sections || []).flatMap(s => s.questions || [])).map((qq, i) => (
                <div key={i} className="text-[12px] p-2 rounded-lg bg-slate-50 dark:bg-slate-900/40"><b>Q{i + 1}.</b> {typeof qq === 'string' ? qq : (qq.q || qq.question || qq.text || '')}</div>
              ))}
            </div>
            <a href={`/api/lessons/${current.lessonId}/worksheets/${current.id}/pdf?variant=worksheet`} target="_blank" rel="noreferrer" className="block mt-3 text-center bg-blue-600 text-white rounded-full py-2 text-sm font-bold">📥 Download PDF</a>
          </Card>
        </div>
      )}
    </div>
  )
}

const LiveGenerationFeed = ({ stage, draftPreview, resourceName = 'resource' }) => {
  const [ticks, setTicks] = useState(0)
  useEffect(() => { const iv = setInterval(() => setTicks(t => t + 1), 800); return () => clearInterval(iv) }, [])
  const dots = '.'.repeat((ticks % 3) + 1)
  const steps = [
    { key: 'preparing', emoji: '📖', label: 'Reading lesson content', done: ['drafting','enhancing','saving','ready'].includes(stage) },
    { key: 'drafting', emoji: '✍️', label: 'Writing questions from scratch', done: ['enhancing','saving','ready'].includes(stage) },
    { key: 'enhancing', emoji: '✨', label: 'Improving with smart assistant', done: ['saving','ready'].includes(stage) },
    { key: 'saving', emoji: '💾', label: 'Saving to your library', done: ['ready'].includes(stage) },
  ]
  const draftQs = Array.isArray(draftPreview?.draftQuestions) ? draftPreview.draftQuestions : []
  return (
    <div className="space-y-3">
      <Card className="p-4 rounded-2xl border-2 bg-gradient-to-br from-indigo-50 to-blue-50 dark:from-indigo-950/40 dark:to-blue-950/40">
        <p className="font-extrabold text-xs text-indigo-700 dark:text-indigo-300 mb-2">🤖 Generating {resourceName}{stage !== 'ready' ? dots : '…'}</p>
        {(() => {
          const PS = [
            { key: 'blueprint', label: 'Blueprint', icon: '🧭' },
            { key: 'questions', label: 'Questions', icon: '✍️' },
            { key: 'answerkey', label: 'Answer key', icon: '🔑' },
            { key: 'ready', label: 'Ready', icon: '✅' },
          ]
          const idx = stage === 'preparing' ? 0 : stage === 'drafting' ? 1 : stage === 'enhancing' ? 2 : (stage === 'saving' || stage === 'ready') ? 3 : 0
          return (
            <div className="flex items-center justify-between gap-1 mb-3">
              {PS.map((st, i) => (
                <Fragment key={st.key}>
                  <div className="flex flex-col items-center gap-0.5 min-w-0">
                    <div className={`w-7 h-7 rounded-full grid place-items-center text-[13px] ${i <= idx ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400 dark:bg-slate-700'}`}>{i < idx ? '✓' : st.icon}</div>
                    <span className={`text-[9px] font-bold ${i <= idx ? 'text-indigo-700 dark:text-indigo-300' : 'text-slate-400'}`}>{st.label}</span>
                  </div>
                  {i < PS.length - 1 && <div className={`flex-1 h-0.5 ${i < idx ? 'bg-indigo-500' : 'bg-slate-200 dark:bg-slate-700'}`} />}
                </Fragment>
              ))}
            </div>
          )
        })()}
        <div className="space-y-1.5">
          {steps.map(s => {
            const active = stage === s.key
            const done = s.done
            return (
              <div key={s.key} className={`flex items-center gap-2 text-[11px] ${done ? 'text-emerald-700 dark:text-emerald-400' : active ? 'text-blue-700 dark:text-blue-300 font-bold' : 'opacity-40'}`}>
                <span className="w-4 text-center">{done ? '✓' : active ? <Loader2 className="w-3 h-3 animate-spin inline" /> : '○'}</span>
                <span>{s.emoji}</span>
                <span>{s.label}{active ? dots : ''}</span>
              </div>
            )
          })}
        </div>
      </Card>
      {draftPreview?.draftTitle && (
        <Card className="p-3 rounded-2xl border-2 border-blue-200 dark:border-blue-900 bg-white dark:bg-slate-950 animate-in fade-in slide-in-from-bottom-4">
          <p className="font-bold text-xs mb-1"><Typewriter text={String(draftPreview.draftTitle)} className="text-indigo-700 dark:text-indigo-300" /></p>
          {draftPreview.draftInstructions && (
            <p className="text-[10px] opacity-70 italic mb-2 line-clamp-2">{String(draftPreview.draftInstructions).slice(0, 150)}</p>
          )}
        </Card>
      )}
      {draftQs.length > 0 && (
        <Card className="p-3 rounded-2xl border-2 border-emerald-200 dark:border-emerald-900 animate-in fade-in slide-in-from-bottom-4">
          <div className="flex items-center gap-2 mb-2">
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
            <p className="font-bold text-[11px] text-emerald-700 dark:text-emerald-400">Draft ready · polishing {draftQs.length} question{draftQs.length !== 1 ? 's' : ''}…</p>
          </div>
          <div className="space-y-1.5 max-h-64 overflow-y-auto">
            {draftQs.slice(0, 8).map((q, i) => {
              const qText = typeof q === 'string' ? q : (q?.q || q?.question || q?.text || '')
              return (
                <div key={i} className="p-1.5 rounded bg-slate-50 dark:bg-slate-900/50 text-xs animate-in fade-in slide-in-from-left-2" style={{ animationDelay: `${i * 90}ms` }}>
                  <span className="font-extrabold text-emerald-600">Q{i + 1}.</span> <Typewriter text={String(qText).slice(0, 160)} speed={8} />
                </div>
              )
            })}
            {draftQs.length > 8 && <p className="text-[10px] opacity-60 text-center">+ {draftQs.length - 8} more…</p>}
          </div>
        </Card>
      )}
      {!draftPreview?.draftReady && (
        <p className="text-xs text-center text-muted-foreground">💡 First questions appear in ~15-25 seconds</p>
      )}
    </div>
  )
}

const Spinner = ({ label }) => (
  <div className="flex flex-col items-center justify-center py-20 gap-3 text-muted-foreground">
    <Loader2 className="w-7 h-7 animate-spin text-primary" />
    {label && <p className="text-sm">{label}</p>}
  </div>
)

