// Public testimonials block — fetches /reviews/public, falls back to seed list if empty.
const PublicTestimonialsSection = ({ fallback = [] }) => {
  const [data, setData] = useState({ reviews: [], avg: 0, count: 0 })
  useEffect(() => {
    api('/reviews/public').then(r => setData({ reviews: r.reviews || [], avg: r.avg || 0, count: r.count || 0 })).catch(() => {})
  }, [])
  const list = data.reviews.length ? data.reviews : []
  const useFallback = list.length === 0
  return (
    <>
      <div className="flex items-baseline justify-between gap-2">
        <h2 className="text-lg font-bold">💬 What Teachers Say</h2>
        {!useFallback && data.count > 0 && (
          <div className="flex items-center gap-1 text-[12px]">
            <span className="text-amber-500 font-bold">{'★'.repeat(Math.round(data.avg))}{'☆'.repeat(5 - Math.round(data.avg))}</span>
            <span className="font-extrabold">{data.avg.toFixed(1)}</span>
            <span className="text-muted-foreground">({data.count})</span>
          </div>
        )}
      </div>
      <div className="mt-3 flex gap-3 overflow-x-auto scroll-hide -mx-4 px-4 pb-1">
        {useFallback
          ? fallback.map((t, i) => (
            <Card key={'fb-' + i} className="min-w-[260px] p-4 rounded-2xl border-2">
              <div className="flex gap-2 items-center">
                <div className="text-3xl">{t.emoji}</div>
                <div><p className="font-bold text-sm">{t.name}</p><p className="text-[10px] text-muted-foreground">{t.role}</p></div>
              </div>
              <div className="flex mt-2 text-amber-400 text-xs">★★★★★</div>
              <p className="text-xs mt-2 leading-relaxed">&ldquo;{t.text}&rdquo;</p>
            </Card>
          ))
          : list.map((r) => (
            <Card key={r.id} className="min-w-[260px] p-4 rounded-2xl border-2">
              <div className="flex gap-2 items-center">
                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold">{(r.userName || '?').charAt(0).toUpperCase()}</div>
                <div>
                  <p className="font-bold text-sm">{r.userName || 'Teacher'}</p>
                  <p className="text-[10px] text-muted-foreground">Verified User</p>
                </div>
              </div>
              <div className="flex mt-2 text-amber-400 text-xs">{'★'.repeat(r.rating)}{'☆'.repeat(5 - r.rating)}</div>
              {r.comment && <p className="text-xs mt-2 leading-relaxed">&ldquo;{r.comment}&rdquo;</p>}
            </Card>
          ))
        }
      </div>
    </>
  )
}

// Interactive star rating (1-5)
const StarRating = ({ value, onChange, size = 'md' }) => {
  const cls = size === 'lg' ? 'w-8 h-8' : size === 'sm' ? 'w-4 h-4' : 'w-6 h-6'
  return (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map((n) => (
        <button key={n} type="button" onClick={() => onChange(n)} aria-label={`Rate ${n} stars`} className="transition-transform active:scale-90">
          <Star className={`${cls} ${n <= value ? 'fill-amber-400 text-amber-400' : 'text-muted-foreground/40'}`} />
        </button>
      ))}
    </div>
  )
}

// Profile-screen card: lets logged-in users post a 1-5 star rating + comment (one per user, can edit).
const RateUsCard = () => {
  const [open, setOpen] = useState(false)
  const [rating, setRating] = useState(5)
  const [comment, setComment] = useState('')
  const [existing, setExisting] = useState(null)
  const [busy, setBusy] = useState(false)
  useEffect(() => {
    api('/reviews/me').then(r => {
      if (r.review) {
        setExisting(r.review)
        setRating(r.review.rating || 5)
        setComment(r.review.comment || '')
      }
    }).catch(() => {})
  }, [])
  const submit = async () => {
    if (!rating || rating < 1 || rating > 5) return toast.error('Choose 1-5 stars')
    setBusy(true)
    try {
      const r = await api('/reviews', { method: 'POST', body: { rating, comment } })
      setExisting(r.review)
      toast.success(existing ? 'Review updated ✨' : 'Thanks for your review! 🎉')
      setOpen(false)
    } catch (e) { toast.error(e.message) } finally { setBusy(false) }
  }
  return (
    <>
      <Card onClick={() => setOpen(true)} className="p-4 rounded-2xl border-2 cursor-pointer bg-gradient-to-br from-amber-50 to-orange-50 dark:from-amber-950/30 dark:to-orange-950/30 border-amber-300 dark:border-amber-700/50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 text-white flex items-center justify-center"><Star className="w-5 h-5 fill-white" /></div>
          <div className="flex-1">
            <p className="font-semibold flex items-center gap-2">⭐ {existing ? 'Update Your Review' : 'Rate Lesson Guru Odisha'}</p>
            <p className="text-[11px] text-muted-foreground">{existing ? `You rated ${existing.rating}/5 — tap to change` : 'Help us improve · Help others choose'}</p>
          </div>
          <ChevronRight className="w-4 h-4 text-muted-foreground" />
        </div>
      </Card>
      {open && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-end sm:items-center justify-center p-3" onClick={() => setOpen(false)}>
          <Card className="max-w-md w-full p-5 rounded-2xl bg-background" onClick={(e) => e.stopPropagation()}>
            <p className="text-lg font-extrabold">⭐ How would you rate us?</p>
            <p className="text-[11px] text-muted-foreground mt-1">Your honest review helps other teachers find us.</p>
            <div className="mt-4 flex justify-center"><StarRating value={rating} onChange={setRating} size="lg" /></div>
            <p className="text-center text-[11px] text-muted-foreground mt-1">{['Tap stars to rate', 'Poor', 'Fair', 'Good', 'Great', 'Excellent! 🎉'][rating || 0]}</p>
            <Textarea value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Share your experience (optional)…" rows={3} className="mt-3 rounded-xl text-sm" maxLength={600} />
            <p className="text-right text-[10px] text-muted-foreground mt-1">{comment.length}/600</p>
            <div className="grid grid-cols-2 gap-2 mt-3">
              <Button variant="outline" onClick={() => setOpen(false)} className="rounded-xl">Cancel</Button>
              <Button onClick={submit} disabled={busy} className="rounded-xl bg-gradient-to-r from-amber-500 to-orange-500 font-bold">
                {busy ? <Loader2 className="w-4 h-4 animate-spin" /> : (existing ? 'Update Review' : 'Submit Review')}
              </Button>
            </div>
          </Card>
        </div>
      )}
    </>
  )
}

