// Profile-screen card: shows my referral code, link, stats, share buttons.
const InviteAndEarnCard = () => {
  const [data, setData] = useState(null)
  const [busy, setBusy] = useState(false)
  useEffect(() => {
    api('/me/referral').then(setData).catch(() => {})
  }, [])
  const onCopyLink = async () => {
    if (!data?.link) return
    try { await navigator.clipboard.writeText(data.link); toast.success('Link copied! 📋') }
    catch { toast.error('Copy failed') }
  }
  const onCopyMessage = async () => {
    if (!data?.link) return
    try { await navigator.clipboard.writeText((data.shareMessage || buildOdiaReferralMessage(data.link))); toast.success('Message copied to clipboard! 📋') }
    catch { toast.error('Copy failed') }
  }
  const shareNative = async () => {
    if (!data?.link) return
    const msg = (data.shareMessage || buildOdiaReferralMessage(data.link))
    if (navigator.share) {
      try { await navigator.share({ title: 'Lesson Guru Odisha', text: msg, url: data.link }); }
      catch {}
    } else {
      onCopyMessage()
    }
  }
  const onShareWhatsApp = () => {
    if (!data?.link) return
    const msg = (data.shareMessage || buildOdiaReferralMessage(data.link))
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(msg)}`
    window.open(url, '_blank', 'noopener,noreferrer')
  }
  const onShareTelegram = () => {
    if (!data?.link) return
    const msg = (data.shareMessage || buildOdiaReferralMessage(data.link))
    const url = `https://t.me/share/url?url=${encodeURIComponent(data.link)}&text=${encodeURIComponent(msg)}`
    window.open(url, '_blank', 'noopener,noreferrer')
  }
  const onShareFacebook = () => {
    if (!data?.link) return
    const url = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(data.link)}`
    window.open(url, '_blank', 'noopener,noreferrer')
  }
  const onShareTwitter = () => {
    if (!data?.link) return
    const msg = `🔥 ଓଡ଼ିଶାର ଶିକ୍ଷକଙ୍କ ପାଇଁ Best App! OCF Daily 7-Period Plan, Worksheet, LO Code — One-Click!\n🎥 Demo: https://youtu.be/KVdJWUbaLIc\n🛠️ 30+ Free Tools: https://TeacherUtilityToolKit.in\n👇 Join Free: ${data.link}`
    const url = `https://twitter.com/intent/tweet?text=${encodeURIComponent(msg)}`
    window.open(url, '_blank', 'noopener,noreferrer')
  }
  return (
    <Card className="p-0 rounded-2xl border-2 overflow-hidden">
      {/* Hero */}
      <div className="relative bg-gradient-to-br from-fuchsia-600 via-purple-600 to-indigo-700 text-white p-5">
        <div className="absolute -top-6 -right-6 text-7xl opacity-15">🎁</div>
        <p className="text-xs opacity-90 uppercase tracking-wide font-bold">Invite Friends · Earn Rewards</p>
        <p className="text-xl font-extrabold mt-1 leading-tight">🚀 ସାଙ୍ଗଙ୍କୁ Invite କରନ୍ତୁ — ସମସ୍ତଙ୍କୁ Free ରେ ସାହାଯ୍ୟ କରନ୍ତୁ!</p>
        <p className="text-[11px] opacity-95 mt-1.5">ପ୍ରତ୍ୟେକ Teacher ଯିଏ ଆପଣଙ୍କ link ରୁ join କରନ୍ତି — ସେ ଆପଣଙ୍କ team ର ଅଂଶ ହୁଅନ୍ତି ⭐</p>
        {data && (
          <div className="mt-3 grid grid-cols-2 gap-2">
            <div className="bg-white/15 backdrop-blur rounded-xl p-2">
              <p className="text-[10px] opacity-90 uppercase font-bold">Total Invites</p>
              <p className="text-2xl font-extrabold">{data.totalInvited || 0}</p>
            </div>
            <div className="bg-white/15 backdrop-blur rounded-xl p-2">
              <p className="text-[10px] opacity-90 uppercase font-bold">Premium Joined</p>
              <p className="text-2xl font-extrabold">{data.subscribedCount || 0}</p>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 space-y-3">
        {/* Referral code + link */}
        {data ? (
          <>
            <div>
              <Label className="text-[11px] font-bold">🎟️ Your Unique Referral Code</Label>
              <div className="mt-1 flex gap-2">
                <Input value={data.code} readOnly className="font-mono font-extrabold tracking-wider rounded-xl h-11 text-center text-base bg-muted" />
                <Button onClick={() => { navigator.clipboard.writeText(data.code).then(() => toast.success('Code copied! 📋')) }} className="rounded-xl h-11" variant="outline"><Copy className="w-4 h-4" /></Button>
              </div>
            </div>
            <div>
              <Label className="text-[11px] font-bold">🔗 Your Shareable Link</Label>
              <div className="mt-1 flex gap-2">
                <Input value={data.link} readOnly className="rounded-xl h-11 text-[11px] bg-muted" />
                <Button onClick={onCopyLink} className="rounded-xl h-11" variant="outline"><Copy className="w-4 h-4" /></Button>
              </div>
            </div>
            {/* Share buttons */}
            <div>
              <p className="text-[11px] font-bold mb-1.5">📤 Share Instantly</p>
              <div className="grid grid-cols-4 gap-2">
                <Button onClick={onShareWhatsApp} className="rounded-xl h-12 flex-col gap-0 bg-[#25D366] hover:bg-[#1ebe57] text-white text-[10px] font-bold"><MessageCircle className="w-5 h-5" /><span>WhatsApp</span></Button>
                <Button onClick={onShareTelegram} className="rounded-xl h-12 flex-col gap-0 bg-[#0088cc] hover:bg-[#0077b3] text-white text-[10px] font-bold"><Send className="w-5 h-5" /><span>Telegram</span></Button>
                <Button onClick={onShareFacebook} className="rounded-xl h-12 flex-col gap-0 bg-[#1877F2] hover:bg-[#0d67d4] text-white text-[10px] font-bold"><span className="text-base">f</span><span>Facebook</span></Button>
                <Button onClick={onShareTwitter} className="rounded-xl h-12 flex-col gap-0 bg-black hover:bg-zinc-800 text-white text-[10px] font-bold"><span className="text-base">𝕏</span><span>Twitter</span></Button>
              </div>
              <div className="grid grid-cols-2 gap-2 mt-2">
                <Button onClick={shareNative} variant="outline" className="rounded-xl h-10 text-xs font-bold"><Share2 className="w-4 h-4 mr-1" /> More Apps…</Button>
                <Button onClick={onCopyMessage} variant="outline" className="rounded-xl h-10 text-xs font-bold"><Copy className="w-4 h-4 mr-1" /> Copy Message</Button>
              </div>
            </div>
            {/* Joined list */}
            {data.joined?.length > 0 && (
              <div>
                <p className="text-[11px] font-bold mb-1.5">🏅 Your Recent Invites</p>
                <div className="space-y-1.5 max-h-44 overflow-y-auto pr-1">
                  {data.joined.slice(0, 10).map((j, i) => (
                    <div key={i} className="flex items-center gap-2 p-2 rounded-lg bg-muted/40">
                      <div className="w-7 h-7 rounded-full bg-primary/15 flex items-center justify-center font-bold text-xs text-primary">{(j.name || '?').charAt(0).toUpperCase()}</div>
                      <div className="flex-1 min-w-0">
                        <p className="text-xs font-semibold truncate">{j.name}</p>
                        <p className="text-[10px] text-muted-foreground">{j.mobile} · {new Date(j.joinedAt).toLocaleDateString('en-IN')}</p>
                      </div>
                      {j.subscribed ? <Badge className="bg-emerald-500 text-white text-[9px] h-5">⭐ Premium</Badge> : <Badge variant="outline" className="text-[9px] h-5">Free</Badge>}
                    </div>
                  ))}
                </div>
              </div>
            )}
            {/* Preview message */}
            <details className="rounded-xl border-2 bg-muted/30 p-3">
              <summary className="text-xs font-bold cursor-pointer">👁️ Preview your invite message (Odia)</summary>
              <pre className="text-[11px] whitespace-pre-wrap font-sans mt-2 leading-relaxed">{(data.shareMessage || buildOdiaReferralMessage(data.link))}</pre>
            </details>
          </>
        ) : (
          <div className="flex items-center justify-center py-6"><Loader2 className="w-5 h-5 animate-spin text-muted-foreground" /></div>
        )}
      </div>
    </Card>
  )
}

