// =================== PROFILE ===================
// ============ Ajira Pathya Jojana — Purchase & Gift History Card ============
// Shows the logged-in user their Ajira addon activity so they can see when
// their addon expires + who granted it (admin or self-purchase).  Rendered
// inside the Profile page.
const AjiraAddonHistoryCard = () => {
  const [state, setState] = useState({ loading: true, items: [], active: null, err: null })
  const [status, setStatus] = useState(null)   // /ajira-addon/status → { hasAccess, source, priceRupees, pricing }
  const [expanded, setExpanded] = useState(false)
  const [paying, setPaying] = useState(false)
  const [rzpReady, setRzpReady] = useState(false)

  // Load history + current pricing tier
  const load = async () => {
    try {
      const [h, s] = await Promise.all([
        api('/ajira-addon/history').catch(() => ({ items: [], active: null })),
        api('/ajira-addon/status').catch(() => null),
      ])
      setState({ loading: false, items: h?.items || [], active: h?.active || null, err: null })
      setStatus(s || null)
    } catch (e) {
      setState(s => ({ ...s, loading: false, err: e?.message || 'Failed to load' }))
    }
  }
  useEffect(() => { load() }, [])

  // Lazy-load Razorpay checkout.js only when this card is expanded and the
  // renew action becomes available (avoids blocking the initial page paint).
  useEffect(() => {
    if (typeof window === 'undefined') return
    if (window.Razorpay) { setRzpReady(true); return }
    if (!expanded) return
    const existing = document.querySelector('script[src*="checkout.razorpay.com"]')
    if (existing) { existing.addEventListener('load', () => setRzpReady(true)); return }
    const scr = document.createElement('script')
    scr.src = 'https://checkout.razorpay.com/v1/checkout.js'
    scr.async = true
    scr.onload = () => setRzpReady(true)
    document.body.appendChild(scr)
  }, [expanded])

  // One-tap Razorpay checkout for Ajira addon — used for both first-purchase
  // and renew/extend flows.  Idempotent: on success it reloads the history so
  // the user sees the newly stacked expiry immediately.
  const startCheckout = async () => {
    if (paying) return
    if (!status?.pricing?.enabled) return toast.error('Ajira Pathya Jojana add-on is currently unavailable.')
    if (typeof window === 'undefined' || !window.Razorpay) {
      return toast.error('Payment library still loading — please wait a moment and retry.')
    }
    setPaying(true)
    try {
      const order = await api('/ajira-addon/create-order', { method: 'POST' })
      if (!order?.orderId) throw new Error(order?.error || 'Could not create order')
      const options = {
        key: order.keyId, amount: order.amount, currency: order.currency,
        name: 'Lesson Guru Odisha',
        description: `Ajira Pathya Jojana Add-on · 365 days`,
        image: '/icon-192.png',
        order_id: order.orderId,
        theme: { color: '#ea580c' },
        notes: { product: 'ajira-addon' },
        modal: { ondismiss: () => { setPaying(false); toast.info('Payment cancelled') } },
        handler: async (resp) => {
          try {
            const v = await api('/ajira-addon/verify-payment', {
              method: 'POST',
              body: {
                razorpay_order_id: resp.razorpay_order_id,
                razorpay_payment_id: resp.razorpay_payment_id,
                razorpay_signature: resp.razorpay_signature,
              },
            })
            if (v?.ok) {
              toast.success('🎉 Ajira Pathya Jojana activated! 365 days added.')
              await load()
            } else {
              toast.error('Verification failed. Please contact support.')
            }
          } catch (e) { toast.error(e?.message || 'Verification failed') } finally { setPaying(false) }
        },
      }
      const rzp = new window.Razorpay(options)
      rzp.on('payment.failed', (r) => { toast.error(r?.error?.description || 'Payment failed'); setPaying(false) })
      rzp.open()
    } catch (e) {
      toast.error(e?.message || 'Failed to start payment')
      setPaying(false)
    }
  }

  const fmtDate = (iso) => iso ? new Date(iso).toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' }) : '—'
  const daysLeft = (iso) => {
    if (!iso) return 0
    const ms = new Date(iso).getTime() - Date.now()
    return Math.max(0, Math.ceil(ms / 86_400_000))
  }
  const sourceLabel = (s) => {
    if (s === 'admin-grant')       return '🎁 Gifted by Admin'
    if (s === 'admin-grant-bulk')  return '🎯 Group Gift (Admin)'
    if (s === 'verify-recovery')   return '💳 Purchase (Recovered)'
    if (s === 'webhook')           return '💳 Purchase'
    return '💳 Purchase'
  }
  const statusBadge = (st) => {
    if (st === 'active')     return { label: 'Active',     cls: 'bg-emerald-100 text-emerald-700 border-emerald-300 dark:bg-emerald-900/40 dark:text-emerald-200' }
    if (st === 'expired')    return { label: 'Expired',    cls: 'bg-slate-200 text-slate-600 border-slate-300 dark:bg-slate-800 dark:text-slate-300' }
    if (st === 'revoked')    return { label: 'Revoked',    cls: 'bg-red-100 text-red-700 border-red-300 dark:bg-red-950/50 dark:text-red-200' }
    if (st === 'superseded') return { label: 'Superseded', cls: 'bg-amber-100 text-amber-700 border-amber-300 dark:bg-amber-950/40 dark:text-amber-200' }
    return { label: st, cls: 'bg-muted text-muted-foreground border-border' }
  }
  if (state.loading) {
    return (
      <Card className="p-4 rounded-2xl border-2 flex items-center gap-3 text-sm text-muted-foreground">
        <Loader2 className="w-4 h-4 animate-spin" /> Loading your Ajira history…
      </Card>
    )
  }
  if (state.err && !state.items.length) {
    return null  // Silent — don't clutter Profile if there is no history at all.
  }
  if (!state.items.length) {
    // Show a subtle "no addon yet" card so users know the feature exists.
    return (
      <Card className="p-4 rounded-2xl border-2 flex items-center gap-3">
        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 grid place-items-center text-lg">🌅</div>
        <div className="flex-1 min-w-0">
          <p className="font-bold text-[13.5px]">Ajira Pathya Jojana</p>
          <p className="text-[10.5px] text-muted-foreground">No addon purchases yet. Unlock daily lesson plans for the year.</p>
        </div>
        <ChevronRight className="w-4 h-4 text-muted-foreground" />
      </Card>
    )
  }
  const active = state.active
  return (
    <Card className={`rounded-2xl border-2 overflow-hidden ${active ? 'border-emerald-200 dark:border-emerald-900/60' : 'border-border'}`}>
      {/* Header — current status */}
      <button onClick={() => setExpanded(v => !v)} className="w-full p-4 flex items-center gap-3 text-left hover:bg-muted/40 transition">
        <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-amber-400 to-orange-500 grid place-items-center text-lg shadow-sm">🌅</div>
        <div className="flex-1 min-w-0">
          <p className="font-bold text-[13.5px]">Ajira Pathya Jojana</p>
          {active ? (
            <p className="text-[10.5px] text-emerald-700 dark:text-emerald-300 font-semibold">
              ✅ Active · expires {fmtDate(active.expiresAt)} · <b>{daysLeft(active.expiresAt)} days left</b>
            </p>
          ) : (
            <p className="text-[10.5px] text-muted-foreground">Last purchase expired · view history below</p>
          )}
        </div>
        {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
      </button>

      {/* Expanded — full timeline */}
      {expanded && (
        <div className="border-t border-border bg-muted/20 px-3 py-3 space-y-2">
          {state.items.map(it => {
            const b = statusBadge(it.status)
            return (
              <div key={it.id} className="p-2.5 rounded-xl bg-card border border-border flex items-start gap-2">
                <div className="text-[13px] pt-0.5">{sourceLabel(it.source).split(' ')[0]}</div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <p className="text-[11.5px] font-bold">{sourceLabel(it.source).replace(/^[^\s]+\s/, '')}</p>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border ${b.cls}`}>{b.label}</span>
                  </div>
                  <p className="text-[10px] text-muted-foreground">
                    Purchased: {fmtDate(it.purchasedAt)} · Expires: <b className="text-foreground">{fmtDate(it.expiresAt)}</b>
                    {it.amount ? ` · ₹${it.amount}` : ''}
                    {it.grantedByName ? ` · by ${it.grantedByName}` : ''}
                  </p>
                </div>
              </div>
            )
          })}

          {/* 🔄 Renew / Extend / First-buy CTA — one tap opens Razorpay right here.
              Button copy changes based on current access state so users always
              see the exact action + price they'll be charged. */}
          {status?.pricing?.enabled && (
            <div className="pt-2">
              {active ? (
                <>
                  <Button
                    onClick={startCheckout}
                    disabled={paying || !rzpReady}
                    className="w-full h-11 rounded-2xl font-black text-[13px] bg-gradient-to-r from-emerald-500 via-orange-500 to-rose-500 hover:brightness-110 text-white shadow-md"
                  >
                    {paying ? <Loader2 className="w-4 h-4 animate-spin" /> : (
                      <>🔄 Extend Access · +365 days · ₹{status.priceRupees}</>
                    )}
                  </Button>
                  <p className="text-[9.5px] text-center text-muted-foreground mt-1">
                    Adds 365 days on top of your current expiry ({fmtDate(active.expiresAt)}).
                  </p>
                </>
              ) : (
                <>
                  <Button
                    onClick={startCheckout}
                    disabled={paying || !rzpReady}
                    className="w-full h-11 rounded-2xl font-black text-[13px] bg-gradient-to-r from-orange-500 via-red-500 to-rose-500 hover:brightness-110 text-white shadow-md animate-pulse"
                  >
                    {paying ? <Loader2 className="w-4 h-4 animate-spin" /> : (
                      <>🚀 Renew Ajira Access · ₹{status.priceRupees}</>
                    )}
                  </Button>
                  <p className="text-[9.5px] text-center text-muted-foreground mt-1">
                    Instant 365-day activation · secured by Razorpay
                  </p>
                </>
              )}
            </div>
          )}
        </div>
      )}
    </Card>
  )
}

