const DAY_KEY = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat']

const resolveClassTimetableKey = (className) => {
  const n = (className || '').toLowerCase()
  if (n.includes('balvatika') || n.includes('ବାଳବାଟିକା') || n.includes('shishu') || n.includes('ଶିଶୁ')) return 'balvatika'
  const m = n.match(/(\d+)/)
  if (!m) return null
  const c = Number(m[1])
  if (c >= 1 && c <= 2) return 'class-1-2'
  if (c === 3) return 'class-3'
  if (c === 4 || c === 5) return 'class-4-5'
  if (c >= 6 && c <= 8) return 'class-6-8'
  return null
}
const getTodaysSubjects = (className, dayIdx) => {
  const key = resolveClassTimetableKey(className)
  if (!key || !CLASS_TIMETABLE[key]) return null
  const tt = CLASS_TIMETABLE[key]
  if (tt['mon-fri']) return dayIdx === 6 ? tt['sat'] : (dayIdx === 0 ? null : tt['mon-fri'])
  return tt[DAY_KEY[dayIdx]] || null
}

