// Classwise color palette (used across the Daily Plan wizard & printable output)
// Returns Tailwind classes for: solid bg, soft bg, border, text, and a print HEX color
const getClassColor = (className) => {
  const n = (className || '').toLowerCase()
  // Balvatika / Shishu
  if (n.includes('balvatika') || n.includes('ବାଳବାଟିକା') || n.includes('shishu') || n.includes('ଶିଶୁ')) {
    return { name: 'pink',     solid: 'bg-pink-600 text-white',     soft: 'bg-pink-100 dark:bg-pink-950/30 text-pink-900 dark:text-pink-200',         border: 'border-pink-300 dark:border-pink-900',     accent: 'text-pink-700 dark:text-pink-300',     hex: '#fce7f3', hexBorder: '#ec4899' }
  }
  const m = n.match(/(\d+)/)
  const c = m ? Number(m[1]) : 0
  const palettes = [
    { name: 'rose',    solid: 'bg-rose-600 text-white',    soft: 'bg-rose-100 dark:bg-rose-950/30 text-rose-900 dark:text-rose-200',         border: 'border-rose-300 dark:border-rose-900',    accent: 'text-rose-700 dark:text-rose-300',     hex: '#ffe4e6', hexBorder: '#e11d48' },   // C1
    { name: 'orange',  solid: 'bg-orange-600 text-white',  soft: 'bg-orange-100 dark:bg-orange-950/30 text-orange-900 dark:text-orange-200', border: 'border-orange-300 dark:border-orange-900', accent: 'text-orange-700 dark:text-orange-300', hex: '#ffedd5', hexBorder: '#ea580c' }, // C2
    { name: 'amber',   solid: 'bg-amber-600 text-white',   soft: 'bg-amber-100 dark:bg-amber-950/30 text-amber-900 dark:text-amber-200',    border: 'border-amber-300 dark:border-amber-900',  accent: 'text-amber-700 dark:text-amber-300',   hex: '#fef3c7', hexBorder: '#d97706' }, // C3
    { name: 'yellow',  solid: 'bg-yellow-600 text-white',  soft: 'bg-yellow-100 dark:bg-yellow-950/30 text-yellow-900 dark:text-yellow-200', border: 'border-yellow-300 dark:border-yellow-900', accent: 'text-yellow-700 dark:text-yellow-300', hex: '#fef9c3', hexBorder: '#ca8a04' }, // C4
    { name: 'lime',    solid: 'bg-lime-600 text-white',    soft: 'bg-lime-100 dark:bg-lime-950/30 text-lime-900 dark:text-lime-200',         border: 'border-lime-300 dark:border-lime-900',    accent: 'text-lime-700 dark:text-lime-300',     hex: '#ecfccb', hexBorder: '#65a30d' }, // C5
    { name: 'emerald', solid: 'bg-emerald-600 text-white', soft: 'bg-emerald-100 dark:bg-emerald-950/30 text-emerald-900 dark:text-emerald-200', border: 'border-emerald-300 dark:border-emerald-900', accent: 'text-emerald-700 dark:text-emerald-300', hex: '#d1fae5', hexBorder: '#059669' }, // C6
    { name: 'cyan',    solid: 'bg-cyan-600 text-white',    soft: 'bg-cyan-100 dark:bg-cyan-950/30 text-cyan-900 dark:text-cyan-200',         border: 'border-cyan-300 dark:border-cyan-900',    accent: 'text-cyan-700 dark:text-cyan-300',     hex: '#cffafe', hexBorder: '#0891b2' }, // C7
    { name: 'sky',     solid: 'bg-sky-600 text-white',     soft: 'bg-sky-100 dark:bg-sky-950/30 text-sky-900 dark:text-sky-200',             border: 'border-sky-300 dark:border-sky-900',      accent: 'text-sky-700 dark:text-sky-300',       hex: '#e0f2fe', hexBorder: '#0284c7' }, // C8
    { name: 'indigo',  solid: 'bg-indigo-600 text-white',  soft: 'bg-indigo-100 dark:bg-indigo-950/30 text-indigo-900 dark:text-indigo-200', border: 'border-indigo-300 dark:border-indigo-900', accent: 'text-indigo-700 dark:text-indigo-300', hex: '#e0e7ff', hexBorder: '#4f46e5' }, // C9
    { name: 'purple',  solid: 'bg-purple-600 text-white',  soft: 'bg-purple-100 dark:bg-purple-950/30 text-purple-900 dark:text-purple-200', border: 'border-purple-300 dark:border-purple-900', accent: 'text-purple-700 dark:text-purple-300', hex: '#f3e8ff', hexBorder: '#9333ea' }, // C10
  ]
  if (c >= 1 && c <= 10) return palettes[c - 1]
  return { name: 'slate', solid: 'bg-slate-600 text-white', soft: 'bg-slate-100 text-slate-900', border: 'border-slate-300', accent: 'text-slate-700', hex: '#f1f5f9', hexBorder: '#64748b' }
}

const formatOdiaDate = (iso) => {
  if (!iso) return ''
  const [y, m, d] = iso.split('-')
  return `${d}-${m}-${y}`
}

const DailyPlanView = ({ go, user }) => {
  const exportSettings = useExportSettings()
  const [step, setStep] = useState('wizard') // 'wizard' | 'generating' | 'result'
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10))
  const [schoolName, setSchoolName] = useState('')
  const [classType, setClassType] = useState('single')
  const [classes, setClasses] = useState([])
  const [selectedClassIds, setSelectedClassIds] = useState([])
  const [allBooks, setAllBooks] = useState([])      // books across selected classes
  const [selectedBookIds, setSelectedBookIds] = useState([])
  const [allChapters, setAllChapters] = useState([]) // chapters across selected books
  const [selectedChapterIds, setSelectedChapterIds] = useState([])
  const [allLessons, setAllLessons] = useState([])   // lessons across selected chapters
  const [selectedLessons, setSelectedLessons] = useState([]) // ordered ids, up to 7
  const [arrangeMode, setArrangeMode] = useState('auto') // 'auto' | 'manual'
  // Which columns to include: 'teacher' | 'student' | 'both' (default both)
  const [activityMode, setActivityMode] = useState('both')
  // Layout style: 'detailed' (1 period / landscape page) | 'compact' (2 periods / landscape page, single row each)
  const [layoutStyle, setLayoutStyle] = useState('detailed')
  const [generating, setGenerating] = useState(false)
  const [plan, setPlan] = useState(null)

  // Selected class type → max classes
  const maxClasses = classType === 'single' ? 1 : classType === 'double' ? 2 : classType === 'tini' ? 3 : 7
  const dayIdx = new Date(date + 'T00:00:00Z').getUTCDay()
  const dayLabel = DAY_NAMES_OD[dayIdx]
  const isSat = dayIdx === 6
  const isSun = dayIdx === 0

  // Load classes once
  useEffect(() => {
    api('/classes').then(r => setClasses(r.classes || [])).catch(e => toast.error(e.message))
  }, [])

  // When selected classes change → load all books in those classes
  // When selected classes change → load all books across all selected classes
  useEffect(() => {
    let cancelled = false
    const load = async () => {
      if (!selectedClassIds.length) { setAllBooks([]); setSelectedBookIds([]); return }
      const results = await Promise.all(selectedClassIds.map(cid => api(`/books?classId=${cid}&counts=1`).then(r => (r.books || []).map(b => ({ ...b, _classId: cid })))))
      if (cancelled) return
      const flat = results.flat()
      setAllBooks(flat)
      setSelectedBookIds(prev => prev.filter(id => flat.find(b => b.id === id)))
    }
    load().catch(e => { if (!cancelled) toast.error(e.message) })
    return () => { cancelled = true }
  }, [selectedClassIds])

  // When selected books change → load all chapters in those books
  useEffect(() => {
    let cancelled = false
    const load = async () => {
      if (!selectedBookIds.length) { setAllChapters([]); setSelectedChapterIds([]); return }
      const results = await Promise.all(selectedBookIds.map(bid => api(`/chapters?bookId=${bid}`).then(r => (r.chapters || []).map(c => ({ ...c, _bookId: bid })))))
      if (cancelled) return
      const flat = results.flat()
      setAllChapters(flat)
      setSelectedChapterIds(prev => prev.filter(id => flat.find(c => c.id === id)))
    }
    load().catch(e => { if (!cancelled) toast.error(e.message) })
    return () => { cancelled = true }
  }, [selectedBookIds])

  // When selected chapters change → load all lessons in those chapters
  useEffect(() => {
    let cancelled = false
    const load = async () => {
      if (!selectedChapterIds.length) { setAllLessons([]); setSelectedLessons([]); return }
      const results = await Promise.all(selectedChapterIds.map(cid => api(`/lessons?chapterId=${cid}`).then(r => (r.lessons || []).map(l => ({ ...l, _chapterId: cid })))))
      if (cancelled) return
      const flat = results.flat()
      setAllLessons(flat)
      // keep only existing selections
      setSelectedLessons(prev => prev.filter(id => flat.find(l => l.id === id)))
    }
    load().catch(e => { if (!cancelled) toast.error(e.message) })
    return () => { cancelled = true }
  }, [selectedChapterIds])

  const toggleClass = (cid) => {
    setSelectedClassIds(prev => {
      const has = prev.includes(cid)
      if (has) return prev.filter(x => x !== cid)
      if (prev.length >= maxClasses) {
        if (classType === 'single') return [cid]
        toast.error(`Max ${maxClasses} classes for ${classType}`)
        return prev
      }
      return [...prev, cid]
    })
  }
  const toggleId = (setter, value, max) => {
    setter(prev => {
      const has = prev.includes(value)
      if (has) return prev.filter(x => x !== value)
      if (max && prev.length >= max) { toast.error(`Maximum ${max} allowed`); return prev }
      return [...prev, value]
    })
  }

  const reorderLesson = (idx, dir) => {
    setSelectedLessons(prev => {
      const arr = [...prev]
      const tgt = idx + dir
      if (tgt < 0 || tgt >= arr.length) return prev
      ;[arr[idx], arr[tgt]] = [arr[tgt], arr[idx]]
      return arr
    })
  }

  const handleGenerate = async () => {
    if (!selectedLessons.length) return toast.error('ଅନ୍ତତଃ ୧ଟି ପ୍ରସଙ୍ଗ ବାଛନ୍ତୁ')
    if (isSun) return toast.error('ରବିବାର — ତାରିଖ ବଦଳାନ୍ତୁ')
    setGenerating(true); setStep('generating')
    try {
      const slots = selectedLessons.slice(0, 7).map(id => ({ lessonId: id }))
      const r = await api('/daily-plan/generate', { method: 'POST', body: { date, schoolName, classType, slots } })
      // Attach activity-mode preference so the printable component knows which columns to show
      setPlan({ ...r, activityMode, layoutStyle })
      setStep('result')
      // Enable print mode CSS hook
      document.body.classList.add('has-daily-plan')
    } catch (e) {
      toast.error(e.message)
      setStep('wizard')
    } finally { setGenerating(false) }
  }

  const handlePrint = () => {
    document.body.classList.add('print-mode')
    setTimeout(() => {
      window.print()
      setTimeout(() => document.body.classList.remove('print-mode'), 500)
    }, 100)
  }

  // ===== Word (.doc) download — uses Word's HTML-import support =====
  const handleDownloadWord = () => {
    if (!plan) return
    try {
      const pages = []
      for (let i = 0; i < plan.periods.length; i += 4) pages.push(plan.periods.slice(i, i + 4))
      const dayShort = DAY_NAMES_OD_SHORT[new Date(plan.date + 'T00:00:00Z').getUTCDay()]
      const stripT = (h) => String(h || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()
      const cell = (p, key, idx) => {
        let t = '', s = ''
        if (p?.format === 'fiveE' && Array.isArray(p?.fiveE?.stages)) {
          const stage = p.fiveE.stages[idx]
          if (stage) { t = stripT(stage.teacher || ''); s = stripT(stage.student || '') }
        } else {
          const d = p.panchapadi?.[key] || {}
          t = stripT(d.teacherActivityText || d.teacherActivity || '')
          s = stripT(d.studentActivityText || d.studentActivity || '')
        }
        if (plan.activityMode === 'teacher') return t || '—'
        if (plan.activityMode === 'student') return s || '—'
        return [t && `<b>ଶି:</b> ${t}`, s && `<b>ଛା:</b> ${s}`].filter(Boolean).join('<br/>') || '—'
      }
      const rowsHtml = (rows) => rows.map(p => { return `
        <tr>
          <td style="text-align:center;font-weight:700">${dayShort}</td>
          <td style="text-align:center;font-weight:700">P${p.periodNum}<br/><span style="font-weight:400;font-size:8pt">${p.time}</span></td>
          <td style="background:${getClassColor(p.className).hex};font-weight:700;text-align:center;white-space:nowrap">${p.className || ''}</td>
          <td style="white-space:nowrap">${p.subject || ''}</td>
          <td>${p.topic || p.title || ''}</td>
          <td style="font-size:9pt;text-align:center">${renderDgStackHtml(p, { fontSize: '9pt' })}</td>
          <td style="font-size:9pt;text-align:center;line-height:1.15">${renderLoStackHtml(p, { fontSize: '9pt' })}</td>
          <td>${cell(p, 'prastabana', 0)}</td>
          <td>${cell(p, 'anweshana', 1)}</td>
          <td>${cell(p, 'alochana', 2)}</td>
          <td>${cell(p, 'prayoga', 3)}</td>
          <td>${cell(p, 'mulyayana', 4)}</td>
          <td style="font-size:8pt">${(p.tlm || []).join(', ') || '—'}</td>
        </tr>
      `}).join('')
      const COLS = ['3%','6%','4%','7%','9%','9%','4%','12%','13%','10%','10%','10%','3%']
      const colgroup = `<colgroup>${COLS.map(w => `<col style="width:${w}"/>`).join('')}</colgroup>`
      const pageHtml = (rows, idx, total) => `
        <div style="page-break-after:${idx < total - 1 ? 'always' : 'auto'};position:relative">
          ${exportSettings.showWatermark ? brandWatermarkSvgHtml() : ''}
          <div style="position:relative;z-index:1">
          <div style="border:1.5pt solid #000;border-bottom:0;padding:5px 8px;font-size:11pt;display:flex;justify-content:space-between">
            <span><b>ବିଦ୍ୟାଳୟ:</b> ${plan.schoolName || '__________________'}</span>
            <span><b>ତାରିଖ:</b> ${formatOdiaDate(plan.date)} &nbsp; <b>ବାର:</b> ${plan.day}</span>
            <span style="font-size:9pt">Page ${idx + 1} of ${total}</span>
          </div>
          <table style="width:100%;table-layout:fixed;border-collapse:collapse;font-size:9pt;line-height:1.15" border="1">
            ${colgroup}
            <thead><tr style="background:#fde68a;font-size:11pt;font-weight:700">
              <th>ବାର</th><th>ପିରିୟଡ୍/ସମୟ</th><th>ଶ୍ରେଣୀ</th><th>ବିଷୟ</th><th>ପ୍ରସଙ୍ଗ</th><th>ଦକ୍ଷତା ଲକ୍ଷ୍ୟ (DG)</th><th>LO</th>
              <th>ଅଧୀତି</th><th>ବୋଧ</th><th>ଅଭ୍ୟାସ</th><th>ପ୍ରୟୋଗ</th><th>ପ୍ରସାର</th><th>TLM</th>
            </tr></thead>
            <tbody>${rowsHtml(rows)}</tbody>
          </table>
          ${idx === total - 1 ? `
            <div style="display:flex;justify-content:space-between;margin-top:24pt;padding-top:6pt;gap:8mm">
              <div style="flex:1;text-align:center;font-weight:700;border-top:1pt solid #000;padding-top:8pt">ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର</div>
              <div style="flex:1;text-align:center;font-weight:700;border-top:1pt solid #000;padding-top:8pt">ସହକାରୀ ଶିକ୍ଷକ</div>
              <div style="flex:1;text-align:center;font-weight:700;border-top:1pt solid #000;padding-top:8pt">ପ୍ରଧାନ ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର</div>
            </div>` : ''}
          </div>
        </div>`
      const html = `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head>
  <meta charset="utf-8">
  <title>Daily Lesson Plan</title>
  <!--[if gte mso 9]><xml><w:WordDocument><w:View>Print</w:View><w:Zoom>100</w:Zoom><w:DoNotOptimizeForBrowser/></w:WordDocument></xml><![endif]-->
  <style>
    @page { size: A4 landscape; margin: 5mm; mso-page-orientation: landscape; }
    body { font-family: 'Noto Sans Oriya Embedded', 'Noto Sans Oriya', 'Calibri', 'Inter', system-ui, sans-serif; font-size: 9pt; color: #000; }
    table { border-collapse: collapse; }
    td, th { word-break: normal; overflow-wrap: break-word; }
  </style>
</head>
<body>
  ${pages.map((rows, idx) => pageHtml(rows, idx, pages.length)).join('')}
</body></html>`
      const blob = new Blob(['\ufeff' + html], { type: 'application/msword;charset=utf-8' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `Daily-Lesson-Plan-${plan.date}.doc`
      document.body.appendChild(a)
      a.click()
      setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url) }, 1000)
      toast.success('Word file downloaded')
    } catch (e) {
      toast.error(e.message || 'Word export failed')
    }
  }

  const handleReset = () => {
    setPlan(null); setStep('wizard'); document.body.classList.remove('print-mode')
  }

  // ===== PDF download — server-side Lesson Diary (A4 landscape, new template) =====
  //  Uses the shared /api/instant-plan/pdf endpoint with mode='daily' so the
  //  Daily 7-Period output matches the bilingual "Daily Teaching Diary" PDF
  //  design (colour bands, meta cards, chips, Panchapadi hues).
  const handleDownloadPdf = async () => {
    if (!plan) return
    const tid = toast.loading('PDF ପ୍ରସ୍ତୁତ ହେଉଛି…')
    try {
      const token = typeof window !== 'undefined' ? (localStorage.getItem('em_token') || localStorage.getItem('token') || '') : ''
      const res = await fetch('/api/instant-plan/pdf', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: 'Bearer ' + token } : {}),
        },
        body: JSON.stringify({ plan, mode: 'daily', showWatermark: !!exportSettings.showWatermark }),
      })
      if (!res.ok) {
        const j = await res.json().catch(() => ({}))
        throw new Error(j.error || `PDF generation failed (${res.status})`)
      }
      const blob = await res.blob()
      if (blob.size < 800) throw new Error('Empty PDF received — please retry.')
      const url = URL.createObjectURL(blob)
      const filename = `Daily-7-Period-Lesson-${plan.date || 'today'}.pdf`
      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent || '')
      if (isMobile) {
        try {
          const file = new File([blob], filename, { type: 'application/pdf' })
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({ files: [file], title: filename })
            toast.success('✅ PDF ready — tap Save to Files', { id: tid })
            return
          }
        } catch (shareErr) {
          if (shareErr && shareErr.name === 'AbortError') { toast.dismiss(tid); return }
        }
        window.open(url, '_blank')
        toast.success('📄 PDF opened — tap ⤓ / Share → Save to Files', { id: tid })
        return
      }
      const a = document.createElement('a')
      a.href = url; a.download = filename
      document.body.appendChild(a); a.click(); a.remove()
      setTimeout(() => URL.revokeObjectURL(url), 3000)
      toast.success('PDF ଡାଉନଲୋଡ୍ ହୋଇଗଲା', { id: tid })
    } catch (e) {
      toast.error(e?.message || 'PDF export failed', { id: tid })
    }
  }

  // ============ RESULT VIEW — full-screen landscape Lesson Diary preview ============
  if (step === 'result' && plan) {
    return (
      <LessonDiaryFullScreen
        plan={plan}
        mode="daily"
        showWatermark={!!exportSettings.showWatermark}
        title="ଆଜିର ଶିକ୍ଷଣ ଯୋଜନା · Daily 7-Period Plan"
        filename={`Daily-7-Period-Lesson-${plan.date || 'today'}.pdf`}
        onClose={handleReset}
        allowPdf={exportSettings.showPdf !== false}
        allowPrint={exportSettings.showPrint !== false && exportSettings.lpAllowPrint !== false}
      />
    )
  }

  if (step === 'generating') {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
        <p className="text-sm font-bold">ଶିକ୍ଷଣ ଯୋଜନା ପ୍ରସ୍ତୁତ ହେଉଛି…</p>
        <p className="text-[10px] text-muted-foreground italic max-w-xs text-center">ଏହାକୁ ୧୦-୩୦ ସେକେଣ୍ଡ ଲାଗି ପାରେ (ପ୍ରତ୍ୟେକ ପିରିୟଡ୍‌ର ପଞ୍ଚପଦୀ ସୋପାନ ସୃଷ୍ଟି ହେଉଛି)</p>
      </div>
    )
  }

  // ============ WIZARD ============
  return (
    <div className="space-y-3 pb-24">
      <TopBar title="ଦୈନିକ ଶିକ୍ଷଣ ଯୋଜନା" onBack={() => go('home')} />

      <Card className="p-3 rounded-2xl bg-gradient-to-r from-blue-500 to-indigo-600 text-white border-0">
        <p className="font-extrabold flex items-center gap-2"><CalendarDays className="w-5 h-5" /> ୭ ପିରିୟଡ୍ ଶିକ୍ଷଣ ଯୋଜନା ଜେନେରେଟର</p>
        <p className="text-[11px] opacity-90 mt-1">ତାରିଖ ବାଛନ୍ତୁ → ଶ୍ରେଣୀ → ବିଷୟ → ଅଧ୍ୟାୟ → ପ୍ରସଙ୍ଗ → ପଞ୍ଚପଦୀ ଶିକ୍ଷଣ ଯୋଜନା ସୃଷ୍ଟି କରନ୍ତୁ।</p>
      </Card>

      {/* STEP 1: Date */}
      <Card className="p-3 rounded-2xl space-y-2">
        <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">1</span> ତାରିଖ ବାଛନ୍ତୁ</p>
        <div className="flex items-center gap-2">
          <Input type="date" value={date} onChange={e => setDate(e.target.value)} className="h-10 rounded-xl flex-1" />
          <div className="text-[11px] text-muted-foreground">
            <p className="font-bold">{dayLabel}</p>
            {isSat && <p className="text-amber-600">ଶନିବାର ସମୟ</p>}
            {isSun && <p className="text-red-600">⚠️ ରବିବାର</p>}
          </div>
        </div>
      </Card>

      {/* STEP 2: School Name */}
      <Card className="p-3 rounded-2xl space-y-2">
        <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">2</span> ବିଦ୍ୟାଳୟ ନାମ</p>
        <Input value={schoolName} onChange={e => setSchoolName(e.target.value)} placeholder="ଉଦା: ସରକାରୀ ପ୍ରାଥମିକ ବିଦ୍ୟାଳୟ, ____" className="h-10 rounded-xl" />
      </Card>

      {/* STEP 3: Class Type */}
      <Card className="p-3 rounded-2xl space-y-2">
        <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">3</span> ଶ୍ରେଣୀ ପ୍ରକାର</p>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-1.5">
          {[
            { v: 'single', l: 'ଏକ ଶ୍ରେଣୀ' },
            { v: 'double', l: 'ଦୁଇ ଶ୍ରେଣୀ' },
            { v: 'tini',   l: 'ତିନି ଶ୍ରେଣୀ' },
            { v: 'multi',  l: 'ବହୁ ଶ୍ରେଣୀ' },
          ].map(o => (
            <button key={o.v}
              onClick={() => {
                setClassType(o.v)
                if (o.v === 'single') setSelectedClassIds(prev => prev.slice(0, 1))
                else if (o.v === 'double') setSelectedClassIds(prev => prev.slice(0, 2))
                else if (o.v === 'tini') setSelectedClassIds(prev => prev.slice(0, 3))
                else if (o.v === 'multi') setSelectedClassIds(prev => prev.slice(0, 7))
              }}
              className={`h-9 rounded-xl text-xs font-bold transition border ${classType === o.v ? 'bg-blue-600 text-white border-blue-600' : 'bg-muted text-foreground border-transparent'}`}>
              {o.l}
            </button>
          ))}
        </div>
      </Card>

      {/* STEP 4: Class Selection */}
      <Card className="p-3 rounded-2xl space-y-2">
        <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">4</span> ଶ୍ରେଣୀ ବାଛନ୍ତୁ ({selectedClassIds.length}/{maxClasses})</p>
        <div className="flex flex-wrap gap-1.5">
          {classes.map(c => {
            const col = getClassColor(c.name)
            const selected = selectedClassIds.includes(c.id)
            return (
              <button key={c.id} onClick={() => toggleClass(c.id)}
                className={`px-2.5 h-8 rounded-xl text-[11px] font-bold transition border ${selected ? `${col.solid} border-transparent shadow` : `${col.soft} ${col.border}`}`}>
                {c.emoji} {c.name}
              </button>
            )
          })}
        </div>
      </Card>

      {/* Today's Subjects Hint based on Class + Day-of-Week (per Odisha primary timetable) */}
      {selectedClassIds.length > 0 && !isSun && (() => {
        const hintBlocks = selectedClassIds.map(cid => {
          const cls = classes.find(c => c.id === cid)
          const subjects = getTodaysSubjects(cls?.name, dayIdx)
          return { cls, subjects, color: getClassColor(cls?.name) }
        }).filter(b => b.subjects && b.cls)
        if (!hintBlocks.length) return null
        return (
          <Card className="p-3 rounded-2xl space-y-2">
            <p className="text-xs font-extrabold flex items-center gap-1.5">📅 ଆଜିର ବିଷୟ ସୂଚୀ ({dayLabel})</p>
            {hintBlocks.map(({ cls, subjects, color }) => (
              <div key={cls.id} className={`rounded-xl overflow-hidden border ${color.border}`}>
                <div className={`px-2 py-1 text-[10px] font-extrabold ${color.soft}`}>{cls.emoji} {cls.name}</div>
                <div className="p-1.5 flex flex-wrap gap-1">
                  {subjects.map((s, i) => (
                    <span key={i} className={`px-1.5 py-0.5 rounded text-[10px] ${color.soft} border ${color.border}`}>
                      <b>P{i + 1}:</b> {s}
                    </span>
                  ))}
                </div>
              </div>
            ))}
            <p className="text-[9px] text-muted-foreground italic">💡 ଏହି ସୂଚୀ ଅନୁଯାୟୀ ତଳେ ବିଷୟ ଓ ପ୍ରସଙ୍ଗ ବାଛନ୍ତୁ।</p>
          </Card>
        )
      })()}

      {/* STEP 5: Subjects (grouped by Class for easy selection) */}
      {allBooks.length > 0 && (
        <Card className="p-3 rounded-2xl space-y-2">
          <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">5</span> ବିଷୟ ବାଛନ୍ତୁ ({selectedBookIds.length})</p>
          <p className="text-[10px] text-muted-foreground">💡 ବଇ ପାଖରେ (N) ସେହି ବଇରେ କେତୋଟି ଅଧ୍ୟାୟ ଅଛି ତାହା ଦେଖାଏ। ୦ ଥିଲେ ସେ ବଇ ବାଛିବେ ନାହିଁ।</p>
          <div className="space-y-2 max-h-72 overflow-y-auto">
            {selectedClassIds.map(cid => {
              const cls = classes.find(c => c.id === cid)
              const col = getClassColor(cls?.name)
              const classBooks = allBooks.filter(b => b._classId === cid)
              if (!classBooks.length) {
                return (
                  <div key={cid} className={`border rounded-xl overflow-hidden ${col.border}`}>
                    <div className={`px-2 py-1 text-[10px] font-extrabold flex items-center gap-1.5 ${col.soft}`}>
                      {cls?.emoji} {cls?.name} <span className="opacity-50">· କୌଣସି ବଇ ନାହିଁ</span>
                    </div>
                    <p className="px-2 py-2 text-[10px] text-muted-foreground italic">ଏହି ଶ୍ରେଣୀ ପାଇଁ Admin ତରଫରୁ ବଇ ଯୋଡ଼ାଯାଇନାହିଁ।</p>
                  </div>
                )
              }
              return (
                <div key={cid} className={`border rounded-xl overflow-hidden ${col.border}`}>
                  <div className={`px-2 py-1 text-[10px] font-extrabold flex items-center gap-1.5 ${col.soft}`}>
                    {cls?.emoji} {cls?.name} <span className="opacity-50">({classBooks.length} ବିଷୟ)</span>
                  </div>
                  <div className="p-1.5 grid grid-cols-2 gap-1">
                    {classBooks.map(b => {
                      const selected = selectedBookIds.includes(b.id)
                      const chCount = b.chaptersCount ?? 0
                      const isEmpty = chCount === 0
                      return (
                        <button key={b.id} onClick={() => toggleId(setSelectedBookIds, b.id)}
                          className={`px-2 py-1.5 rounded-lg text-[11px] font-bold transition border text-left flex items-center justify-between gap-1 ${selected ? `${col.solid} border-transparent` : `bg-background ${col.border}`} ${isEmpty ? 'opacity-60' : ''}`}
                          title={isEmpty ? 'ଏହି ବଇରେ ଏବେ କୌଣସି ଅଧ୍ୟାୟ ନାହିଁ' : `${chCount} ଅଧ୍ୟାୟ`}>
                          <span className="truncate">📘 {b.name}</span>
                          <span className={`ml-1 shrink-0 inline-flex items-center justify-center min-w-[20px] h-4 px-1 rounded-full text-[9px] font-extrabold ${selected ? 'bg-white/25' : isEmpty ? 'bg-red-100 text-red-700 dark:bg-red-950/40 dark:text-red-300' : 'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300'}`}>{chCount}</span>
                        </button>
                      )
                    })}
                  </div>
                </div>
              )
            })}
          </div>
        </Card>
      )}

      {/* STEP 6: Chapters (grouped by Class > Book) — always show selected books, even empty ones */}
      {selectedBookIds.length > 0 && (
        <Card className="p-3 rounded-2xl space-y-2">
          <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">6</span> ଅଧ୍ୟାୟ ବାଛନ୍ତୁ ({selectedChapterIds.length})</p>
          <div className="space-y-2 max-h-72 overflow-y-auto">
            {selectedBookIds.map(bid => {
              const book = allBooks.find(b => b.id === bid)
              const cls = book ? classes.find(c => c.id === book._classId) : null
              const bookChapters = allChapters.filter(c => c._bookId === bid)
              const col = getClassColor(cls?.name)
              return (
                <div key={bid} className={`border rounded-xl overflow-hidden ${col.border}`}>
                  <div className={`px-2 py-1 text-[10px] font-extrabold flex items-center gap-1.5 ${col.soft}`}>
                    {cls?.emoji} {cls?.name} <span className="opacity-50">·</span> 📘 {book?.name}
                    <span className="ml-auto text-[9px] opacity-70">{bookChapters.length} ଅଧ୍ୟାୟ</span>
                  </div>
                  {bookChapters.length === 0 ? (
                    <div className="p-2 text-[10px] text-muted-foreground italic">
                      ❌ ଏହି ବଇରେ ଏବେ କୌଣସି ଅଧ୍ୟାୟ ନାହିଁ। Admin Curriculum ରୁ ଯୋଡ଼ନ୍ତୁ ବା ଅନ୍ୟ ବଇ ବାଛନ୍ତୁ।
                    </div>
                  ) : (
                    <div className="p-1.5 flex flex-wrap gap-1">
                      {bookChapters.map(c => {
                        const selected = selectedChapterIds.includes(c.id)
                        return (
                          <button key={c.id} onClick={() => toggleId(setSelectedChapterIds, c.id)}
                            className={`px-2 h-7 rounded-lg text-[11px] font-bold transition border ${selected ? `${col.solid} border-transparent` : `bg-background ${col.border}`}`}>
                            #{c.order} {c.name}
                          </button>
                        )
                      })}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </Card>
      )}

      {/* STEP 7: Lessons (Periods) — grouped by Class > Book > Chapter; always show selected chapters */}
      {selectedChapterIds.length > 0 && (
        <Card className="p-3 rounded-2xl space-y-2">
          <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">7</span> ପ୍ରସଙ୍ଗ ବାଛନ୍ତୁ ({selectedLessons.length}/7)</p>
          <div className="space-y-2 max-h-80 overflow-y-auto">
            {selectedChapterIds.map(cid => {
              const chap = allChapters.find(x => x.id === cid)
              if (!chap) return null
              const book = allBooks.find(b => b.id === chap._bookId)
              const cls = book ? classes.find(c => c.id === book._classId) : null
              const chapterLessons = allLessons.filter(l => l._chapterId === cid)
              const col = getClassColor(cls?.name)
              return (
                <div key={cid} className={`border rounded-xl overflow-hidden ${col.border}`}>
                  <div className={`px-2 py-1 text-[10px] font-extrabold flex items-center gap-1.5 flex-wrap ${col.soft}`}>
                    {cls?.emoji} {cls?.name} <span className="opacity-50">·</span> 📘 {book?.name} <span className="opacity-50">·</span> #{chap?.order} {chap?.name}
                    <span className="ml-auto text-[9px] opacity-70">{chapterLessons.length} ପ୍ରସଙ୍ଗ</span>
                  </div>
                  {chapterLessons.length === 0 ? (
                    <div className="p-2 text-[10px] text-muted-foreground italic">
                      ❌ ଏହି ଅଧ୍ୟାୟରେ ଏବେ କୌଣସି ପ୍ରସଙ୍ଗ ନାହିଁ। Admin Curriculum ରୁ ଯୋଡ଼ନ୍ତୁ।
                    </div>
                  ) : (
                    <div className="p-1.5 space-y-1">
                      {chapterLessons.map(l => {
                        const idx = selectedLessons.indexOf(l.id)
                        const checked = idx >= 0
                        return (
                          <button key={l.id} onClick={() => toggleId(setSelectedLessons, l.id, 7)}
                            className={`w-full text-left px-2.5 py-1.5 rounded-lg text-[11px] transition border flex items-center gap-2 ${checked ? `${col.soft} ${col.border}` : 'bg-muted/40 border-transparent'}`}>
                            <span className={`w-5 h-5 rounded-full text-[9px] font-bold flex items-center justify-center shrink-0 ${checked ? col.solid : 'bg-muted text-muted-foreground'}`}>{checked ? idx + 1 : ''}</span>
                            <span className="flex-1 truncate"><b>P{l.period}</b> · {l.title}</span>
                          </button>
                        )
                      })}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
          {/* Arrange section */}
          {selectedLessons.length > 0 && (
            <div className="border-t pt-2 mt-2 space-y-1.5">
              <p className="text-[10px] font-bold text-muted-foreground">ଅନୁକ୍ରମ ସଜାଣି (7 ପିରିୟଡ୍)</p>
              {selectedLessons.map((lid, i) => {
                const l = allLessons.find(x => x.id === lid)
                if (!l) return null
                const chap = allChapters.find(c => c.id === l._chapterId)
                const book = chap ? allBooks.find(b => b.id === chap._bookId) : null
                const cls = book ? classes.find(c => c.id === book._classId) : null
                const col = getClassColor(cls?.name)
                return (
                  <div key={lid} className={`flex items-center gap-1.5 rounded-lg p-1.5 border ${col.soft} ${col.border}`}>
                    <span className={`w-5 h-5 rounded text-[10px] font-bold flex items-center justify-center ${col.solid}`}>P{i + 1}</span>
                    <span className="text-[10px] flex-1 truncate"><b>{cls?.name}</b> · {l.title}</span>
                    <button onClick={() => reorderLesson(i, -1)} className={`${col.accent} disabled:opacity-30`} disabled={i === 0}><ArrowUp className="w-3.5 h-3.5" /></button>
                    <button onClick={() => reorderLesson(i, 1)} className={`${col.accent} disabled:opacity-30`} disabled={i === selectedLessons.length - 1}><ArrowDown className="w-3.5 h-3.5" /></button>
                    <button onClick={() => toggleId(setSelectedLessons, lid)} className="text-red-500"><Trash2 className="w-3.5 h-3.5" /></button>
                  </div>
                )
              })}
            </div>
          )}
        </Card>
      )}

      {/* STEP 8: Activity columns to include */}
      {selectedLessons.length > 0 && (
        <Card className="p-3 rounded-2xl space-y-2">
          <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">8</span> ଶିକ୍ଷଣ ଯୋଜନାରେ କେଉଁ କାର୍ଯ୍ୟ ଦେଖାଯିବ?</p>
          <div className="grid grid-cols-3 gap-1.5">
            {[
              { v: 'teacher', l: 'କେବଳ ଶିକ୍ଷକ', s: 'Teacher only' },
              { v: 'student', l: 'କେବଳ ଶିକ୍ଷାର୍ଥୀ', s: 'Student only' },
              { v: 'both',    l: 'ଉଭୟ', s: 'Both' },
            ].map(o => (
              <button key={o.v}
                onClick={() => setActivityMode(o.v)}
                className={`h-auto py-2 rounded-xl text-[11px] font-bold transition border flex flex-col items-center justify-center leading-tight ${activityMode === o.v ? 'bg-blue-600 text-white border-blue-600' : 'bg-muted text-foreground border-transparent'}`}>
                <span>{o.l}</span>
                <span className="text-[9px] opacity-70 font-normal">{o.s}</span>
              </button>
            ))}
          </div>
        </Card>
      )}

      {/* STEP 9: Layout style for printable plan */}
      {selectedLessons.length > 0 && (
        <Card className="p-3 rounded-2xl space-y-2">
          <p className="text-xs font-extrabold flex items-center gap-1.5"><span className="bg-blue-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">9</span> ଶିକ୍ଷଣ ଯୋଜନା ଶୈଳୀ</p>
          <div className="grid grid-cols-2 gap-1.5">
            {[
              { v: 'detailed', l: 'ବିସ୍ତୃତ', s: '1 period / page', icon: '📄' },
              { v: 'compact',  l: 'ସଂକ୍ଷିପ୍ତ', s: '2 periods / page', icon: '📋' },
            ].map(o => (
              <button key={o.v}
                onClick={() => setLayoutStyle(o.v)}
                className={`h-auto py-2.5 rounded-xl text-xs font-bold transition border flex flex-col items-center justify-center leading-tight ${layoutStyle === o.v ? 'bg-blue-600 text-white border-blue-600' : 'bg-muted text-foreground border-transparent'}`}>
                <span className="text-base">{o.icon}</span>
                <span>{o.l}</span>
                <span className="text-[9px] opacity-70 font-normal">{o.s}</span>
              </button>
            ))}
          </div>
        </Card>
      )}

      {/* GENERATE button */}
      <Button onClick={handleGenerate} disabled={generating || !selectedLessons.length || isSun}
        className="w-full h-12 rounded-2xl text-sm font-extrabold bg-gradient-to-r from-blue-600 to-indigo-700 hover:opacity-90 shadow-lg">
        {generating ? <Loader2 className="w-4 h-4 animate-spin mr-1" /> : <Sparkles className="w-4 h-4 mr-1" />}
        ଆଜିର ଶିକ୍ଷଣ ଯୋଜନା ପ୍ରସ୍ତୁତ କରନ୍ତୁ
      </Button>
      {!selectedLessons.length && (
        <p className="text-[10px] text-muted-foreground text-center italic">ଅନ୍ତତଃ ୧ଟି ପ୍ରସଙ୍ଗ ବାଛନ୍ତୁ</p>
      )}
    </div>
  )
}

// ===== DETAILED PRINT TEMPLATE — matches attached lesson-plan-style HTML =====
// One period per A4 landscape page. Header table + activity table + signature footer.
// Auto-switches between Panchapadi (lower classes) and 5E (Class 9/10) based on lesson.format.
//
// Helper: returns the activity rows + heading labels appropriate for the lesson's format.
const getActivityRowsForRender = (p, panchapadiSteps) => {
  if (p?.format === 'fiveE' && Array.isArray(p?.fiveE?.stages) && p.fiveE.stages.length > 0) {
    const stageHeader = '5E ସୋପାନ / Stage'
    const teacherHeader = '👨‍🏫 ଶିକ୍ଷକଙ୍କ କାର୍ଯ୍ୟ / Teacher Activity'
    const studentHeader = '🧑‍🎓 ଶିକ୍ଷାର୍ଥୀଙ୍କ କାର୍ଯ୍ୟ / Student Activity'
    const rows = p.fiveE.stages.map((s, i) => {
      const meta = FIVE_E_STAGE_META[s.stage] || { label: s.stage, icon: '⭐' }
      return {
        label: `${i + 1}. ${meta.icon} ${meta.label.toUpperCase()}`,
        time: s.time || '',
        teacher: s.teacher || '',
        student: s.student || '',
      }
    })
    return { rows, stageHeader, teacherHeader, studentHeader, isFiveE: true }
  }
  const stageHeader = 'ସୋପାନ'
  const teacherHeader = 'ଶିକ୍ଷକଙ୍କ କାର୍ଯ୍ୟ'
  const studentHeader = 'ଶିକ୍ଷାର୍ଥୀଙ୍କ କାର୍ଯ୍ୟ'
  const rows = (panchapadiSteps || []).map(s => {
    const d = p.panchapadi?.[s.k] || {}
    return {
      label: s.label,
      time: d.timing || s.time,
      teacher: d.teacherActivityText || d.teacherActivity || '',
      student: d.studentActivityText || d.studentActivity || '',
    }
  })
  return { rows, stageHeader, teacherHeader, studentHeader, isFiveE: false }
}

const PrintDetailedTemplate = ({ plan, watermark = false }) => {
  if (!plan) return null
  const periods = plan.periods || []
  const STEPS = [
    { k: 'prastabana', label: '୧. ଅଧୀତି (Adhiti)',   time: '୫ ମିନିଟ୍' },
    { k: 'anweshana',  label: '୨. ବୋଧ (Bodha)',       time: '୧୫ ମିନିଟ୍' },
    { k: 'alochana',   label: '୩. ଅଭ୍ୟାସ (Abhyasa)',  time: '୧୦ ମିନିଟ୍' },
    { k: 'prayoga',    label: '୪. ପ୍ରୟୋଗ (Prayoga)',  time: '୧୦ ମିନିଟ୍' },
    { k: 'mulyayana',  label: '୫. ପ୍ରସାର (Prasara)',  time: '୫ ମିନିଟ୍' },
  ]
  return (
    <div id="print-view">
      {periods.map((p, idx) => {
        const col = getClassColor(p.className)
        const { rows: activityRows, stageHeader, teacherHeader, studentHeader, isFiveE } = getActivityRowsForRender(p, STEPS)
        return (
          <div key={idx} className="detailed-page" style={{ pageBreakAfter: idx < periods.length - 1 ? 'always' : 'auto' }}>
            {watermark && <PrintBrandWatermark />}
            {/* Header table */}
            <table className="header-table" style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '8px', background: '#fefefe' }}>
              <tbody>
                <tr>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d', width: '34%' }}>ବିଦ୍ୟାଳୟ: {plan.schoolName || '___________________'}</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d', width: '33%', background: col.hex }}>ଶ୍ରେଣୀ: {p.className}</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d', width: '33%' }}>ତାରିଖ: {formatOdiaDate(plan.date)} ({plan.day})</td>
                </tr>
                <tr>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ଅଧ୍ୟାୟ: {p.chapterName || '—'}</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ସମୟ: {p.time}</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ବିଷୟ: {p.subject}</td>
                </tr>
                <tr>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ଶିକ୍ଷକଙ୍କ ନାମ: ________________</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ପ୍ରସଙ୍ଗ: {p.topic || p.title || '—'}</td>
                  <td style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>ପିରିୟଡ୍ ନଂ: {p.periodNum} କାଳାଂଶ {p.loCode ? `· LO: ${p.loCode}` : ''}</td>
                </tr>
                {(p.loDescription || p.learningOutcomes?.length > 0) && (
                  <tr>
                    <td colSpan={3} style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>
                      <span style={{ color: '#2b6cb0', fontWeight: 700 }}>ଶିକ୍ଷଣ ଫଳାଫଳ:</span> {p.loDescription || (p.learningOutcomes || []).map((lo, i) => `${i + 1}. ${lo}`).join(' · ') || '—'}
                    </td>
                  </tr>
                )}
                {p.tlm?.length > 0 && (
                  <tr>
                    <td colSpan={3} style={{ border: '1px solid #888', padding: '6px 10px', fontWeight: 600, color: '#1a365d' }}>
                      <span style={{ color: '#2b6cb0', fontWeight: 700 }}>TLM:</span> {p.tlm.join(' · ')}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>

            {/* Panchapadi table */}
            <table className="panchapadi-table" style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '8px' }}>
              <thead>
                <tr>
                  <th style={{ width: '10%', background: '#e2e8f0', color: '#2d3748', fontWeight: 700, textAlign: 'center', border: '1px solid #888', padding: '6px 10px' }}>{stageHeader}</th>
                  <th style={{ width: '8%',  background: '#e2e8f0', color: '#2d3748', fontWeight: 700, textAlign: 'center', border: '1px solid #888', padding: '6px 10px' }}>ସମୟ</th>
                  {(plan.activityMode !== 'student') && (
                    <th style={{ width: plan.activityMode === 'teacher' ? '82%' : '41%', background: '#e2e8f0', color: '#2d3748', fontWeight: 700, textAlign: 'center', border: '1px solid #888', padding: '6px 10px' }}>{teacherHeader}</th>
                  )}
                  {(plan.activityMode !== 'teacher') && (
                    <th style={{ width: plan.activityMode === 'student' ? '82%' : '41%', background: '#e2e8f0', color: '#2d3748', fontWeight: 700, textAlign: 'center', border: '1px solid #888', padding: '6px 10px' }}>{studentHeader}</th>
                  )}
                </tr>
              </thead>
              <tbody>
                {activityRows.map((row, i) => {
                  const bg = i % 2 === 1 ? '#f7fafc' : '#ffffff'
                  return (
                    <tr key={i} style={{ background: bg }}>
                      <td style={{ width: '10%', fontWeight: 700, textAlign: 'center', border: '1px solid #888', padding: '6px 10px', verticalAlign: 'top' }}>{row.label}</td>
                      <td style={{ width: '8%',  textAlign: 'center', border: '1px solid #888', padding: '6px 10px', verticalAlign: 'top' }}>{row.time}</td>
                      {(plan.activityMode !== 'student') && (
                        <td style={{ border: '1px solid #888', padding: '6px 10px', verticalAlign: 'top' }} dangerouslySetInnerHTML={{ __html: row.teacher || '—' }} />
                      )}
                      {(plan.activityMode !== 'teacher') && (
                        <td style={{ border: '1px solid #888', padding: '6px 10px', verticalAlign: 'top' }} dangerouslySetInnerHTML={{ __html: row.student || '—' }} />
                      )}
                    </tr>
                  )
                })}
              </tbody>
            </table>

            {p.homework && (
              <div style={{ fontSize: '12px', margin: '6px 0', color: '#333' }}><b>🏠 ଗୃହକାର୍ଯ୍ୟ:</b> {p.homework}</div>
            )}

            {/* Footer signatures */}
            <div className="detailed-footer" style={{ display: 'flex', justifyContent: 'space-between', marginTop: 'auto', fontSize: '14px', color: '#4a5568' }}>
              <div>ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର: _________________</div>
              <div>ସହକାରୀ ଶିକ୍ଷକ: _________________</div>
              <div>ପ୍ରଧାନ ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର: _________________</div>
            </div>
          </div>
        )
      })}
    </div>
  )
}


// ============================================================
//  LessonDiaryTable · Shared Odisha "Daily Teaching Diary" renderer
//
//  Used by:
//    • Daily 7-Period Lesson  (mode='daily')
//    • Instant Daily Plan     (mode='instant')
//    • Multigrade Lesson Plan (mode='multigrade')
//
//  Column order (17):
//    Day → Period → Class → Subject → Chapter → Topic
//    → Curricular Goal → Competency → LO Code → Learning Outcome
//    → Adhiti → Bodha → Abhyasa → Prayoga → Prasara
//    → TLM → Assessment
//
//  Rowspan rule: Day / Class / Subject / Chapter / CG / Competency /
//  LO Code / Learning Outcome — merge across consecutive rows when
//  the value is IDENTICAL.  Panchapadi + TLM + Assessment are ALWAYS
//  period-specific and never merged.
//
//  Multigrade: one row per (Period × Class) — each class's Panchapadi
//  is rendered separately even when the Period number matches.
//
//  Renders identically on-screen and via window.print() (A4 landscape).
// ============================================================

const DIARY_COLUMNS = [
  { key: 'day',       label: 'ଦିନ / ତାରିଖ',              en: 'Day / Date',       band: 1, mergeable: true,  width: '5%'  },
  { key: 'period',    label: 'ପିରିୟଡ୍',                    en: 'Period',           band: 1,                   width: '4%'  },
  { key: 'className', label: 'ଶ୍ରେଣୀ',                    en: 'Class',            band: 1, mergeable: true,  width: '4%'  },
  { key: 'subject',   label: 'ବିଷୟ',                       en: 'Subject',          band: 1, mergeable: true,  width: '5%'  },
  { key: 'chapter',   label: 'ଅଧ୍ୟାୟ',                     en: 'Chapter',          band: 2, mergeable: true,  width: '6%'  },
  { key: 'topic',     label: 'ପ୍ରସଙ୍ଗ / ବିଷୟବସ୍ତୁ',      en: 'Topic',            band: 2,                   width: '7%'  },
  { key: 'cg',        label: 'ପାଠ୍ୟକ୍ରମ ଲକ୍ଷ୍ୟ',          en: 'Curricular Goal',  band: 2, mergeable: true, mono: true, width: '5%' },
  { key: 'competency',label: 'ଦକ୍ଷତା',                    en: 'Competency',       band: 2, mergeable: true,  width: '7%'  },
  { key: 'loCode',    label: 'LO ସଂକେତ',                   en: 'LO Code',          band: 2, mergeable: true, mono: true, width: '4%' },
  { key: 'lo',        label: 'ଶିକ୍ଷଣ ଫଳାଫଳ',              en: 'Learning Outcome', band: 2, mergeable: true,  width: '8%'  },
  { key: 'adhiti',    label: 'ଅଧୀତି',                      en: 'Adhiti',           band: 3, step: 'adhiti',  width: '7.5%' },
  { key: 'bodha',     label: 'ବୋଧ',                        en: 'Bodha',            band: 3, step: 'bodha',   width: '7.5%' },
  { key: 'abhyasa',   label: 'ଅଭ୍ୟାସ',                    en: 'Abhyasa',          band: 3, step: 'abhyasa', width: '7.5%' },
  { key: 'prayoga',   label: 'ପ୍ରୟୋଗ',                    en: 'Prayoga',          band: 3, step: 'prayoga', width: '7.5%' },
  { key: 'prasara',   label: 'ପ୍ରସାର',                     en: 'Prasara',          band: 3, step: 'prasara', width: '7.5%' },
  { key: 'tlm',       label: 'TLM',                          en: 'TLM',              band: 4, tlm: true,      width: '6%'  },
  { key: 'assessment',label: 'ମୂଲ୍ୟାୟନ',                  en: 'Assessment',       band: 4, assess: true,   width: '7%'  },
]

// Panchapadi step palette — each stage gets its own hue so the five
// steps are immediately distinguishable in print.  Header uses the
// saturated colour, body uses a very light tint for readability.
const DIARY_STEP_PALETTE = {
  adhiti:  { headBg: '#1d4ed8', headFg: '#ffffff', body: '#eff6ff' },  // blue
  bodha:   { headBg: '#0f766e', headFg: '#ffffff', body: '#f0fdfa' },  // teal
  abhyasa: { headBg: '#c2410c', headFg: '#ffffff', body: '#fff7ed' },  // orange
  prayoga: { headBg: '#be185d', headFg: '#ffffff', body: '#fdf2f8' },  // pink
  prasara: { headBg: '#7c3aed', headFg: '#ffffff', body: '#faf5ff' },  // purple
}

const DIARY_BANDS = [
  { id: 1, cols: 4, label: 'ବୈଦିନିକ ବିବରଣୀ',              en: 'Daily Details',           bg: '#1e3a8a', color: '#ffffff' },   // deep blue
  { id: 2, cols: 6, label: 'ପାଠ୍ୟ ବିବରଣୀ',                en: 'Lesson Details',          bg: '#b45309', color: '#ffffff' },   // amber/gold
  { id: 3, cols: 5, label: 'ପଞ୍ଚପଦୀ ଶିକ୍ଷଣ ପ୍ରକ୍ରିୟା',    en: 'Panchapadi Teaching Process', bg: '#6b21a8', color: '#ffffff' },   // deep purple
  { id: 4, cols: 2, label: 'ଶିକ୍ଷଣ ସହାୟକ ଓ ମୂଲ୍ୟାୟନ',   en: 'Support & Assessment',    bg: '#065f46', color: '#ffffff' },   // deep green
]

// Helper: pull a single Panchapadi cell's plain text from a period.
// Handles both the "steps[]" shape (Daily/Instant) and "panchapadi{}" (AI generator).
function _diaryPanchapadiText(p, stageKey) {
  if (!p) return ''
  if (p.panchapadi && p.panchapadi[stageKey]) {
    const s = p.panchapadi[stageKey]
    const bits = [
      s.teacherActivity && `👨‍🏫 ${s.teacherActivity}`,
      s.studentActivity && `🎒 ${s.studentActivity}`,
      s.duration && `⏱ ${s.duration}`,
    ].filter(Boolean)
    return bits.join('\n')
  }
  const stageMap = { adhiti: 'prastabana', bodha: 'anweshana', abhyasa: 'alochana', prayoga: 'prayoga', prasara: 'mulyayana' }
  const legacyKey = stageMap[stageKey]
  const step = (p.steps || []).find(s => s.key === legacyKey || s.stage === stageKey)
  if (!step) return ''
  const bits = [
    step.teacherActivity && `👨‍🏫 ${step.teacherActivity}`,
    step.studentActivity && `🎒 ${step.studentActivity}`,
    step.duration && `⏱ ${step.duration}`,
  ].filter(Boolean)
  if (bits.length) return bits.join('\n')
  return String(step.text || step.content || step.description || '').trim()
}

function _diaryFieldSummary(p) {
  const dgCodes = (typeof getDgStack === 'function' && p) ? (getDgStack(p) || []) : []
  const cg = dgCodes.length ? dgCodes.join(', ') : (p?.curricularGoal || p?.cgCode || '')
  const loEntries = (typeof getAllLoEntries === 'function' && p) ? (getAllLoEntries(p) || []) : []
  const foundational = loEntries.find(e => e.isFoundational) || loEntries[0]
  const loCode = foundational?.displayCode || (Array.isArray(p?.loCodes) ? p.loCodes[0] : (p?.loCode || ''))
  const loText = foundational?.text || p?.loDescription
    || (Array.isArray(p?.learningOutcomes) && p.learningOutcomes[0])
    || ''
  const competency = p?.competencyText || foundational?.competencyText || ''
  const tlm = Array.isArray(p?.tlm) && p.tlm.length ? p.tlm.join(' · ') : (p?.tlm || '')
  const assessment = p?.assessment || p?.assessmentQuestion || p?.exitTicket || p?.evaluation
    || (Array.isArray(p?.assessmentQuestions) && p.assessmentQuestions.join(' · ')) || ''
  return { cg, competency, loCode, loText, tlm, assessment }
}

function _buildDiaryRows(plan, mode) {
  const dayLabel = plan?.day && plan?.date
    ? `${plan.day}\n${(typeof formatOdiaDate === 'function') ? formatOdiaDate(plan.date) : plan.date}`
    : (plan?.day || plan?.date || '')

  // MULTIGRADE (single-period shape): plan has plan.classes[] at TOP
  // level plus plan.periodNumber / plan.time — not the periods[] array
  // shape used by Daily/Instant.  Synthesize one row per class.
  if (mode === 'multigrade' && Array.isArray(plan?.classes) && plan.classes.length && !Array.isArray(plan?.periods)) {
    const rows = []
    for (const cls of plan.classes) {
      const summary = _diaryFieldSummary(cls)
      rows.push({
        day: dayLabel,
        period: plan.periodNumber ? `P${plan.periodNumber}${plan.time ? `\n${plan.time}` : ''}` : (plan.time || ''),
        className: cls.className || '',
        subject: cls.subject || cls.bookName || '',
        chapter: cls.chapterName || cls.chapter || '',
        topic: cls.topic || cls.title || '',
        cg: summary.cg,
        competency: summary.competency,
        loCode: summary.loCode,
        lo: summary.loText,
        adhiti:  _diaryPanchapadiText(cls, 'adhiti'),
        bodha:   _diaryPanchapadiText(cls, 'bodha'),
        abhyasa: _diaryPanchapadiText(cls, 'abhyasa'),
        prayoga: _diaryPanchapadiText(cls, 'prayoga'),
        prasara: _diaryPanchapadiText(cls, 'prasara'),
        tlm: summary.tlm || (Array.isArray(cls.tlm) ? cls.tlm.join(' · ') : ''),
        assessment: summary.assessment,
      })
    }
    return rows
  }

  const periods = Array.isArray(plan?.periods) ? plan.periods : []
  const rows = []
  for (const p of periods) {
    if (mode === 'multigrade' && Array.isArray(p.classes) && p.classes.length) {
      for (const cls of p.classes) {
        const summary = _diaryFieldSummary({ ...p, ...cls })
        rows.push({
          day: dayLabel,
          period: p.periodNum ? `P${p.periodNum}${p.time ? `\n${p.time}` : ''}` : (p.time || ''),
          className: cls.className || cls.class || '',
          subject: cls.subject || p.subject || '',
          chapter: cls.chapterName || cls.chapter || p.chapterName || '',
          topic: cls.topic || cls.title || p.topic || p.title || '',
          cg: summary.cg,
          competency: summary.competency,
          loCode: summary.loCode,
          lo: summary.loText,
          adhiti:  _diaryPanchapadiText(cls, 'adhiti')  || _diaryPanchapadiText(p, 'adhiti'),
          bodha:   _diaryPanchapadiText(cls, 'bodha')   || _diaryPanchapadiText(p, 'bodha'),
          abhyasa: _diaryPanchapadiText(cls, 'abhyasa') || _diaryPanchapadiText(p, 'abhyasa'),
          prayoga: _diaryPanchapadiText(cls, 'prayoga') || _diaryPanchapadiText(p, 'prayoga'),
          prasara: _diaryPanchapadiText(cls, 'prasara') || _diaryPanchapadiText(p, 'prasara'),
          tlm: summary.tlm || (Array.isArray(cls.tlm) ? cls.tlm.join(' · ') : ''),
          assessment: summary.assessment,
        })
      }
    } else {
      const summary = _diaryFieldSummary(p)
      rows.push({
        day: dayLabel,
        period: p.periodNum ? `P${p.periodNum}${p.time ? `\n${p.time}` : ''}` : (p.time || ''),
        className: p.className || plan?.className || '',
        subject: p.subject || plan?.subject || '',
        chapter: p.chapterName || p.chapter || '',
        topic: p.topic || p.title || '',
        cg: summary.cg,
        competency: summary.competency,
        loCode: summary.loCode,
        lo: summary.loText,
        adhiti:  _diaryPanchapadiText(p, 'adhiti'),
        bodha:   _diaryPanchapadiText(p, 'bodha'),
        abhyasa: _diaryPanchapadiText(p, 'abhyasa'),
        prayoga: _diaryPanchapadiText(p, 'prayoga'),
        prasara: _diaryPanchapadiText(p, 'prasara'),
        tlm: summary.tlm,
        assessment: summary.assessment,
      })
    }
  }
  return rows
}

function _computeDiaryRowspans(rows) {
  const spans = rows.map(() => ({}))
  const mergeableKeys = DIARY_COLUMNS.filter(c => c.mergeable).map(c => c.key)
  for (const colKey of mergeableKeys) {
    let i = 0
    while (i < rows.length) {
      const val = String(rows[i][colKey] ?? '').trim()
      let j = i + 1
      while (val && j < rows.length && String(rows[j][colKey] ?? '').trim() === val) j++
      const span = j - i
      spans[i][colKey] = { first: true, span }
      for (let k = i + 1; k < j; k++) spans[k][colKey] = { first: false }
      i = j
    }
  }
  return spans
}

const LessonDiaryTable = ({ plan, mode = 'daily' }) => {
  useEffect(() => { if (typeof hydrateLoCodes === 'function') hydrateLoCodes() }, [])
  if (!plan) return null
  const rows = _buildDiaryRows(plan, mode)
  const spans = _computeDiaryRowspans(rows)
  const meta = {
    school:   plan.schoolName || plan.school || '',
    teacher:  plan.teacherName || plan.teacher || '',
    className:plan.className || (rows[0]?.className || ''),
    subject:  plan.subject || (rows[0]?.subject || ''),
    book:     plan.bookName || plan.book || '',
    chapter:  plan.chapterName || plan.chapter || (rows[0]?.chapter || ''),
    duration: plan.duration || plan.periodTime || '',
    learners: plan.learnersCount || plan.learners || '',
    date:     (typeof formatOdiaDate === 'function' && plan.date) ? formatOdiaDate(plan.date) : (plan.date || ''),
  }
  const modeTitle = mode === 'daily' ? '(Daily 7-Period)' : mode === 'instant' ? '(Instant Daily)' : mode === 'multigrade' ? '(Multigrade)' : ''

  return (
    <div className="lesson-diary-wrap">
      <style dangerouslySetInnerHTML={{ __html: `
        .lesson-diary-wrap { color: #0f172a; font-family: 'Inter', 'Noto Sans Oriya', sans-serif; }
        .lesson-diary-header { border: 2px solid #0f172a; border-bottom: 0; background: #f8fafc; padding: 6px 8px; }
        .lesson-diary-title { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; margin-bottom: 4px; padding-bottom: 4px; border-bottom: 2px solid #0f172a; }
        .lesson-diary-title h1 { font-size: 14px; font-weight: 800; margin: 0; line-height: 1.15; }
        .lesson-diary-title p  { font-size: 8.5px; color: #475569; margin: 0; }
        .lesson-diary-meta { display: grid; grid-template-columns: repeat(4, 1fr); gap: 3px 6px; font-size: 9.5px; }
        .lesson-diary-meta div { border: 1px solid #cbd5e1; padding: 2px 5px; background: #ffffff; border-radius: 3px; }
        .lesson-diary-meta b { display: block; font-size: 8px; color: #64748b; font-weight: 700; letter-spacing: 0.3px; }
        .lesson-diary-table { width: 100%; min-width: 1600px; border-collapse: collapse; border: 2px solid #0f172a; font-size: 9px; table-layout: fixed; }
        .lesson-diary-table thead th { padding: 4px 4px; text-align: center; border: 1px solid #0f172a; vertical-align: middle; font-weight: 800; letter-spacing: 0.2px; }
        .lesson-diary-table thead .band-row th { font-size: 11px; padding: 5px 4px; }
        .lesson-diary-table thead .col-row th { font-size: 9.5px; }
        .lesson-diary-table thead .col-head-en { display: block; font-weight: 600; font-size: 8.5px; opacity: 0.85; margin-top: 1px; }
        .lesson-diary-table tbody td { padding: 4px 5px; border: 1px solid #94a3b8; vertical-align: top; word-break: break-word; overflow-wrap: anywhere; white-space: pre-line; line-height: 1.3; font-size: 9px; }
        .lesson-diary-table tbody td.mono { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 9px; color: #6d28d9; font-weight: 700; text-align: center; }
        .lesson-diary-table tbody td.tlm-cell { background: #ecfdf5; }
        .lesson-diary-table tbody td.assess-cell { background: #fef3c7; }
        .lesson-diary-table tbody tr { page-break-inside: avoid; }
        .lesson-diary-footer { border: 2px solid #0f172a; border-top: 0; padding: 6px 10px; display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        .lesson-diary-footer .sig-block { border-top: 1px solid #0f172a; padding-top: 4px; font-size: 9px; text-align: center; margin-top: 24px; }
        .lesson-diary-footer .headmaster { font-size: 10px; font-weight: 700; margin-bottom: 4px; }
        @media print {
          @page { size: A4 landscape !important; margin: 6mm 8mm; }
          html, body { width: 297mm !important; }
          .lesson-diary-wrap { color: #000 !important; }
          .lesson-diary-table { min-width: 0; font-size: 7pt; page-break-inside: auto; }
          .lesson-diary-table thead { display: table-header-group; }
          .lesson-diary-table tfoot { display: table-footer-group; }
          .lesson-diary-table thead th { font-size: 7.5pt; padding: 3px; }
          .lesson-diary-table thead .band-row th { font-size: 8.5pt; }
          .lesson-diary-table tbody td { font-size: 7pt; padding: 3px 4px; line-height: 1.2; }
          .lesson-diary-header, .lesson-diary-footer { page-break-inside: avoid; }
          .lesson-diary-table th, .lesson-diary-table td { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        }
        .lesson-diary-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; }
      ` }} />

      <div className="lesson-diary-header">
        <div className="lesson-diary-title">
          <div>
            <h1>ଦୈନନ୍ଦିନ ଶିକ୍ଷଣ ଡାଏରୀ · DAILY TEACHING DIARY {modeTitle}</h1>
            <p>NEP 2020 / OCF-SE 2025 · Lesson Guru Odisha</p>
          </div>
          <div style={{ textAlign: 'right', fontSize: 9, color: '#475569' }}>
            <div>{meta.date || '—'}</div>
            <div>ପୃଷ୍ଠା · Page 1</div>
          </div>
        </div>
        <div className="lesson-diary-meta">
          <div><b>ବିଦ୍ୟାଳୟ · SCHOOL</b>{meta.school || '—'}</div>
          <div><b>ଶିକ୍ଷକ · TEACHER</b>{meta.teacher || '—'}</div>
          <div><b>ଶ୍ରେଣୀ · CLASS</b>{meta.className || '—'}</div>
          <div><b>SUBJECT</b>{meta.subject || '—'}</div>
          <div><b>ପୁସ୍ତକ · BOOK</b>{meta.book || '—'}</div>
          <div><b>ଅଧ୍ୟାୟ · CHAPTER</b>{meta.chapter || '—'}</div>
          <div><b>ପ୍ରାୟ · DURATION</b>{meta.duration || '—'}</div>
          <div><b>ଛାତ୍ର · LEARNERS</b>{meta.learners || '—'}</div>
        </div>
      </div>

      <div className="lesson-diary-scroll">
        <table className="lesson-diary-table">
          <colgroup>
            {DIARY_COLUMNS.map(c => <col key={c.key} style={{ width: c.width }} />)}
          </colgroup>
          <thead>
            <tr className="band-row">
              {DIARY_BANDS.map(b => (
                <th key={b.id} colSpan={b.cols} style={{ background: b.bg, color: b.color }}>
                  {b.label}<div style={{ fontSize: 8.5, fontWeight: 600, opacity: 0.9 }}>{b.en}</div>
                </th>
              ))}
            </tr>
            <tr className="col-row">
              {DIARY_COLUMNS.map(c => {
                const band = DIARY_BANDS.find(b => b.id === c.band)
                const step = c.step ? DIARY_STEP_PALETTE[c.step] : null
                const bg = step ? step.headBg : band.bg
                const fg = step ? step.headFg : band.color
                return (
                  <th key={c.key} style={{ background: bg, color: fg }}>
                    {c.label}
                    <span className="col-head-en" style={{ color: fg }}>{c.en}</span>
                  </th>
                )
              })}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i}>
                {DIARY_COLUMNS.map(c => {
                  const sp = spans[i][c.key]
                  if (c.mergeable && sp && !sp.first) return null
                  const rowSpan = sp?.span || 1
                  const step = c.step ? DIARY_STEP_PALETTE[c.step] : null
                  const classes = [
                    c.mono ? 'mono' : '',
                    c.tlm ? 'tlm-cell' : '',
                    c.assess ? 'assess-cell' : '',
                  ].filter(Boolean).join(' ')
                  const cellStyle = step ? { background: step.body } : undefined
                  return (
                    <td key={c.key} rowSpan={rowSpan > 1 ? rowSpan : undefined} className={classes} style={cellStyle}>
                      {row[c.key] || '—'}
                    </td>
                  )
                })}
              </tr>
            ))}
            {rows.length === 0 && (
              <tr><td colSpan={DIARY_COLUMNS.length} style={{ textAlign: 'center', padding: 20, color: '#94a3b8' }}>No lesson data to display.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="lesson-diary-footer">
        <div>
          <div className="headmaster">ପ୍ରଧାନ ଶିକ୍ଷକଙ୍କ ମତାମତ · HEADMASTER'S REMARKS</div>
          <div style={{ minHeight: 32, borderBottom: '1px dashed #94a3b8' }} />
          <div className="sig-block">ପ୍ରଧାନ ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର · Headmaster's Signature</div>
        </div>
        <div>
          <div className="headmaster">ପଞ୍ଚପଦୀ ଶିକ୍ଷଣ ଯୋଜନା · Lesson Guru Odisha</div>
          <div style={{ minHeight: 32, borderBottom: '1px dashed #94a3b8' }} />
          <div className="sig-block">ଶିକ୍ଷକଙ୍କ ସ୍ୱାକ୍ଷର · Teacher's Signature</div>
        </div>
      </div>
    </div>
  )
}


// ============================================================
//  LessonDiaryFullScreen · full-screen landscape HTML preview
// ------------------------------------------------------------
//  Shown right after a plan is generated in the Daily 7-Period,
//  Instant Daily, and Multigrade sections.  Fetches the server-
//  rendered Lesson Diary HTML (POST /api/instant-plan/html) — the
//  SAME markup used for the PDF — and shows it inside an iframe so
//  the on-screen preview matches the downloaded PDF exactly.
//  Toolbar exposes Print (native, via the iframe) + Download PDF.
// ============================================================
function LessonDiaryFullScreen({ plan, mode = 'instant', showWatermark = true, title = 'Lesson Diary', filename = 'Lesson-Diary.pdf', onClose, allowPdf = true, allowPrint = true }) {
  const [html, setHtml] = useState('')
  const [loading, setLoading] = useState(true)
  const [err, setErr] = useState('')
  const [pdfBusy, setPdfBusy] = useState(false)
  const [ifrH, setIfrH] = useState(640)
  const iframeRef = useRef(null)

  const authToken = () => (typeof window !== 'undefined' ? (localStorage.getItem('em_token') || localStorage.getItem('token') || '') : '')

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setLoading(true); setErr('')
      try {
        const tk = authToken()
        const res = await fetch('/api/instant-plan/html', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', ...(tk ? { Authorization: 'Bearer ' + tk } : {}) },
          body: JSON.stringify({ plan, mode, showWatermark }),
        })
        const j = await res.json().catch(() => ({}))
        if (!res.ok) throw new Error(j.error || `Preview failed (${res.status})`)
        if (!cancelled) setHtml(j.html || '')
      } catch (e) {
        if (!cancelled) setErr(e.message || 'Preview failed')
      } finally {
        if (!cancelled) setLoading(false)
      }
    })()
    return () => { cancelled = true }
  }, [plan, mode, showWatermark])

  const onFrameLoad = () => {
    try {
      const doc = iframeRef.current?.contentDocument
      if (doc && doc.body) setIfrH(Math.max(560, doc.body.scrollHeight + 32))
    } catch {}
  }

  const doPrint = () => {
    const ifr = iframeRef.current
    if (!ifr || !ifr.contentWindow) { toast.error('Preview not ready yet'); return }
    try { ifr.contentWindow.focus(); ifr.contentWindow.print() }
    catch { toast.error('Print failed — please use Download PDF instead') }
  }

  const doDownloadPdf = async () => {
    if (pdfBusy) return
    setPdfBusy(true)
    const tid = toast.loading('📄 Generating PDF…')
    try {
      const tk = authToken()
      const res = await fetch('/api/instant-plan/pdf', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', ...(tk ? { Authorization: 'Bearer ' + tk } : {}) },
        body: JSON.stringify({ plan, mode, showWatermark }),
      })
      if (!res.ok) { const j = await res.json().catch(() => ({})); throw new Error(j.error || `PDF failed (${res.status})`) }
      const blob = await res.blob()
      if (blob.size < 800) throw new Error('Empty PDF received — please retry.')
      toast.dismiss(tid)
      const saved = savePdfBlobOrError(blob, filename)
      if (saved) toast.success('✅ PDF downloaded')
    } catch (e) {
      toast.dismiss(tid); toast.error(e.message || 'PDF download failed')
    } finally { setPdfBusy(false) }
  }

  return (
    <div className="fixed inset-0 z-[120] bg-neutral-900/95 flex flex-col">
      {/* Toolbar */}
      <div className="flex items-center gap-2 px-3 py-2 bg-neutral-950 text-white shadow-lg shrink-0">
        <Button size="sm" variant="ghost" onClick={onClose} className="h-9 rounded-lg text-white hover:bg-white/10 px-2">
          <ArrowLeft className="w-4 h-4 mr-1" /> <span className="hidden sm:inline">Back</span>
        </Button>
        <div className="flex-1 text-center text-[12px] sm:text-sm font-bold truncate px-1">{title}</div>
        {allowPrint && (
          <Button size="sm" onClick={doPrint} className="h-9 rounded-lg bg-blue-600 hover:bg-blue-700">
            <Printer className="w-4 h-4 sm:mr-1" /> <span className="hidden sm:inline">Print</span>
          </Button>
        )}
        {allowPdf && (
          <Button size="sm" onClick={doDownloadPdf} disabled={pdfBusy} className="h-9 rounded-lg bg-emerald-600 hover:bg-emerald-700">
            {pdfBusy ? <Loader2 className="w-4 h-4 sm:mr-1 animate-spin" /> : <Download className="w-4 h-4 sm:mr-1" />} <span className="hidden sm:inline">PDF</span>
          </Button>
        )}
        <Button size="sm" variant="ghost" onClick={onClose} className="h-9 w-9 p-0 rounded-lg text-white hover:bg-white/10">
          <X className="w-5 h-5" />
        </Button>
      </div>
      {/* Preview body */}
      <div className="flex-1 overflow-auto p-2 sm:p-4 md:p-6">
        {loading && (
          <div className="flex flex-col items-center justify-center h-full text-white/80 gap-3">
            <Loader2 className="w-8 h-8 animate-spin" />
            <p className="text-sm">Preparing landscape preview…</p>
          </div>
        )}
        {!loading && err && (
          <div className="flex flex-col items-center justify-center h-full text-red-200 gap-3">
            <AlertCircle className="w-8 h-8" />
            <p className="text-sm text-center max-w-md">{err}</p>
            <Button size="sm" onClick={onClose} variant="secondary">Close</Button>
          </div>
        )}
        {!loading && !err && (
          <div className="mx-auto bg-white shadow-2xl rounded-sm overflow-auto" style={{ width: 'min(100%, 1123px)' }}>
            <iframe
              ref={iframeRef}
              title="Lesson Diary Preview"
              srcDoc={html}
              onLoad={onFrameLoad}
              className="block border-0 bg-white"
              style={{ width: '1123px', maxWidth: '100%', height: ifrH }}
            />
          </div>
        )}
      </div>
    </div>
  )
}


// ============================================================
//  InstantPlanResult · Result-mode header with Print + Download-PDF CTAs
// ------------------------------------------------------------
//  Isolated from InstantPlanView so we can use hooks (useState for pdfBusy)
//  without polluting the giant parent component.  Handles Odia font-safe
//  landscape PDF download via /api/instant-plan/pdf.
// ============================================================
function InstantPlanResult({ plan, resetToDaily, handlePrint, exportSettings, api }) {
  const [pdfBusy, setPdfBusy] = useState(false)
  const [lastPdfUrl, setLastPdfUrl] = useState(null)

  const filename = `Instant-Daily-Lesson-Plan-${plan.date || 'today'}.pdf`

  const downloadPdf = async () => {
    if (pdfBusy) return
    setPdfBusy(true)
    try {
      const token = typeof window !== 'undefined' ? (localStorage.getItem('em_token') || localStorage.getItem('token') || '') : ''
      const res = await fetch('/api/instant-plan/pdf', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: 'Bearer ' + token } : {}),
        },
        body: JSON.stringify({ plan, showWatermark: exportSettings.showWatermark }),
      })
      if (!res.ok) {
        const j = await res.json().catch(() => ({}))
        throw new Error(j.error || `PDF generation failed (${res.status})`)
      }
      const blob = await res.blob()
      if (blob.size < 800) throw new Error('Empty PDF received. Please retry.')
      const url = URL.createObjectURL(blob)
      setLastPdfUrl(url)
      const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent || '')
      if (isMobile) {
        try {
          const file = new File([blob], filename, { type: 'application/pdf' })
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({ files: [file], title: filename })
            toast.success('✅ PDF ready — tap Save to Files')
            return
          }
        } catch (shareErr) {
          if (shareErr && shareErr.name === 'AbortError') return
        }
        window.open(url, '_blank')
        toast.success('📄 PDF opened — tap ⤓ / Share → Save to Files')
        return
      }
      const a = document.createElement('a')
      a.href = url
      a.download = filename
      document.body.appendChild(a); a.click(); a.remove()
      toast.success('⬇ ' + filename + ' downloaded!')
    } catch (e) {
      toast.error(e.message || 'PDF download failed')
    } finally {
      setPdfBusy(false)
    }
  }

  const openPdf = () => {
    if (!lastPdfUrl) return
    window.open(lastPdfUrl, '_blank', 'noopener,noreferrer')
  }

  return (
    <LessonDiaryFullScreen
      plan={plan}
      mode="instant"
      showWatermark={!!exportSettings.showWatermark}
      title="ଆଜିର ଶିକ୍ଷଣ ଯୋଜନା · Instant Daily Plan"
      filename={`Instant-Daily-Lesson-Plan-${plan.date || 'today'}.pdf`}
      onClose={resetToDaily}
      allowPdf={true}
      allowPrint={exportSettings.showPrint !== false && exportSettings.lpAllowPrint !== false}
    />
  )
}

