// ============================================================
//  TeachingPlanCard · Panchapadi Sopana + TLM for a single period
// ------------------------------------------------------------
//  Reads BOTH shapes we support:
//    • Panchapadi (Class 1-8)  → p.panchapadi = { prastabana, anweshana, alochana, prayoga, mulyayana }
//        each with { teacherActivityText | teacherActivity, studentActivityText | studentActivity, timing }
//    • 5E (Class 9-10)         → p.fiveE.stages = [ { name, teacher, student, minutes }, ... ]
//
//  Explicitly "Not specified" for missing fields per the spec (never
//  silently hides the section).
// ============================================================
const PANCHAPADI_STEPS = [
  { key: 'prastabana', label: 'ଅଧୀତି',   en: 'Adhiti · Introduction' },
  { key: 'anweshana',  label: 'ବୋଧ',     en: 'Bodha · Comprehension' },
  { key: 'alochana',   label: 'ଅଭ୍ୟାସ',  en: 'Abhyasa · Practice' },
  { key: 'prayoga',    label: 'ପ୍ରୟୋଗ',  en: 'Prayoga · Application' },
  { key: 'mulyayana',  label: 'ପ୍ରସାର',  en: 'Prasar · Extension' },
]

function TeachingPlanCard({ period: p }) {
  if (!p) return null
  const col = getClassColor(p.className)
  // Build the 5-step teaching flow from whichever data shape is present.
  const isFiveE = p?.format === 'fiveE' && Array.isArray(p?.fiveE?.stages) && p.fiveE.stages.length > 0
  const steps = PANCHAPADI_STEPS.map((s, idx) => {
    if (isFiveE) {
      const stage = p.fiveE.stages[idx] || {}
      return {
        label: s.label,
        en: stage.name || s.en,
        time: stage.minutes ? `${stage.minutes} ${'min'}` : (stage.timing || ''),
        teacher: stripHtml(stage.teacher || ''),
        student: stripHtml(stage.student || ''),
      }
    }
    const d = p.panchapadi?.[s.key] || {}
    return {
      label: s.label,
      en: s.en,
      time: d.timing || d.duration || d.minutes || '',
      teacher: stripHtml(d.teacherActivityText || d.teacherActivity || ''),
      student: stripHtml(d.studentActivityText || d.studentActivity || ''),
    }
  })
  const hasAnyStep = steps.some(s => s.teacher || s.student)
  const tlmItems = Array.isArray(p.tlm) ? p.tlm.filter(t => String(t || '').trim()) : []

  return (
    <div className="teaching-plan-card">
      <div className="tp-header" style={{ borderLeft: `4px solid ${col.hexBorder || col.hex}` }}>
        <div className="tp-header-title">
          <span className="tp-badge" style={{ background: col.hex }}>P{p.periodNum}</span>
          <b>{p.className}</b> · {p.subject}
          {(p.chapterTitle || p.chapterName) && <> · <span className="tp-chapter">{p.chapterTitle || p.chapterName}</span></>}
          {p.lessonTitle && p.lessonTitle !== (p.chapterTitle || p.chapterName) && <> · {p.lessonTitle}</>}
        </div>
        <div className="tp-header-meta">{p.time}</div>
      </div>

      {/* 📖 Panchapadi Sopana */}
      <div className="tp-section-label">📖 ପଞ୍ଚପଦୀ ସୋପାନ · Panchapadi Sopana</div>
      {hasAnyStep ? (
        <table className="tp-panchapadi">
          <colgroup>
            <col style={{ width: '18%' }} />
            <col style={{ width: '10%' }} />
            <col style={{ width: '72%' }} />
          </colgroup>
          <thead>
            <tr>
              <th>ସୋପାନ<br/><span className="th-en">Step</span></th>
              <th>ସମୟ<br/><span className="th-en">Time</span></th>
              <th>ଶିକ୍ଷଣ-ଶିକ୍ଷଣ ପ୍ରକ୍ରିୟା<br/><span className="th-en">Teaching-Learning Process</span></th>
            </tr>
          </thead>
          <tbody>
            {steps.map((s, i) => (
              <tr key={i} className="tp-step-row">
                <td className="tp-step-label"><b>{s.label}</b><br/><span className="tp-step-en">{s.en}</span></td>
                <td className="tp-step-time">{s.time || '—'}</td>
                <td>
                  {s.teacher && <div><b>ଶିକ୍ଷକ · Teacher:</b> {s.teacher}</div>}
                  {s.student && <div style={{ marginTop: 3 }}><b>ଛାତ୍ର · Student:</b> {s.student}</div>}
                  {!s.teacher && !s.student && <span className="tp-empty">Not specified</span>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      ) : (
        <div className="tp-empty-block">Panchapadi Sopana: Not specified</div>
      )}

      {/* 🎨 TLM */}
      <div className="tp-section-label" style={{ marginTop: '4mm' }}>🎨 ଶିକ୍ଷଣ-ଶିକ୍ଷଣ ସାମଗ୍ରୀ · TLM</div>
      {tlmItems.length ? (
        <div className="tp-tlm">
          {tlmItems.map((t, i) => <span key={i} className="tp-tlm-chip">✓ {t}</span>)}
        </div>
      ) : (
        <div className="tp-empty-block">TLM: Not specified</div>
      )}
    </div>
  )
}

