// =================== ROOT APP ===================
// ===================== PWA Install App (button + banner + iOS instructions) =====================
// Custom hook: tracks beforeinstallprompt event + standalone-mode detection.
const usePwaInstall = () => {
  const [deferred, setDeferred] = useState(null)
  const [installed, setInstalled] = useState(false)
  const [isIos, setIsIos] = useState(false)
  const [isStandalone, setIsStandalone] = useState(false)

  useEffect(() => {
    if (typeof window === 'undefined') return
    // Detect standalone (already installed and launched)
    const standalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true
    setIsStandalone(standalone)
    // Detect iOS (Safari iOS doesn't fire beforeinstallprompt — show manual instructions)
    const ua = String(navigator.userAgent || '').toLowerCase()
    const ios = /iphone|ipad|ipod/.test(ua) && !/crios|fxios/.test(ua)
    setIsIos(ios)
    // Capture install prompt
    const onPrompt = (e) => { e.preventDefault(); setDeferred(e) }
    const onInstalled = () => { setInstalled(true); setDeferred(null); toast.success('🎉 App installed successfully!') }
    window.addEventListener('beforeinstallprompt', onPrompt)
    window.addEventListener('appinstalled', onInstalled)
    return () => {
      window.removeEventListener('beforeinstallprompt', onPrompt)
      window.removeEventListener('appinstalled', onInstalled)
    }
  }, [])

  const triggerInstall = useCallback(async () => {
    if (!deferred) return false
    deferred.prompt()
    const choice = await deferred.userChoice
    setDeferred(null)
    return choice?.outcome === 'accepted'
  }, [deferred])

  return { canInstall: !!deferred, installed, isIos, isStandalone, triggerInstall }
}

// ===================== INSTANT DAILY LESSON PLAN =====================
// One-time weekly timetable setup. Once configured, teacher just picks a date and
// the app loads that weekday's timetable automatically, then reuses the existing
// `/api/daily-plan/generate` endpoint + Panchapadi / 5E renderers to produce the
// full day's printable plan in one click. Holidays can be marked per-date and
// skip the generate step.
const DAY_NAMES_EN = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
// Standard school timings used by the existing Daily 7-Period Plan tool — re-used here
// so the Instant Daily Plan defaults match the rest of the platform.  Each period
// remains individually editable in the wizard / daily preview.
const WEEKDAY_PERIOD_TIMES  = ['10:15 – 11:00', '11:00 – 11:45', '11:55 – 12:40', '12:40 – 01:25', '02:10 – 02:50', '02:50 – 03:30', '03:30 – 04:00']
const SATURDAY_PERIOD_TIMES = ['06:45 – 07:30', '07:30 – 08:15', '08:25 – 09:10', '09:10 – 09:55', '10:40 – 11:20', '11:20 – 12:00', '12:00 – 12:30']
const getDefaultPeriodTimes = (weekday) => (weekday === 6 ? SATURDAY_PERIOD_TIMES : WEEKDAY_PERIOD_TIMES)
// Kept for backward-compat (unused now but referenced elsewhere if any)
const DEFAULT_PERIOD_TIMES = WEEKDAY_PERIOD_TIMES

// Single-period row picker — cascading Class > Book > Chapter > Lesson dropdowns
const PeriodRowPicker = ({ value, onChange, classes, classIds, allowedClassIds }) => {
  const [books, setBooks] = useState([])
  const [chapters, setChapters] = useState([])
  const [lessons, setLessons] = useState([])
  // Use the timetable's chosen classes
  const availableClasses = classes.filter(c => (allowedClassIds || classIds).includes(c.id))
  useEffect(() => {
    if (!value.classId) { setBooks([]); return }
    api(`/books?classId=${value.classId}`).then(r => setBooks(r.books || [])).catch(() => setBooks([]))
  }, [value.classId])
  useEffect(() => {
    if (!value.bookId) { setChapters([]); return }
    api(`/chapters?bookId=${value.bookId}`).then(r => setChapters(r.chapters || [])).catch(() => setChapters([]))
  }, [value.bookId])
  useEffect(() => {
    if (!value.chapterId) { setLessons([]); return }
    api(`/lessons?chapterId=${value.chapterId}`).then(r => setLessons(r.lessons || [])).catch(() => setLessons([]))
  }, [value.chapterId])
  return (
    <div className="grid grid-cols-2 gap-1.5">
      <select value={value.classId || ''} onChange={(e) => onChange({ ...value, classId: e.target.value, bookId: '', chapterId: '', lessonId: '' })} className="h-9 rounded-lg border bg-background text-xs px-1.5">
        <option value="">🏫 ଶ୍ରେଣୀ</option>
        {availableClasses.map(c => <option key={c.id} value={c.id}>{c.emoji} {c.name}</option>)}
      </select>
      <select value={value.bookId || ''} onChange={(e) => onChange({ ...value, bookId: e.target.value, chapterId: '', lessonId: '' })} disabled={!value.classId} className="h-9 rounded-lg border bg-background text-xs px-1.5">
        <option value="">📘 ବିଷୟ</option>
        {books.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
      </select>
      <select value={value.chapterId || ''} onChange={(e) => onChange({ ...value, chapterId: e.target.value, lessonId: '' })} disabled={!value.bookId} className="h-9 rounded-lg border bg-background text-xs px-1.5">
        <option value="">📄 ଅଧ୍ୟାୟ</option>
        {chapters.map(c => <option key={c.id} value={c.id}>#{c.order} {c.name}</option>)}
      </select>
      <select value={value.lessonId || ''} onChange={(e) => onChange({ ...value, lessonId: e.target.value })} disabled={!value.chapterId} className="h-9 rounded-lg border bg-background text-xs px-1.5">
        <option value="">📝 ପ୍ରସଙ୍ଗ</option>
        {lessons.map(l => <option key={l.id} value={l.id}>P{l.period} · {(l.title || '').slice(0, 30)}</option>)}
      </select>
    </div>
  )
}

const InstantPlanView = ({ go, user }) => {
  useEffect(() => { hydrateLoCodes() }, [])
  const exportSettings = useExportSettings()
  const [loading, setLoading] = useState(true)
  const [classes, setClasses] = useState([])
  const [timetable, setTimetable] = useState(null)
  const [mode, setMode] = useState('loading')  // loading | setup | daily | generating | result
  const [setupStep, setSetupStep] = useState(1)
  const [plan, setPlan] = useState(null)

  // Setup wizard state
  const [classType, setClassType] = useState('single')
  const [selectedClassIds, setSelectedClassIds] = useState([])
  const [weekly, setWeekly] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] })
  const [activeDay, setActiveDay] = useState(1)
  const maxClasses = classType === 'single' ? 1 : classType === 'double' ? 2 : classType === 'tini' ? 3 : 7

  // Daily mode state
  // Always start at TODAY's date — recomputed at mount and refreshed when the
  // tab/window becomes visible again so the teacher never sees a stale date
  // carried over from a previous day.
  const computeTodayISO = () => { const t = new Date(); t.setHours(0, 0, 0, 0); return t.toISOString().slice(0, 10) }
  const [selectedDate, setSelectedDate] = useState(computeTodayISO)
  // Keep `selectedDate` in sync with today on focus / visibility change so that if
  // the user keeps the app open across midnight, or returns to the tab the next day,
  // the date silently updates to the current calendar day.
  useEffect(() => {
    const refreshToToday = () => {
      const today = computeTodayISO()
      setSelectedDate(prev => (prev === today ? prev : today))
    }
    refreshToToday()
    if (typeof window === 'undefined') return
    const onVis = () => { if (document.visibilityState === 'visible') refreshToToday() }
    window.addEventListener('focus', refreshToToday)
    document.addEventListener('visibilitychange', onVis)
    // Re-check every 5 minutes as a safety net (handles long-open dashboards).
    const interval = setInterval(refreshToToday, 5 * 60 * 1000)
    return () => {
      window.removeEventListener('focus', refreshToToday)
      document.removeEventListener('visibilitychange', onVis)
      clearInterval(interval)
    }
  }, [])
  const [dayType, setDayType] = useState('working')
  const [todaysPeriods, setTodaysPeriods] = useState([])
  const [savePermanently, setSavePermanently] = useState(false)
  const [editingPeriodIdx, setEditingPeriodIdx] = useState(null)
  const [schoolName, setSchoolName] = useState('')
  // Step 8 + 9 (same options as the existing Daily 7-Period Plan generator)
  const [activityMode, setActivityMode] = useState('both')    // 'teacher' | 'student' | 'both'
  const [layoutStyle, setLayoutStyle] = useState('detailed')  // 'detailed' | 'compact'
  // Per-slot progress hint: lessonId → { period, totalInChapter, chapterName }
  const [lessonMeta, setLessonMeta] = useState({})

  // Derived: weekday number 0-6 from selectedDate
  const weekday = useMemo(() => new Date(selectedDate + 'T00:00:00').getDay(), [selectedDate])
  const isHolidayDate = useMemo(() => (timetable?.holidays || []).includes(selectedDate), [timetable, selectedDate])

  // Initial load: classes + timetable
  useEffect(() => {
    Promise.all([
      api('/classes').catch(() => ({ classes: [] })),
      api('/me/timetable').catch(() => ({ timetable: null })),
    ]).then(([cls, tt]) => {
      setClasses(cls.classes || [])
      if (tt.timetable && tt.timetable.setupComplete) {
        setTimetable(tt.timetable)
        setClassType(tt.timetable.classType || 'single')
        setSelectedClassIds(tt.timetable.classIds || [])
        setWeekly(tt.timetable.weekly || {})
        setMode('daily')
      } else {
        setMode('setup')
        if (tt.timetable) {
          setClassType(tt.timetable.classType || 'single')
          setSelectedClassIds(tt.timetable.classIds || [])
          setWeekly(tt.timetable.weekly || { 1: [], 2: [], 3: [], 4: [], 5: [], 6: [] })
        }
      }
      setLoading(false)
    })
  }, [])

  // 🔁 ONE-TIME BACKFILL: For teachers who set up their timetable before the
  // auto-mirror feature landed (typical case: only Monday configured, other
  // Mon-Sat days empty) — silently mirror the first-populated Mon-Sat day to
  // every empty Mon-Sat day. Sunday NEVER inherits (No School by default).
  // No-op once all Mon-Sat days are populated. Runs on first mount in daily mode.
  const mirroredRef = useRef(false)
  useEffect(() => {
    if (mode !== 'daily' || !timetable || mirroredRef.current) return
    const w = timetable.weekly || {}
    // Detect the "only-one-day-filled" gap.
    const monSatFilled = [1, 2, 3, 4, 5, 6].filter(d => Array.isArray(w[d] || w[String(d)]) && (w[d] || w[String(d)]).length > 0)
    const monSatEmpty = [1, 2, 3, 4, 5, 6].filter(d => !Array.isArray(w[d] || w[String(d)]) || (w[d] || w[String(d)]).length === 0)
    if (monSatFilled.length === 0 || monSatEmpty.length === 0) { mirroredRef.current = true; return }
    mirroredRef.current = true
    ;(async () => {
      try {
        const r = await api('/me/timetable/mirror-empty-days', { method: 'POST' })
        if (r?.timetable && Array.isArray(r?.filledDays) && r.filledDays.length) {
          setTimetable(r.timetable)
          setWeekly(r.timetable.weekly || {})
          toast.success(`🔁 Weekly template auto-applied to ${r.filledDays.length} more day${r.filledDays.length > 1 ? 's' : ''}`, { duration: 4000 })
        }
      } catch (_) { /* non-blocking */ }
    })()
  }, [mode, timetable?.id])

  // 🎯 DATE-BASED AUTO-PROGRESSION: When the teacher picks a date in daily mode,
  // sync the timetable forward for THIS weekday based on how many weeks have passed
  // since the last anchor for that weekday. Going backwards is a no-op. Runs BEFORE
  // the periods-recompute effect below so the freshly-advanced slots are what render.
  const syncedForDateRef = useRef({})
  useEffect(() => {
    if (mode !== 'daily' || !timetable) return
    const key = `${timetable.id || 'anon'}::${selectedDate}`
    if (syncedForDateRef.current[key]) return
    syncedForDateRef.current[key] = true
    let cancelled = false
    ;(async () => {
      try {
        const r = await api('/me/timetable/sync-to-date', { method: 'POST', body: { date: selectedDate } })
        if (cancelled) return
        if (r?.timetable) setTimetable(r.timetable)
        if (r?.weeksDiff > 0 && Array.isArray(r?.moves) && r.moves.length) {
          toast.success(`🎯 Auto-advanced ${r.moves.length} period${r.moves.length > 1 ? 's' : ''} for this date (+${r.weeksDiff} week${r.weeksDiff > 1 ? 's' : ''})`)
        }
      } catch (_) { /* non-blocking */ }
    })()
    return () => { cancelled = true }
  }, [selectedDate, mode, timetable?.id])

  // When the date or timetable changes in daily mode, recompute today's periods + holiday flag.
  // Also backfill blank times with the day-appropriate schedule (weekday vs Saturday) so the
  // teacher always sees the standard school timings unless they override them.
  useEffect(() => {
    if (mode !== 'daily' || !timetable) return
    const wd = new Date(selectedDate + 'T00:00:00').getDay()
    const dayPeriods = (timetable.weekly && (timetable.weekly[wd] || timetable.weekly[String(wd)])) || []
    const defaults = getDefaultPeriodTimes(wd)
    setTodaysPeriods(dayPeriods.map((p, i) => ({
      ...p,
      time: (p.time && p.time.trim()) ? p.time : (defaults[i] || ''),
    })))
    setDayType((timetable.holidays || []).includes(selectedDate) ? 'holiday' : 'working')
    setEditingPeriodIdx(null)
  }, [selectedDate, timetable, mode])

  // Reset all of today's period times back to the standard school schedule.
  const resetTimingsToStandard = () => {
    const wd = new Date(selectedDate + 'T00:00:00').getDay()
    const defaults = getDefaultPeriodTimes(wd)
    setTodaysPeriods(arr => arr.map((p, i) => ({ ...p, time: defaults[i] || '' })))
    toast.success('🕐 Restored standard school timings')
  }

  // ===== Setup helpers =====
  const ensureDayPeriods = (day) => {
    if (!Array.isArray(weekly[day]) || weekly[day].length === 0) {
      const times = getDefaultPeriodTimes(day)
      const seed = Array.from({ length: 7 }, (_, i) => ({
        periodNumber: i + 1, time: times[i],
        classId: selectedClassIds[0] || '', bookId: '', chapterId: '', lessonId: '',
      }))
      setWeekly(w => ({ ...w, [day]: seed }))
      return seed
    }
    // Backfill missing times based on the day-appropriate schedule (don't overwrite user edits)
    const defaults = getDefaultPeriodTimes(day)
    let needsBackfill = false
    const filled = weekly[day].map((p, i) => {
      if (!p.time || !p.time.trim()) { needsBackfill = true; return { ...p, time: defaults[i] || '' } }
      return p
    })
    if (needsBackfill) setWeekly(w => ({ ...w, [day]: filled }))
    return filled
  }
  const updateDayPeriod = (day, idx, patch) => {
    setWeekly(w => ({
      ...w,
      [day]: (w[day] || []).map((p, i) => i === idx ? { ...p, ...patch } : p),
    }))
  }
  const copyDayToAll = (sourceDay) => {
    const src = weekly[sourceDay] || []
    if (!src.length) return toast.error('Source day is empty')
    if (!confirm('Copy this day to all other working days (Mon–Sat)?')) return
    const nw = { ...weekly }
    for (let d = 1; d <= 6; d++) {
      if (d !== sourceDay) nw[d] = src.map(p => ({ ...p }))
    }
    setWeekly(nw)
    toast.success('Copied to all days ✅')
  }
  const saveSetup = async () => {
    if (!selectedClassIds.length) return toast.error('Step 2: ଶ୍ରେଣୀ ବାଛନ୍ତୁ')
    try {
      const r = await api('/me/timetable', { method: 'PUT', body: {
        classType, classIds: selectedClassIds, weekly, setupComplete: true,
      } })
      setTimetable(r.timetable)
      if (r.timetable?.weekly) setWeekly(r.timetable.weekly)
      // Reset the client-side "already mirrored" guard so the daily view can
      // pick up the latest server state without a page reload.
      mirroredRef.current = true
      if (r.mirroredFrom) {
        toast.success(`💾 Saved · Weekly template auto-mirrored from ${DAY_NAMES_OD[r.mirroredFrom]} to all working days 🎯`, { duration: 5000 })
      } else {
        toast.success('💾 ସମୟ ସାରଣୀ ସଂରକ୍ଷିତ ହୋଇଗଲା!')
      }
      setMode('daily')
    } catch (e) { toast.error(e.message) }
  }

  // ===== Daily mode actions =====
  const toggleHoliday = async (mark) => {
    try {
      await api('/me/timetable/holiday', { method: 'POST', body: { date: selectedDate, mark } })
      // refresh timetable holidays from server
      const r = await api('/me/timetable')
      if (r.timetable) setTimetable(r.timetable)
      setDayType(mark ? 'holiday' : 'working')
      toast.success(mark ? '🎉 Marked as holiday' : '📚 Marked as working day')
    } catch (e) { toast.error(e.message) }
  }
  const saveTodayEditsPermanently = async () => {
    try {
      await api('/me/timetable/day', { method: 'POST', body: { weekday, periods: todaysPeriods } })
      // refresh
      const r = await api('/me/timetable')
      if (r.timetable) setTimetable(r.timetable)
      toast.success('💾 Permanently saved to weekly timetable')
    } catch (e) { toast.error(e.message) }
  }
  // Resolve lesson metadata (period number + chapter total) for each populated slot so we
  // can show "Period 3 / 15" hints in the daily preview. Runs whenever todaysPeriods changes.
  useEffect(() => {
    let cancelled = false
    const load = async () => {
      const meta = {}
      const lessonIds = todaysPeriods.map(p => p.lessonId).filter(Boolean)
      if (!lessonIds.length) { setLessonMeta({}); return }
      // Fetch lesson + chapter info for each slot in parallel
      await Promise.all(lessonIds.map(async (lid) => {
        try {
          const r = await api(`/lessons/${lid}`)
          const l = r.lesson || r
          if (!l) return
          // Get total periods in that chapter
          let total = null, chapterName = ''
          if (l.chapterId) {
            try {
              const cr = await api(`/chapters?bookId=${l.bookId || ''}`)
              const ch = (cr.chapters || []).find(c => c.id === l.chapterId)
              chapterName = ch?.name || ''
              total = ch?.totalPeriods || null
            } catch {}
          }
          meta[lid] = { period: l.period, totalInChapter: total, chapterName, title: l.title }
        } catch {}
      }))
      if (!cancelled) setLessonMeta(meta)
    }
    load()
    return () => { cancelled = true }
  }, [todaysPeriods])

  const generatePlan = async () => {
    const slots = todaysPeriods.filter(p => p.lessonId).map(p => ({ lessonId: p.lessonId }))
    if (!slots.length) return toast.error('No periods configured with a lesson — please edit timetable first.')
    if (savePermanently) await saveTodayEditsPermanently()
    setMode('generating')
    try {
      const r = await api('/daily-plan/generate', { method: 'POST', body: { date: selectedDate, schoolName, classType, slots, activityMode, layoutStyle } })
      setPlan({ ...r, activityMode, layoutStyle })
      // NOTE: Auto-progression is now driven by date-based sync (`/me/timetable/sync-to-date`),
      // which fires whenever the teacher picks a new date. Calling /advance here as well would
      // double-advance the slots, so this legacy post-Generate advancement has been removed.
      setMode('result')
      document.body.classList.add('has-daily-plan')
    } catch (e) {
      toast.error(e.message)
      setMode('daily')
    }
  }
  const resetToDaily = () => { setPlan(null); setMode('daily'); document.body.classList.remove('print-mode', 'has-daily-plan') }
  const handlePrint = () => {
    document.body.classList.add('print-mode')
    setTimeout(() => { window.print(); setTimeout(() => document.body.classList.remove('print-mode'), 500) }, 100)
  }

  // ===== Render =====
  if (loading) return <div className="flex items-center justify-center min-h-screen"><Loader2 className="w-8 h-8 animate-spin text-primary" /></div>

  // ----- RESULT -----
  if (mode === 'result' && plan) {
    return <InstantPlanResult plan={plan} resetToDaily={resetToDaily} handlePrint={handlePrint} exportSettings={exportSettings} api={api} />
  }

  if (mode === 'generating') {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-3 p-6 text-center">
        <Loader2 className="w-10 h-10 animate-spin text-primary" />
        <p className="font-bold">ଆଜିର ଶିକ୍ଷଣ ଯୋଜନା ତିଆରି ହେଉଛି...</p>
        <p className="text-xs text-muted-foreground">ସମସ୍ତ ୭ଟି ପିରିୟଡ Panchapadi / 5E ସୋପାନ ସହ ସୃଷ୍ଟି ହେଉଛି।</p>
      </div>
    )
  }

  // ----- SETUP WIZARD -----
  if (mode === 'setup') {
    return (
      <div className="space-y-3 pb-24 px-2">
        <TopBar title="📅 ତୁରନ୍ତ ଦୈନିକ ଶିକ୍ଷଣ ଯୋଜନା" onBack={() => go('dashboard')} />

        {/* Hero */}
        <Card className="p-4 rounded-2xl border-0 bg-gradient-to-br from-fuchsia-600 via-purple-600 to-indigo-700 text-white">
          <p className="font-extrabold text-base">✨ ଗୋଟିଏ-ଥର Setup କରନ୍ତୁ, ପ୍ରତିଦିନ One-Click ରେ Plan ପାଆନ୍ତୁ</p>
          <p className="text-[11px] opacity-95 mt-1">ସାପ୍ତାହିକ ସମୟ ସାରଣୀ ଥରେ ସେଟ୍ କରନ୍ତୁ → ପ୍ରତିଦିନ ତାରିଖ ଦେଲେ ସେହି ଦିନର ଯୋଜନା ଗୋଟିଏ ଟ୍ୟାପ୍ ରେ!</p>
        </Card>

        {/* Step progress */}
        <Card className="p-3 rounded-2xl border-2">
          <div className="flex items-center justify-between">
            {[1, 2, 3, 4].map(n => (
              <div key={n} className="flex items-center gap-1 flex-1">
                <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-extrabold ${setupStep >= n ? 'bg-fuchsia-600 text-white' : 'bg-muted text-muted-foreground'}`}>{n}</div>
                {n < 4 && <div className={`h-0.5 flex-1 ${setupStep > n ? 'bg-fuchsia-600' : 'bg-muted'}`} />}
              </div>
            ))}
          </div>
          <p className="text-[10px] mt-1.5 text-center text-muted-foreground">{['ଶ୍ରେଣୀ ପ୍ରକାର', 'ଶ୍ରେଣୀ ବାଛନ୍ତୁ', 'ସମୟ ସାରଣୀ', 'ସଂରକ୍ଷଣ'][setupStep - 1]}</p>
        </Card>

        {/* Step 1: Class Type */}
        {setupStep === 1 && (
          <Card className="p-4 rounded-2xl border-2 space-y-3">
            <p className="font-extrabold text-sm">ଶ୍ରେଣୀ ପ୍ରକାର ବାଛନ୍ତୁ</p>
            <div className="grid grid-cols-2 gap-2">
              {[
                { v: 'single', l: 'Single Class', o: 'ଏକ ଶ୍ରେଣୀ' },
                { v: 'double', l: 'Double Class', o: 'ଦୁଇ ଶ୍ରେଣୀ' },
                { v: 'tini',   l: 'Triple Class', o: 'ତିନି ଶ୍ରେଣୀ' },
                { v: 'multi',  l: 'Multigrade',   o: 'ବହୁ ଶ୍ରେଣୀ (5-7)' },
              ].map(o => (
                <button key={o.v} onClick={() => { setClassType(o.v); setSelectedClassIds([]) }} className={`p-3 rounded-xl border-2 text-left transition ${classType === o.v ? 'border-fuchsia-500 bg-fuchsia-50 dark:bg-fuchsia-950/30' : 'border-transparent bg-muted'}`}>
                  <p className="text-sm font-bold">{o.l}</p>
                  <p className="text-[10px] text-muted-foreground">{o.o}</p>
                </button>
              ))}
            </div>
            <Button onClick={() => setSetupStep(2)} className="w-full rounded-xl bg-fuchsia-600 hover:bg-fuchsia-700">Next →</Button>
          </Card>
        )}

        {/* Step 2: Classes */}
        {setupStep === 2 && (
          <Card className="p-4 rounded-2xl border-2 space-y-3">
            <p className="font-extrabold text-sm">ଶ୍ରେଣୀ ବାଛନ୍ତୁ ({selectedClassIds.length}/{maxClasses})</p>
            <div className="grid grid-cols-3 gap-1.5">
              {classes.map(c => {
                const sel = selectedClassIds.includes(c.id)
                return (
                  <button key={c.id} onClick={() => {
                    if (sel) setSelectedClassIds(selectedClassIds.filter(x => x !== c.id))
                    else if (selectedClassIds.length < maxClasses) setSelectedClassIds([...selectedClassIds, c.id])
                    else toast.info(`Max ${maxClasses} classes for ${classType}`)
                  }} className={`h-10 rounded-lg text-xs font-bold transition border ${sel ? 'bg-fuchsia-600 text-white border-fuchsia-600' : 'bg-background border-border'}`}>
                    {c.emoji} {c.name}
                  </button>
                )
              })}
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setSetupStep(1)} className="rounded-xl flex-1">← Back</Button>
              <Button disabled={!selectedClassIds.length} onClick={() => setSetupStep(3)} className="rounded-xl flex-1 bg-fuchsia-600 hover:bg-fuchsia-700">Next →</Button>
            </div>
          </Card>
        )}

        {/* Step 3: Weekly timetable builder */}
        {setupStep === 3 && (
          <Card className="p-3 rounded-2xl border-2 space-y-3">
            <div className="flex items-center justify-between">
              <p className="font-extrabold text-sm">📚 ସାପ୍ତାହିକ ସମୟ ସାରଣୀ</p>
              <Button size="sm" variant="outline" className="rounded-full text-[10px] h-7" onClick={() => copyDayToAll(activeDay)}><Copy className="w-3 h-3 mr-1" /> Copy to all days</Button>
            </div>

            {/* 💡 One-time setup hint · reassures the teacher they only need
                to fill one day (typically Monday). Mon-Sat auto-mirrors on save. */}
            <div className="rounded-xl bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-950/30 dark:to-orange-950/30 border border-amber-200 dark:border-amber-800 p-2.5">
              <p className="text-[11px] font-bold text-amber-900 dark:text-amber-100 leading-snug">
                ⚡ ONE-TIME setup · Fill Monday and Save
              </p>
              <p className="text-[10px] text-amber-800 dark:text-amber-200 mt-0.5 leading-snug">
                We'll auto-apply the same template to Tue–Sat. Sunday stays No School. Lessons progress week-by-week automatically 🎯
              </p>
            </div>

            <div className="flex gap-1 overflow-x-auto scroll-hide -mx-1 px-1">
              {[1, 2, 3, 4, 5, 6].map(d => (
                <button key={d} onClick={() => { ensureDayPeriods(d); setActiveDay(d) }} className={`shrink-0 px-3 h-9 rounded-lg text-xs font-bold border-2 transition ${activeDay === d ? 'bg-fuchsia-600 text-white border-fuchsia-600' : 'border-border bg-background'}`}>
                  {DAY_NAMES_OD[d].slice(0, 3)}<br /><span className="text-[8px] opacity-80">{DAY_NAMES_EN[d].slice(0, 3)}</span>
                </button>
              ))}
            </div>
            <div className="space-y-2">
              {(weekly[activeDay] && weekly[activeDay].length > 0 ? weekly[activeDay] : ensureDayPeriods(activeDay)).map((p, idx) => (
                <Card key={idx} className="p-2 rounded-xl border bg-muted/30">
                  <div className="flex items-center gap-2 mb-1.5">
                    <Badge className="bg-fuchsia-600 text-white text-[10px]">P{idx + 1}</Badge>
                    <Input value={p.time || ''} onChange={(e) => updateDayPeriod(activeDay, idx, { time: e.target.value })} className="h-7 rounded-md text-[11px] w-32" placeholder="HH:MM-HH:MM" />
                  </div>
                  <PeriodRowPicker value={p} onChange={(np) => updateDayPeriod(activeDay, idx, np)} classes={classes} classIds={selectedClassIds} />
                </Card>
              ))}
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setSetupStep(2)} className="rounded-xl flex-1">← Back</Button>
              <Button onClick={() => setSetupStep(4)} className="rounded-xl flex-1 bg-fuchsia-600 hover:bg-fuchsia-700">Next →</Button>
            </div>
          </Card>
        )}

        {/* Step 4: Save */}
        {setupStep === 4 && (
          <Card className="p-4 rounded-2xl border-2 space-y-3">
            <p className="font-extrabold text-sm">💾 ସମୟ ସାରଣୀ ସଂରକ୍ଷଣ କରନ୍ତୁ</p>
            <p className="text-[11px] text-muted-foreground">{Object.values(weekly).flat().filter(p => p?.lessonId).length} periods configured across {Object.entries(weekly).filter(([k, v]) => v?.length).length} days.</p>
            <div className="rounded-xl bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-emerald-950/30 dark:to-teal-950/30 border border-emerald-200 dark:border-emerald-800 p-2.5">
              <p className="text-[11px] font-bold text-emerald-900 dark:text-emerald-100">✨ What happens after Save?</p>
              <ul className="text-[10px] text-emerald-800 dark:text-emerald-200 mt-1 space-y-0.5 list-disc pl-4">
                <li>Mon-Sat template auto-mirrored to any empty days</li>
                <li>Sunday stays No School (never inherits)</li>
                <li>Lessons auto-progress week-by-week for the whole year</li>
                <li>No re-configuration needed for Week 2, 3, 10, 52…</li>
              </ul>
            </div>
            <p className="text-[10px] text-amber-700 dark:text-amber-300">💡 Tip: ସମ୍ପୂର୍ଣ୍ଣ Setup Optional — ଆପଣ ପରେ ବି Edit କରିପାରିବେ।</p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setSetupStep(3)} className="rounded-xl flex-1">← Back</Button>
              <Button onClick={saveSetup} className="rounded-xl flex-1 bg-gradient-to-r from-emerald-600 to-teal-600 font-bold">💾 ସମୟ ସାରଣୀ ସଂରକ୍ଷଣ କରନ୍ତୁ</Button>
            </div>
          </Card>
        )}
      </div>
    )
  }

  // ----- DAILY MODE -----
  return (
    <div className="space-y-3 pb-24 px-2">
      <TopBar title="📅 ତୁରନ୍ତ ଦୈନିକ ଶିକ୍ଷଣ ଯୋଜନା" onBack={() => go('dashboard')} />

      {/* ✅ ANNUAL PLAN ACTIVE · Reassures the teacher that setup is a one-time
          action; the weekly template auto-repeats Mon-Sat for the whole year.
          Also exposes ⚙ Edit Weekly Timetable (jumps back to setup step 3). */}
      {timetable?.setupComplete && (
        <Card className="p-3 rounded-2xl border-2 bg-gradient-to-br from-emerald-50 via-teal-50 to-cyan-50 dark:from-emerald-950/40 dark:via-teal-950/40 dark:to-cyan-950/40 border-emerald-200 dark:border-emerald-800">
          <div className="flex items-start gap-2">
            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-emerald-500 to-teal-600 text-white flex items-center justify-center shrink-0 shadow">✅</div>
            <div className="flex-1 min-w-0">
              <p className="font-black text-[13px] leading-tight text-emerald-900 dark:text-emerald-100">Annual Plan Active · One-Time Setup Complete</p>
              <p className="text-[10px] text-emerald-800 dark:text-emerald-200 mt-0.5 leading-snug">
                Weekly template auto-repeats every Mon–Sat. Sundays are No School. Lessons progress week-by-week automatically — no re-setup needed 🎯
              </p>
              <div className="flex gap-1.5 mt-2 flex-wrap">
                <Badge className="bg-emerald-500/15 text-emerald-800 dark:text-emerald-200 border border-emerald-300 text-[9px] h-5 px-2">🔄 Auto Progression</Badge>
                <Badge className="bg-sky-500/15 text-sky-800 dark:text-sky-200 border border-sky-300 text-[9px] h-5 px-2">🛌 Sunday · No School</Badge>
                {timetable?.mirroredFromDay && (
                  <Badge className="bg-fuchsia-500/15 text-fuchsia-800 dark:text-fuchsia-200 border border-fuchsia-300 text-[9px] h-5 px-2">🔁 Mirrored from {DAY_NAMES_OD[timetable.mirroredFromDay]}</Badge>
                )}
              </div>
            </div>
            <Button
              size="sm"
              variant="outline"
              className="h-8 rounded-lg text-[10px] shrink-0"
              onClick={() => {
                if (confirm('⚙ Edit Weekly Template\n\nChanges will apply from the NEXT future week onwards. Previous & current plans stay unchanged. Continue?')) {
                  setMode('setup'); setSetupStep(3); setActiveDay(1)
                }
              }}
              title="Edit weekly template (applies to future weeks only)"
            >
              <Edit className="w-3 h-3 mr-1" /> Edit
            </Button>
          </div>
        </Card>
      )}

      {/* Date + Day picker — always defaults to today's date.  A subtle "Today" badge
          reminds the teacher of the current calendar day; tapping the calendar icon
          snaps the date back to today after any manual override. */}
      <Card className="p-3 rounded-2xl border-2 space-y-2">
        <div className="flex items-center justify-between gap-2">
          <div className="flex-1">
            <div className="flex items-center justify-between mb-1">
              <Label className="text-[11px] font-bold">📅 ତାରିଖ ବାଛନ୍ତୁ</Label>
              {selectedDate !== (new Date().toISOString().slice(0, 10)) && (
                <button
                  onClick={() => setSelectedDate(new Date().toISOString().slice(0, 10))}
                  className="text-[10px] font-bold text-fuchsia-600 dark:text-fuchsia-300 underline"
                  title="Snap to today"
                >↺ Today</button>
              )}
            </div>
            <Input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} className="h-10 rounded-lg text-sm" />
            <p className="text-[10px] text-muted-foreground mt-1">
              🗓️ ଆଜିର ତାରିଖ : <span className="font-bold text-foreground">{new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric' })}</span>
            </p>
          </div>
          <div>
            <Label className="text-[11px] font-bold">📆 ବାର</Label>
            <p className="h-10 rounded-lg bg-muted px-2 flex items-center text-xs font-bold mt-1">{DAY_NAMES_OD[weekday]}</p>
          </div>
        </div>
        <div>
          <Label className="text-[11px] font-bold">🏫 ବିଦ୍ୟାଳୟ ନାମ (ଐଚ୍ଛିକ)</Label>
          <Input value={schoolName} onChange={(e) => setSchoolName(e.target.value)} placeholder="School name for printout" className="h-9 rounded-lg text-sm mt-1" />
        </div>
        <div className="grid grid-cols-2 gap-2 pt-1">
          <button onClick={() => toggleHoliday(false)} className={`p-2 rounded-lg border-2 transition text-xs font-bold ${dayType === 'working' ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-950/30' : 'border-transparent bg-muted'}`}>📚 Working Day · କାର୍ଯ୍ୟଦିବସ</button>
          <button onClick={() => toggleHoliday(true)} className={`p-2 rounded-lg border-2 transition text-xs font-bold ${dayType === 'holiday' ? 'border-rose-500 bg-rose-50 dark:bg-rose-950/30' : 'border-transparent bg-muted'}`}>🎉 Holiday · ଛୁଟି ଦିନ</button>
        </div>
      </Card>

      {/* Holiday view */}
      {dayType === 'holiday' && (
        <Card className="p-6 rounded-2xl border-2 bg-gradient-to-br from-rose-50 to-pink-50 dark:from-rose-950/30 dark:to-pink-950/30 border-rose-200 dark:border-rose-800 text-center">
          <p className="text-5xl">🎉</p>
          <p className="font-extrabold text-lg mt-2">ଆଜି ଛୁଟି ଦିନ</p>
          <p className="text-xs text-muted-foreground mt-1">No lesson plan generation for this date.</p>
          <p className="text-[10px] text-muted-foreground mt-2">{DAY_NAMES_OD[weekday]} · {new Date(selectedDate + 'T00:00:00').toLocaleDateString('en-IN')}</p>
          <Button onClick={() => toggleHoliday(false)} variant="outline" className="mt-4 rounded-xl">↺ Mark as Working Day</Button>
        </Card>
      )}

      {/* Working day: today's timetable */}
      {dayType === 'working' && (
        <>
          <Card className="p-3 rounded-2xl border-2">
            <div className="flex items-center justify-between mb-2">
              <div>
                <p className="font-extrabold text-sm">📖 ଆଜିର ସମୟ ସାରଣୀ</p>
                <p className="text-[10px] text-muted-foreground">{weekday === 6 ? '🏫 Saturday timings' : '🏫 Weekday timings'} (Period times shown · editable)</p>
              </div>
              <div className="flex gap-1.5">
                <Button size="sm" variant="outline" onClick={resetTimingsToStandard} className="rounded-full h-7 text-[10px]" title="Reset to school standard timings"><RefreshCw className="w-3 h-3 mr-1" /> Reset Times</Button>
                <Badge variant="outline" className="text-[10px]">{todaysPeriods.length} periods</Badge>
              </div>
            </div>
            {weekday === 0 ? (
              /* 🛌 Sunday · Always empty by default (No School).
                 Never inherits Monday's template. If the school runs on a
                 specific Sunday, mark that date as a Working Day override. */
              <div className="text-center py-6 bg-gradient-to-br from-sky-50 to-indigo-50 dark:from-sky-950/30 dark:to-indigo-950/30 border-2 border-dashed border-sky-200 dark:border-sky-800 rounded-xl">
                <p className="text-4xl">🛌</p>
                <p className="font-extrabold text-base mt-1">Sunday · No School</p>
                <p className="text-[11px] text-muted-foreground mt-1">ରବିବାର · ବିଦ୍ୟାଳୟ ବନ୍ଦ</p>
                <p className="text-[10px] text-muted-foreground mt-2 max-w-[280px] mx-auto">
                  Weekly template does not apply on Sundays. Pick another date to continue.
                </p>
              </div>
            ) : todaysPeriods.length === 0 ? (
              <div className="text-center py-6">
                <p className="text-xs text-muted-foreground mb-2">Applying your saved weekly template to {DAY_NAMES_OD[weekday]}…</p>
                <Button
                  onClick={async () => {
                    try {
                      const r = await api('/me/timetable/mirror-empty-days', { method: 'POST' })
                      if (r?.timetable) { setTimetable(r.timetable); setWeekly(r.timetable.weekly || {}) }
                      if (Array.isArray(r?.filledDays) && r.filledDays.length) {
                        toast.success(`✅ Weekly template applied to ${r.filledDays.length} day${r.filledDays.length > 1 ? 's' : ''}`)
                      } else {
                        // No source day at all → fall back to explicit configure
                        setMode('setup'); setSetupStep(3); setActiveDay(weekday)
                      }
                    } catch (e) { toast.error(e.message || 'Retry failed') }
                  }}
                  className="rounded-xl bg-fuchsia-600 h-10"
                >
                  <RefreshCw className="w-4 h-4 mr-1" /> Apply Weekly Template
                </Button>
                <p className="text-[10px] text-muted-foreground mt-2">Tip: The setup is one-time. Week 2, Week 3… use the same template automatically.</p>
              </div>
            ) : (
              <div className="space-y-2">
                {todaysPeriods.map((p, idx) => {
                  const cls = classes.find(c => c.id === p.classId)
                  const isEditing = editingPeriodIdx === idx
                  return (
                    <Card key={idx} className={`p-2 rounded-xl ${isEditing ? 'border-2 border-fuchsia-500' : 'border'}`}>
                      <div className="flex items-center gap-2">
                        <Badge className="bg-fuchsia-600 text-white text-[10px] shrink-0">P{p.periodNumber}</Badge>
                        <Input
                          value={p.time || ''}
                          onChange={(e) => setTodaysPeriods(arr => arr.map((x, i) => i === idx ? { ...x, time: e.target.value } : x))}
                          className="h-6 px-1.5 rounded-md text-[10px] w-24 shrink-0 font-mono"
                          title="Edit time for this period"
                        />
                        <p className="text-[11px] font-bold truncate flex-1">{cls?.emoji} {cls?.name || '—'}</p>
                        <Button size="icon" variant="ghost" onClick={() => setEditingPeriodIdx(isEditing ? null : idx)} className="h-7 w-7" title="Edit class/subject/chapter/lesson"><Edit className="w-3.5 h-3.5" /></Button>
                      </div>
                      {!isEditing ? (
                        <div className="text-[11px] text-muted-foreground mt-1 flex flex-wrap items-center gap-1.5">
                          {p.lessonId ? (
                            <>
                              <span className="text-emerald-600 font-bold">✓</span>
                              <span className="truncate flex-1">{lessonMeta[p.lessonId]?.title || 'Lesson selected'}</span>
                              {lessonMeta[p.lessonId]?.period && (
                                <Badge variant="outline" className="text-[9px] h-4 border-fuchsia-300 text-fuchsia-700 dark:text-fuchsia-300 shrink-0">
                                  P {lessonMeta[p.lessonId].period}{lessonMeta[p.lessonId].totalInChapter ? ` / ${lessonMeta[p.lessonId].totalInChapter}` : ''}
                                </Badge>
                              )}
                            </>
                          ) : <span className="text-amber-600">⚠ No lesson — tap ✏</span>}
                        </div>
                      ) : (
                        <div className="mt-2 space-y-2">
                          <PeriodRowPicker
                            value={p}
                            onChange={(np) => setTodaysPeriods(arr => arr.map((x, i) => i === idx ? { ...x, ...np } : x))}
                            classes={classes}
                            classIds={selectedClassIds}
                          />
                        </div>
                      )}
                    </Card>
                  )
                })}
                <label className="flex items-center gap-2 text-[11px] mt-2 cursor-pointer">
                  <input type="checkbox" checked={savePermanently} onChange={(e) => setSavePermanently(e.target.checked)} className="w-4 h-4" />
                  <span>☑ ସ୍ଥାୟୀ ଭାବେ ସମୟ ସାରଣୀ Update କରନ୍ତୁ (Save permanently to {DAY_NAMES_OD[weekday]})</span>
                </label>
              </div>
            )}
          </Card>

          {todaysPeriods.length > 0 && (
            <>
              {/* STEP 8: Activity Mode — exactly like the Daily 7-Period Plan generator */}
              <Card className="p-3 rounded-2xl space-y-2 border-2">
                <p className="text-xs font-extrabold flex items-center gap-1.5">
                  <span className="bg-fuchsia-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">8</span>
                  ଶିକ୍ଷଣ ଯୋଜନାରେ କେଉଁ କାର୍ଯ୍ୟ ଦେଖାଯିବ?
                </p>
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { v: 'teacher', l: 'କେବଳ ଶିକ୍ଷକ',   e: 'Teacher only' },
                    { v: 'student', l: 'କେବଳ ଶିକ୍ଷାର୍ଥୀ', e: 'Student only' },
                    { v: 'both',    l: 'ଉଭୟ',           e: 'Both' },
                  ].map(o => (
                    <button key={o.v} onClick={() => setActivityMode(o.v)} className={`p-2.5 rounded-xl text-center transition border-2 ${activityMode === o.v ? 'border-fuchsia-500 bg-fuchsia-50 dark:bg-fuchsia-950/30 text-fuchsia-700 dark:text-fuchsia-300' : 'border-transparent bg-muted/40'}`}>
                      <p className="text-xs font-bold">{o.l}</p>
                      <p className="text-[9px] text-muted-foreground mt-0.5">{o.e}</p>
                    </button>
                  ))}
                </div>
              </Card>

              {/* STEP 9: Layout Style */}
              <Card className="p-3 rounded-2xl space-y-2 border-2">
                <p className="text-xs font-extrabold flex items-center gap-1.5">
                  <span className="bg-fuchsia-500 text-white rounded-full w-5 h-5 inline-flex items-center justify-center text-[10px]">9</span>
                  ଶିକ୍ଷଣ ଯୋଜନା ଶୈଳୀ
                </p>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { v: 'detailed', l: 'ବିସ୍ତୃତ',  e: '1 period / page', icon: '📄' },
                    { v: 'compact',  l: 'ସଂକ୍ଷିପ୍ତ', e: '2 periods / page', icon: '📋' },
                  ].map(o => (
                    <button key={o.v} onClick={() => setLayoutStyle(o.v)} className={`p-3 rounded-xl text-center transition border-2 ${layoutStyle === o.v ? 'border-fuchsia-500 bg-fuchsia-50 dark:bg-fuchsia-950/30 text-fuchsia-700 dark:text-fuchsia-300' : 'border-transparent bg-muted/40'}`}>
                      <p className="text-xl">{o.icon}</p>
                      <p className="text-xs font-bold mt-0.5">{o.l}</p>
                      <p className="text-[9px] text-muted-foreground">{o.e}</p>
                    </button>
                  ))}
                </div>
              </Card>

              <Button onClick={generatePlan} className="w-full h-14 rounded-2xl bg-gradient-to-r from-fuchsia-600 to-purple-700 font-extrabold text-base shadow-lg">
                ✨ ଆଜିର ଶିକ୍ଷଣ ଯୋଜନା ପ୍ରସ୍ତୁତ କରନ୍ତୁ
              </Button>
              <p className="text-[10px] text-center text-muted-foreground -mt-2">
                🎯 ପ୍ରସ୍ତୁତ ହେଲା ପରେ, ଆଗାମୀ ଦିନ ପ୍ରତ୍ୟେକ ବିଷୟ ର <b>ପରବର୍ତ୍ତୀ ପିରିୟଡ</b> ସ୍ୱୟଂଚାଳିତ ଭାବେ ଲୋଡ୍ ହେବ।
              </p>
            </>
          )}

          <Button onClick={() => { setMode('setup'); setSetupStep(1) }} variant="outline" className="w-full rounded-xl text-xs">
            ⚙ Edit Weekly Timetable
          </Button>
        </>
      )}
    </div>
  )
}

// ===================== VISIT-TIME REFERRAL PROMPT =====================
// Shows a high-engagement modal with the logged-in user's OWN referral link.
// Settings (enabled, intervalHours, title/body/benefits/cta) are admin-controlled
// via /api/settings/public ("referralPrompt" object). Modal hides entirely when
// enabled=false. Re-shown after `intervalHours` (default 48h).
const ReferralPrompt = ({ user, view }) => {
  const [open, setOpen] = useState(false)
  const [data, setData] = useState(null)
  const [cfg, setCfg] = useState(null)
  const [v2on, setV2on] = useState(false)

  const hiddenViews = ['login', 'register', 'forgot', 'change-password', 'lesson-view', 'admin', 'ai-wallet']

  // Fetch the admin-configured prompt settings (refresh on user/view change so admins
  // can preview changes immediately after saving).
  useEffect(() => {
    api('/settings/public').then(s => { setCfg(s.referralPrompt || null); setV2on(!!s.referralPopupV2) }).catch(() => {})
  }, [user?.id])

  useEffect(() => {
    if (!user || !cfg) { setOpen(false); return }
    // Admin accounts skip the visit-time referral prompt (keeps admin/testing UI unblocked).
    if (user.role === 'admin') { setOpen(false); return }
    if (cfg.enabled === false) { setOpen(false); return }
    if (hiddenViews.includes(view)) return
    try {
      const intervalMs = Math.max(1, Number(cfg.intervalHours || 48)) * 60 * 60 * 1000
      const last = Number(localStorage.getItem('em_ref_prompt_at') || 0)
      const now = Date.now()
      if (now - last >= intervalMs) {
        const t = setTimeout(() => setOpen(true), 1400)
        return () => clearTimeout(t)
      }
    } catch {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id, view, cfg?.enabled, cfg?.intervalHours])

  useEffect(() => {
    if (!open) return
    api('/me/referral').then(setData).catch(() => {})
  }, [open])

  const markShown = () => {
    try { localStorage.setItem('em_ref_prompt_at', String(Date.now())) } catch {}
  }
  const dismiss = (snooze = true) => {
    if (snooze) markShown()
    setOpen(false)
  }
  const onCopy = async () => {
    if (!data?.link) return
    try { await navigator.clipboard.writeText(data.link); toast.success('Link copied! 📋 Now paste in your Teacher group.') }
    catch { toast.error('Copy failed') }
  }
  const onWhatsApp = () => {
    if (!data?.link) return
    const msg = (data.shareMessage || buildOdiaReferralMessage(data.link))
    const url = `https://api.whatsapp.com/send?text=${encodeURIComponent(msg)}`
    markShown()
    window.open(url, '_blank', 'noopener,noreferrer')
    setOpen(false)
  }
  const onNativeShare = async () => {
    if (!data?.link) return
    const msg = (data.shareMessage || buildOdiaReferralMessage(data.link))
    if (navigator.share) {
      try {
        await navigator.share({ title: 'Lesson Guru Odisha', text: msg, url: data.link })
        markShown()
        setOpen(false)
      } catch {}
    } else {
      onCopy()
    }
  }

  if (!open || !cfg) return null
  // Mutual exclusion with the V2 popup — never show BOTH (fixes double popup).
  if (v2on) return null
  const benefits = Array.isArray(cfg.benefits) ? cfg.benefits.filter(Boolean) : []
  const snoozeLine = String(cfg.snoozeText || 'Maybe Later — {hours} ଘଣ୍ଟା ପରେ ପୁଣି ଦେଖାଯିବ').replace('{hours}', String(cfg.intervalHours || 48))
  return (
    <div className="fixed inset-0 z-[60] bg-black/70 backdrop-blur-sm flex items-end sm:items-center justify-center p-3 animate-in fade-in" onClick={() => dismiss(true)}>
      <Card className="relative max-w-md w-full p-0 rounded-3xl overflow-hidden border-0 shadow-2xl bg-background" onClick={(e) => e.stopPropagation()}>
        <button onClick={() => dismiss(true)} aria-label="Close" className="absolute top-2 right-2 z-10 w-8 h-8 rounded-full bg-white/85 hover:bg-white text-zinc-700 flex items-center justify-center text-sm font-bold shadow">✕</button>

        <div className="relative bg-gradient-to-br from-orange-500 via-amber-500 to-teal-600 text-white p-5 pt-7">
          <div className="absolute -top-6 -right-6 text-8xl opacity-15 select-none">🎁</div>
          <div className="relative">
            {cfg.eyebrow && <p className="text-[10px] font-extrabold tracking-widest uppercase opacity-95">{cfg.eyebrow}</p>}
            <p className="text-xl font-extrabold mt-1 leading-tight">{cfg.title}</p>
            {cfg.body && <p className="text-[12px] opacity-95 mt-1.5 leading-snug whitespace-pre-line">{cfg.body}</p>}
          </div>
        </div>

        <div className="p-4 space-y-3">
          {benefits.length > 0 && (
            <div className="rounded-2xl bg-gradient-to-br from-emerald-50 to-teal-50 dark:from-emerald-950/30 dark:to-teal-950/30 border-2 border-emerald-200 dark:border-emerald-900 p-3 space-y-1.5">
              <p className="text-[12px] font-extrabold text-emerald-700 dark:text-emerald-300 flex items-center gap-1">🎁 Share କଲେ ଆପଣ ପାଇବେ:</p>
              <ul className="text-[11px] space-y-1 text-emerald-900 dark:text-emerald-200">
                {benefits.map((b, i) => <li key={i}>{b}</li>)}
              </ul>
            </div>
          )}

          {data ? (
            <div className="rounded-xl border-2 border-amber-300 bg-amber-50 dark:bg-amber-950/30 dark:border-amber-900 p-2.5">
              <p className="text-[10px] font-extrabold text-amber-700 dark:text-amber-300 uppercase tracking-wide">🔗 Your Personal Link</p>
              <p className="text-[12px] font-mono mt-1 truncate text-amber-900 dark:text-amber-200">{data.link}</p>
              {(data.totalInvited || 0) > 0 && (
                <p className="text-[10px] text-amber-700/80 dark:text-amber-300/80 mt-1">👥 ଏ ପର୍ଯ୍ୟନ୍ତ {data.totalInvited} ଜଣ ଶିକ୍ଷକ ଆପଣଙ୍କ Link ରୁ join କରିଛନ୍ତି ⭐</p>
              )}
            </div>
          ) : (
            <div className="flex items-center justify-center py-4"><Loader2 className="w-4 h-4 animate-spin text-muted-foreground" /></div>
          )}

          <Button onClick={onWhatsApp} disabled={!data?.link} className="w-full h-12 rounded-xl bg-[#25D366] hover:bg-[#1ebe57] text-white font-extrabold text-sm">
            <MessageCircle className="w-5 h-5 mr-1" /> {cfg.ctaText || 'Share Now'}
          </Button>
          <div className="grid grid-cols-2 gap-2">
            <Button onClick={onNativeShare} disabled={!data?.link} variant="outline" className="h-10 rounded-xl text-xs font-bold"><Share2 className="w-4 h-4 mr-1" /> More Apps…</Button>
            <Button onClick={onCopy} disabled={!data?.link} variant="outline" className="h-10 rounded-xl text-xs font-bold"><Copy className="w-4 h-4 mr-1" /> Copy Link</Button>
          </div>

          <button onClick={() => dismiss(true)} className="w-full text-center text-[11px] text-muted-foreground hover:text-foreground py-1">
            {snoozeLine}
          </button>
        </div>
      </Card>
    </div>
  )
}

// Dismissible top banner — appears when install is available, hidden after install or dismissal.
const InstallAppBanner = () => {
  const { canInstall, isIos, isStandalone, triggerInstall } = usePwaInstall()
  const [dismissed, setDismissed] = useState(false)
  const [showIosHelp, setShowIosHelp] = useState(false)
  useEffect(() => {
    if (typeof window === 'undefined') return
    setDismissed(localStorage.getItem('em_install_dismissed') === '1')
  }, [])
  const dismiss = () => { setDismissed(true); localStorage.setItem('em_install_dismissed', '1') }
  if (isStandalone || dismissed) return null
  if (!canInstall && !isIos) return null
  return (
    <>
      <div className="no-print sticky top-0 z-40 px-3 py-2 bg-gradient-to-r from-orange-500 via-amber-500 to-teal-600 text-white shadow-lg">
        <div className="max-w-screen-md mx-auto flex items-center gap-2">
          <span className="text-lg shrink-0">📲</span>
          <div className="flex-1 min-w-0">
            <p className="text-[12px] font-bold leading-tight truncate">Install Lesson Guru Odisha on your phone</p>
            <p className="text-[10px] opacity-90 truncate">by Teacher Utility Tool Kit · works offline · no Play Store</p>
          </div>
          <Button
            size="sm"
            onClick={async () => {
              if (isIos) { setShowIosHelp(true); return }
              const ok = await triggerInstall()
              if (!ok) toast.info('Install cancelled')
            }}
            className="h-8 px-3 rounded-full bg-white text-orange-700 hover:bg-white/90 font-extrabold text-xs shrink-0"
          >
            <Download className="w-3.5 h-3.5 mr-1" /> Install
          </Button>
          <Button size="icon" variant="ghost" onClick={dismiss} className="h-7 w-7 rounded-full text-white/90 hover:bg-white/10 shrink-0">✕</Button>
        </div>
      </div>
      {showIosHelp && <IosInstallHelp onClose={() => setShowIosHelp(false)} />}
    </>
  )
}

